window.RULES_DATA = [{"id":"R-ENTRY-01","cat":"entry_sign","catLabel":"合同签订","risk":"自用工之日起超过一个月未订立书面劳动合同","level":"auto","owner":"hr","module":"contract","enabled":true,"q":"","law":[{"ref":"《劳动合同法》第10条","text":"第10条　建立劳动关系，应当订立书面劳动合同。 已建立劳动关系，未同时订立书面劳动合同的，应当自用工之日起一个月内订立书面劳动合同。 用人单位与劳动者在用工前订立劳动合同的，劳动关系自用工之日起建立。"},{"ref":"《劳动合同法》第82条","text":"第82条　用人单位自用工之日起超过一个月不满一年未与劳动者订立书面劳动合同的，应当向劳动者每月支付二倍的工资。 用人单位违反本法规定不与劳动者订立无固定期限劳动合同的，自应当订立无固定期限劳动合同之日起向劳动者每月支付二倍的工资。"}],"consequence":"面临支付二倍工资（最长 11 个月），且难以举证劳动关系具体内容","remedy":["用工一个月内完成签约","对已超期人员立即补签并留存补签说明","核算二倍工资敞口"],"sev":"高"},{"id":"R-ENTRY-02","cat":"entry_sign","catLabel":"合同签订","risk":"约定的试用期超过法定上限","level":"auto","owner":"hr","module":"contract","enabled":true,"q":"","law":[{"ref":"《劳动合同法》第19条","text":"第19条　劳动合同期限三个月以上不满一年的，试用期不得超过一个月；劳动合同期限一年以上不满三年的，试用期不得超过二个月；三年以上固定期限和无固定期限的劳动合同，试用期不得超过六个月。 同一用人单位与同一劳动者只能约定一次试用期。 以完成一定工作任务为期限的劳动合同或者劳动合同期限不满三个月的，不得约定试用期。 试用期包含在劳动合同期限内。劳动合同仅约定试用期的，试用期不成立，该期限为劳动合同期限。"}],"consequence":"由劳动行政部门责令改正；违法约定的试用期已经履行的，按已履行超过法定试用期的期间支付赔偿金","remedy":["按合同期限重新核定试用期","已超期履行的依法支付赔偿金"],"sev":"高"},{"id":"R-ENTRY-03","cat":"entry_renew","catLabel":"合同续订","risk":"劳动合同即将到期（30 天内）","level":"auto","owner":"hr","module":"contract","enabled":true,"q":"","law":[{"ref":"《劳动合同法》第14条","text":"第14条　无固定期限劳动合同，是指用人单位与劳动者约定无确定终止时间的劳动合同。 用人单位与劳动者协商一致，可以订立无固定期限劳动合同。有下列情形之一，劳动者提出或者同意续订、订立劳动合同的，除劳动者提出订立固定期限劳动合同外，应当订立无固定期限劳动合同： （一）劳动者在该用人单位连续工作满十年的； （二）用人单位初次实行劳动合同制度或者国有企业改制重新订立劳动合同时，劳动者在该用人单位连续工作满十年且距法定退休年龄不足十年的； （三）连续订立二次固定期限劳动合同，且劳动者没有本法第三十九条和第四十条第一项、第二项规定的情形，续订劳动合同的。 用人单位自用工之日起满一年不与劳动者订立书面劳动合同的，视为用人单位与劳动者已订立无固定期限劳动合同。"}],"consequence":"期满未续签继续用工的，形成事实劳动关系，同样面临二倍工资风险","remedy":["确认是否续签并提前完成手续","不续签的依法支付经济补偿并办理终止手续"],"sev":"高"},{"id":"R-ENTRY-04","cat":"entry_renew","catLabel":"合同续订","risk":"连续订立二次固定期限合同后，仍未订立无固定期限合同","level":"auto","owner":"hr","module":"contract","enabled":true,"q":"","law":[{"ref":"《劳动合同法》第14条","text":"第14条　无固定期限劳动合同，是指用人单位与劳动者约定无确定终止时间的劳动合同。 用人单位与劳动者协商一致，可以订立无固定期限劳动合同。有下列情形之一，劳动者提出或者同意续订、订立劳动合同的，除劳动者提出订立固定期限劳动合同外，应当订立无固定期限劳动合同： （一）劳动者在该用人单位连续工作满十年的； （二）用人单位初次实行劳动合同制度或者国有企业改制重新订立劳动合同时，劳动者在该用人单位连续工作满十年且距法定退休年龄不足十年的； （三）连续订立二次固定期限劳动合同，且劳动者没有本法第三十九条和第四十条第一项、第二项规定的情形，续订劳动合同的。 用人单位自用工之日起满一年不与劳动者订立书面劳动合同的，视为用人单位与劳动者已订立无固定期限劳动合同。"}],"consequence":"劳动者有权要求订立无固定期限劳动合同","remedy":["核对续签次数","符合条件的改为无固定期限合同"],"sev":"高"},{"id":"R-HOURS-01","cat":"entry_hours","catLabel":"工时","risk":"月加班超过 36 小时","level":"auto","owner":"approver","module":"attendance","enabled":true,"q":"","law":[{"ref":"《劳动法》第41条","text":"第41条　用人单位由于生产经���需要，经与工会和劳动者协商后可以延长工作时间，一般每日不得超过一小时；因特殊原因需要延长工作时间的，在保障劳动者身体健康的条件下延长工作时间每日不得超过三小时，但是每月不得超过三十六小时。"}],"consequence":"由劳动行政部门给予警告、责令改正，并可处以罚款","remedy":["调整排班，控制月加班在 36 小时内","确需延长的依法支付加班费并保障健康"],"sev":"高"},{"id":"R-WAGE-01","cat":"entry_wage","catLabel":"工资","risk":"月工资低于当地最低工资标准","level":"auto","owner":"hr","module":"payroll","enabled":true,"q":"","law":[{"ref":"《劳动法》第48条","text":"第48条　国家实行最低工资保障制度。最低工资的具体标准由省、自治区、直辖市人民政府规定，报国务院备案。 用人单位支付劳动者的工资不得低于当地最低工资标准。"}],"consequence":"由劳动行政部门责令支付差额部分；逾期不支付的，责令加付赔偿金","remedy":["核对当地最低工资标准","补足差额并调整工资结构"],"sev":"高"},{"id":"R-WAGE-02","cat":"entry_wage","catLabel":"工资","risk":"存在加班但未计发加班费","level":"auto","owner":"hr","module":"payroll","enabled":true,"q":"","law":[{"ref":"《劳动法》第44条","text":"第44条　有下列情形之一的，用人单位应当按照下列标准支付高于劳动者正常工作时间工资的工资报酬： （一）安排劳动者延长工作时间的，支付不低于工资的百分之一百五十的工资报酬； （二）休息日安排劳动者工作又不能安排补休的，支付不低于工资的百分之二百的工资报酬； （三）法定休假日安排劳动者工作的，支付不低于工资的百分之三百的工资报酬。"}],"consequence":"劳动者可主张补发加班费，存在集体争议风险","remedy":["按 150% / 200% / 300% 补发加班费","规范加班审批与记录"],"sev":"高"},{"id":"R-SOCIAL-01","cat":"entry_welfare","catLabel":"法定福利","risk":"未依法为劳动者缴纳社会保险","level":"auto","owner":"hr","module":"social","enabled":true,"q":"","law":[{"ref":"《社会保险法》第58条","text":"第58条　用人单位应当自用工之日起三十日内为其职工向社会保险经办机构申请办理社会保险登记。未办理社会保险登记的，由社会保险经办机构核定其应当缴纳的社会保险费。 自愿参加社会保险的无雇工的个体工商户、未在用人单位参加社会保险的非全日制从业人员以及其他灵活就业人员，应当向社会保险经办机构申请办理社会保险登记。 国家建立全国统一的个人社会保障号码。个人社会保障号码为公民身份号码。"}],"consequence":"由征收机构责令限期缴纳或补足，并自欠缴之日起加收滞纳金；逾期不缴的处罚款","remedy":["补办参保登记","核算欠缴金额与滞纳金"],"sev":"高"},{"id":"R-LEAVE-01","cat":"leave_end","catLabel":"合同终止","risk":"离职未出具解除或终止劳动合同证明","level":"auto","owner":"hr","module":"staff","enabled":true,"q":"","law":[{"ref":"《劳动合同法》第50条","text":"第50条　用人单位应当在解除或者终止劳动合同时出具解除或者终止劳动合同的证明，并在十五日内为劳动者办理档案和社会保险关系转移手续。 劳动者应当按照双方约定，办理工作交接。用人单位依照本法有关规定应当向劳动者支付经济补偿的，在办结工作交接时支付。 用人单位对已经解除或者终止的劳动合同的文本，至少保存二年备查。"}],"consequence":"由劳动行政部门责令改正；给劳动者造成损害的，应当承担赔偿责任","remedy":["补开离职证明","15 日内办理档案与社保转移"],"sev":"高"},{"id":"R-PROB-01","cat":"probation","catLabel":"试用期","risk":"试用期工资低于本单位相同岗位最低档工资或合同约定工资的 80%","level":"auto","owner":"hr","module":"payroll","enabled":true,"q":"","law":[{"ref":"《劳动合同法》第20条","text":"第20条　劳动者在试用期的工资不得低于本单位相同岗位最低档工资或者劳动合同约定工资的百分之八十，并不得低于用人单位所在地的最低工资标准。"}],"consequence":"由劳动行政部门责令支付差额部分","remedy":["按不低于 80% 补足试用期工资"],"sev":"高"},{"id":"R-SYSTEM-01","cat":"entry_perform","catLabel":"合同履行","risk":"规章制度未经职工代表大会或全体职工讨论、未向劳动者公示","level":"ask","owner":"legal","module":"riskconfirm","enabled":true,"q":"涉及报酬、工时、休假、劳动纪律等切身利益的规章制度，是否经职工代表大会或全体职工讨论、与工会或职工代表平等协商确定，并已公示或告知劳动者？","law":[{"ref":"《劳动合同法》第4条","text":"第4条　用人单位应当依法建立和完善劳动规章制度，保障劳动者享有劳动权利、履行劳动义务。 用人单位在制定、修改或者决定有关劳动报酬、工作时间、休息休假、劳动安全卫生、保险福利、职工培训、劳动纪律以及劳动定额管理等直接涉及劳动者切身利益的规章制度或者重大事项时，应当经职工代表大会或者全体职工讨论，提出方案和意见，与工会或者职工代表平等协商确定。 在规章制度和重大事项决定实施过程中，工会或者职工认为不适当的，有权向用人单位提出，通过协商予以修改完善。 用人单位应当将直接涉及劳动者切身利益的规章制度和重大事项决定公示，或者告知劳动者。"}],"consequence":"依据未经民主程序制定并公示的规章制度作出的处理，可能不被采信","remedy":["补走民主程序并留存会议记录","组织员工签收并留痕"],"sev":"中"},{"id":"R-SPECIAL-01","cat":"special_dispatch","catLabel":"劳务派遣","risk":"劳务派遣用工比例或岗位不符合\"三性\"要求","level":"hybrid","owner":"legal","module":"riskconfirm","enabled":true,"q":"劳务派遣用工是否只用在临时性（存续不超过6个月）、辅助性、替代性岗位上，且派遣用工数量不超过用工总量的10%？","law":[{"ref":"《劳动合同法》第66条","text":"第66条　劳动合同用工是我国的企业基本用工形式。劳务派遣用工是补充形式，只能在临时性、辅助性或者替代性的工作岗位上实施。 前款规定的临时性工作岗位是指存续时间不超过六个月的岗位；辅助性工作岗位是指为主营业务岗位提供服务的非主营业务岗位；替代性工作岗位是指用工单位的劳动者因脱产学习、休假等原因无法工作的一定期间内，可以由其他劳动者替代工作的岗位。 用工单位应当严格控制劳务派遣用工数量，不得超过其用工总量的一定比例，具体比例由国务院劳动行政部门规定。"},{"ref":"《劳务派遣暂行规定》第4条","text":"第4条　用工单位应当严格控制劳务派遣用工数量，使用的被派遣劳动者数量不得超过其用工总量的10%。 前款所称用工总量是指用工单位订立劳动合同人数与使用的被派遣劳动者人数之和。 计算劳务派遣用工比例的用工单位是指依照劳动合同法和劳动合同法实施条例可以与劳动者订立劳动合同的用人单位。"}],"consequence":"由劳动行政部门责令限期改正；逾期不改正的处以罚款","remedy":["核查派遣岗位是否符合三性","核查派遣用工比例"],"sev":"中"},{"id":"R-RECRUIT-01","cat":"recruit","catLabel":"招聘","risk":"招用人员未核查年龄，误招不满16周岁童工","level":"ask","owner":"hr","module":"staff","enabled":true,"q":"招用人员时是否核查身份证并确认其已满16周岁？","law":[{"ref":"《禁止使用童工规定》第2、4条","text":"第2条　国家机关、社会团体 、企业事业单位、民办非企业单位或者个体工商户（以下统称用人单位）均不得招用不满１６周岁的未成年人（招用不满１６周岁的未成年人，以下统称使用童工）。 禁止任何单位或者个人为不满１６周岁的未成年人介绍就业。 禁止不满１６周岁的未成年人开业从事个体经营活动。\n第4条　用人单位招用人员时，必须核查被招用人员的身份证；对不满１６周岁的未成年人，一律不得录用。用人单位录用人员的录用登记、核查材料应当妥善保管。"}],"consequence":"每使用一名童工每月处5000元罚款，并责令限期送回；文艺体育单位招专业工作者须监护人同意（第13条例外）","remedy":["规范招聘流程：核验身份证件（禁招不满16周岁童工）；不扣押证件、不收押金/保证金；招用简章必备法定内容；如实告知职业危害、安全生产状况与劳动报酬；录用前核实候选人已与原单位解除/终止劳动关系。"],"sev":"高"},{"id":"R-RECRUIT-02","cat":"recruit","catLabel":"招聘","risk":"扣押劳动者居民身份证或其他证件，或要求提供担保、以其他名义收取财物（押金/保证金）","level":"ask","owner":"hr","module":"staff","enabled":true,"q":"贵司是否扣押员工证件或收取任何形式的押金、保证金、担保？","law":[{"ref":"《劳动合同法》第9、84条","text":"第9条　用人单位招用劳动者，不得���押劳动者的居民身份证和其他证件，不得要求劳动者提供担保或者以其他名义向劳动者收取财物。\n第84条　用人单位违反本法规定，扣押劳动者居民身份证等证件的，由劳动行政部门责令限期退还劳动者本人，并依照有关法律规定给予处罚。 用人单位违反本法规定，以担保或者其他名义向劳动者收取财物的，由劳动行政部门责令限期退还劳动者本人，并以每人五百元以上二千元以下的标准处以罚款；给劳动者造成损害的，应当承担赔偿责任。 劳动者依法解除或者终止劳动合同，用人单位扣押劳���者档案或者其他物品的，依照前款规定处罚。"},{"ref":"《就业服务与就业管理规定》第14条","text":"第14条　用人单位招用人员不得有下列行为： （一）提供虚假招聘信息，发布虚假招聘广告； （二）扣押被录用人员的居民身份证和其他证件； （三）以担保或者其他名义向劳动者收取财物； （四）招用未满16周岁的未成年人以及国家法律、行政法规规定不得招用的其他人员； （五）招用无合法身份证件的人员； （六）以招用人员为名牟取不正当利益或进行其他违法活动。"}],"consequence":"责令退还，按每人500–2000元罚款；造成损害的承担赔偿责任","remedy":["规范招聘流程：核验身份证件（禁招不满16周岁童工）；不扣押证件、不收押金/保证金；招用简章必备法定内容；如实告知职业危害、安全生产状况与劳动报酬；录用前核实候选人已与原单位解除/终止劳动关系。"],"sev":"高"},{"id":"R-RECRUIT-03","cat":"recruit","catLabel":"招聘","risk":"招聘中存在就业歧视（性别、民族、残疾、传染病病原携带、农村户籍等）","level":"ask","owner":"hr","module":"staff","enabled":true,"q":"招聘简章与录用条件中是否含有歧视性内容，或实际操作中对上述群体差别对待？","law":[{"ref":"《就业促进法》第3、26、27、28、29、30、31、62条","text":"第3条　劳动者依法享有平等就业和自主择业的权利。 劳动者就业，不因民族、种族、性别、宗教信仰等不同而受歧视。\n第26条　用人单位招用人员、职业中介机构从事职业中介活动，应当向劳动者提供平等的就业机会和公平的就业条件，不得实施就业歧视。\n第27条　国家保障妇女享有与男子平等的劳动权利。 用人单位招用人员，除国家规定的不适合妇女的工种或者岗位外，不得以性别为由拒绝录用妇女或者提高对妇女的录用标准。 用人单位录用女职工，不得在劳动合同中规定限制女职工结婚、生育的内容。\n第28条　各民族劳动者享有平等的劳动权利。 用人单位招用人员，应当依法对少数民族劳动者给予适当照顾。\n第29条　国家保障残疾人的劳动权利。 各级人民政府应当对残疾人就业统筹规划，为残疾人创造就业条件。 用人单位招用人员，不得歧视残疾人。\n第30条　用人单位招用人员，不得以是传染病病原携带者为由拒绝录用。但是，经医学鉴定传染病病原携带者在治愈前或者排除传染嫌疑前，不得从事法律、行政法规和国务院卫生行政部门规定禁止从事的易使传染病扩散的工作。\n第31条　农村劳动者进城就业享有与城镇劳动者平等的劳动权利，不得对农村劳动者进城就业设置歧视性限制。\n第62条　违反本法规定，实施就业歧视的，劳动者可以向人民法院提起诉讼。"},{"ref":"《就业服务与就业管理规定》第4、5、16、17、18、19、20条","text":"第4条　劳动者依法享有平等就业的权利。劳动者就业，不因民族、种族、性别、宗教信仰等不同而受歧视。\n第5条　农村劳动者进城就业享有与城镇劳动者平等的就业权利，不得对农村劳动者进城就业设置歧视性限制。\n第16条　用人单位在招用人员时，除国家规定的不适合妇女从事的工种或者岗位外，不得以性别为由拒绝录用妇女或者提高对妇女的录用标准。 用人单位录用女职工，不得在劳动合同中规定限制女职工结婚、生育的内容。\n第17条　用人单位招用人员，应当依法对少数民族劳动者给予适当照顾。\n第18条　用人单位招用人员，不得歧视残疾人。\n第19条　用人单位招用人员，不得以是传染病病原携带者为由拒绝录用。但是，经医学鉴定传染病病原携带者在治愈前或者排除传染嫌疑前，不得从事法律、行政法规和国务院卫生行政部门规定禁止从事的易使传染病扩散的工作。 用人单位招用人员，除国家法律、行政法规和国务院卫生行政部门规定禁止乙肝病原携带者从事的工作外，不得强行将乙肝病毒血清学指标作为体检标准。\n第20条　用人单位发布的招用人员简章或招聘广告，不得包含歧视性内容。"}],"consequence":"劳动者可向人民法院提起诉讼；造成损害的承担赔偿责任","remedy":["规范招聘流程：核验身份证件（禁招不满16周岁童工）；不扣押证件、不收押金/保证金；招用简章必备法定内容；如实告知职业危害、安全生产状况与劳动报酬；录用前核实候选人已与原单位解除/终止劳动关系。"],"sev":"中"},{"id":"R-RECRUIT-04","cat":"recruit","catLabel":"招聘","risk":"招用时未如实告知工作内容、工作条件、职业危害、安全生产状况、劳动报酬等","level":"ask","owner":"hr","module":"staff","enabled":true,"q":"招用员工时是否书面如实告知职业危害、安全生产状况及劳动报酬？","law":[{"ref":"《劳动合同法》第8条","text":"第8条　用人单位招用劳动者时，应当如实告知劳动者工作内容、工作条件、工作地点、职业危害、安全生产状况、劳动报酬，以及劳动者要求了解的其他情况；用人单位有权了解劳动者与劳动合同直接相关的基本情况，劳动者应当如实说明。"},{"ref":"《就业服务与就业管理规定》第12条","text":"第12条　用人单位招用人员时，应当依法如实告知劳动者有关工作内容、工作条件、工作地点、职业危害、安全生产状况、劳动报酬以及劳动者要求了解的其他情况。 用人单位应当根据劳动者的要求，及时向其反馈是否录用的情况。"}],"consequence":"劳动者可据此即时解除劳动合同并要求经济补偿（劳动合同法第38、46条）","remedy":["规范招聘流程：核验身份证件（禁招不满16周岁童工）；不扣押证件、不收押金/保证金；招用简章必备法定内容；如实告知职业危害、安全生产状况与劳动报酬；录用前核实候选人已与原单位解除/终止劳动关系。"],"sev":"中"},{"id":"R-RECRUIT-05","cat":"recruit","catLabel":"招聘","risk":"招用尚未与其他用人单位解除/终止劳动合同的劳动者，致原单位损失","level":"ask","owner":"hr","module":"staff","enabled":true,"q":"录用前是否核实候选人已与原单位解除或终止劳动关系？","law":[{"ref":"《劳动合同法》第91条","text":"第91条　用人单位招用与其他用人单位尚未解除或者终止劳动合同的劳动者，给其他用人单位造成损失的，应当承担连带赔偿责任。"}],"consequence":"对原用人单位造成损失的，承担连带赔偿责任","remedy":["规范招聘流程：核验身份证件（禁招不满16周岁童工）；不扣押证件、不收押金/保证金；招用简章必备法定内容；如实告知职业危害、安全生产状况与劳动报酬；录用前核实候选人已与原单位解除/终止劳动关系。"],"sev":"中"},{"id":"R-RECRUIT-06","cat":"recruit","catLabel":"招聘","risk":"招用简章内容不全（缺工作内容、人数、条件、劳动报酬、福利、社保等）","level":"ask","owner":"hr","module":"staff","enabled":true,"q":"对外发布的招用简章是否包含法定必备内容？","law":[{"ref":"《就业服务与就业管理规定》第11条","text":"第11条　用人单位委托公共就业服务机构或职业中介机构招用人员，或者参加招聘洽谈会时，应当提供招用人员简章，并出示营业执照（副本）或者有关部门批准其设立的文件、经办人的身份证件和受用人单位委托的证明。 招用人员简章应当包括用人单位基本情况、招用人数、工作内容、招录条件、劳动报酬、福利待遇、社会保险等内容，以及法律、法规规定的其他内容。"}],"consequence":"由劳动保障行政部门责令改正，可处罚款","remedy":["规范招聘流程：核验身份证件（禁招不满16周岁童工）；不扣押证件、不收押金/保证金；招用简章必备法定内容；如实告知职业危害、安全生产状况与劳动报酬；录用前核实候选人已与原单位解除/终止劳动关系。"],"sev":"低"},{"id":"R-RECRUIT-07","cat":"recruit","catLabel":"招聘","risk":"发布虚假招聘信息、以招用为名牟利","level":"ask","owner":"hr","module":"staff","enabled":true,"q":"招聘信息是否真实，是否存在虚假承诺或以招聘名义收费？","law":[{"ref":"《就业服务与就业管理规定》第14条","text":"第14条　用人单位招用人员不得有下列行为： （一）提供虚假招聘信息，发布虚假招聘广告； （二）扣押被录用人员的居民身份证和其他证件； （三）以担保或者其他名义向劳动者收取财物； （四）招用未满16周岁的未成年人以及国家法律、行政法规规定不得招用的其他人员； （五）招用无合法身份证件的人员； （六）以招用人员为名牟取不正当利益或进行其他违法活动。"}],"consequence":"责令改正，没收违法所得并可处罚款","remedy":["规范招聘流程：核验身份证件（禁招不满16周岁童工）；不扣押证件、不收押金/保证金；招用简章必备法定内容；如实告知职业危害、安全生产状况与劳动报酬；录用前核实候选人已与原单位解除/终止劳动关系。"],"sev":"中"},{"id":"R-INTERVIEW-01","cat":"interview","catLabel":"面试","risk":"面试中因性别、民族、残疾、传染病病原携带、农村身份等实施歧视或差别对待","level":"ask","owner":"hr","module":"staff","enabled":true,"q":"面试评判是否因性别、婚育状况、乙肝、户籍等与岗位无关因素而拒绝或抬高标准？","law":[{"ref":"《就业促进法》第26、27、28、29、30、31条","text":"第26条　用人单位招用人员、职业中介机构从事职业中介活动，应当向劳动者提供平等的就业机会和公平的就业条件，不得实施就业歧视。\n第27条　国家保障妇女享有与男子平等的劳动权利。 用人单位招用人员，除国家规定的不适合妇女的工种或者岗位外，不得以性别为由拒绝录用妇女或者提高对妇女的录用标准。 用人单位录用女职工，不得在劳动合同中规定限制女职工结婚、生育的内容。\n第28条　各民族劳动者享有平等的劳动权利。 用人单位招用人员，应当依法对少数民族劳动者给予适当照顾。\n第29条　国家保障残疾人的劳动权利。 各级人民政府应当对残疾人就业统筹规划，为残疾人创造就业条件。 用人单位招用人员，不得歧视残疾人。\n第30条　用人单位招用人员，不得以是传染病病原携带者为由拒绝录用。但是，经医学鉴定传染病病原携带者在治愈前或者排除传染嫌疑前，不得从事法律、行政法规和国务院卫生行政部门规定禁止从事的易使传染病扩散的工作。\n第31条　农村劳动者进城就业享有与城镇劳动者平等的劳动权利，不得对农村劳动者进城就业设置歧视性限制。"},{"ref":"《就业服务与就业管理规定》第16、20条","text":"第16条　用人单位在招用人员时，除国家规定的不适合妇女从事的工种或者岗位外，不得以性别为由拒绝录用妇女或者提高对妇女的录用标准。 用人单位录用女职工，不得在劳动合同中规定限制女职工结婚、生育的内容。\n第20条　用人单位发布的招用人员简章或招聘广告，不得包含歧视性内容。"}],"consequence":"劳动者可起诉；造成损害的承担赔偿责任","remedy":["面试仅考察与岗位直接相关因素，杜绝性别、婚育、乙肝、户籍等歧视；不将乙肝病毒血清学指标作为体检或录用标准；不越界打探与合同无关隐私，同时单位应如实告知相关情况。"],"sev":"中"},{"id":"R-INTERVIEW-02","cat":"interview","catLabel":"面试","risk":"将乙肝病毒血清学指标作为体检受录用标准","level":"ask","owner":"hr","module":"staff","enabled":true,"q":"是否将乙肝病毒血清学指标作为体检标准或录用前提？","law":[{"ref":"《就业服务与就业管理规定》第19条","text":"第19条　用人单位招用人员，不得以是传染病病原携带者为由拒绝录用。但是，经医学鉴定传染病病原携带者在治愈前或者排除传染嫌疑前，不得从事法律、行政法规和国务院卫生行政部门规定禁止从事的易使传染病扩散的工作。 用人单位招用人员，除国家法律、行政法规和国务院卫生行政部门规定禁止乙肝病原携带者从事的工作外，不得强行将乙肝病毒血清学指标作为体检标准。"}],"consequence":"责令改正，并可处1000元以下的罚款（情节严重者更高）","remedy":["面试仅考察与岗位直接相关因素，杜绝性别、婚育、乙肝、户籍等歧视；不将乙肝病毒血清学指标作为体检或录用标准；不越界打探与合同无关隐私，同时单位应如实告知相关情况。"],"sev":"中"},{"id":"R-INTERVIEW-03","cat":"interview","catLabel":"面试","risk":"超出与劳动合同直接相关范围打探隐私，或单位未如实告知相关情况","level":"ask","owner":"hr","module":"staff","enabled":true,"q":"面试了解的信息是否限于与合同直接相关的基本情况，且单位已如实告知？","law":[{"ref":"《劳动合同法》第8条","text":"第8条　用人单位招用劳动者时，应当如实告知劳动者工作内容、工作条件、工作地点、职业危害、安全生产状况、劳动报酬，以及劳动者要求了解的其他情况；用人单位有权了解劳动者与劳动合同直接相关的基本情况，劳动者应当如实说明。"}],"consequence":"知情权与告知义务失衡，易引发纠纷与经济补偿责任","remedy":["面试仅考察与岗位直接相关因素，杜绝性别、婚育、乙肝、户籍等歧视；不将乙肝病毒血清学指标作为体检或录用标准；不越界打探与合同无关隐私，同时单位应如实告知相关情况。"],"sev":"低"},{"id":"R-PROB-01-L104","cat":"probation","catLabel":"试用期","risk":"违法约定试用期（期限超法定上限、对同一劳动者重复约定、对不应约定情形约定）","level":"ask","owner":"hr","module":"staff","enabled":true,"q":"试用期是否符合：合同<3月或以完成任务为期限不得约定；3月–1年≤1月；1–3年≤2月；3年以上及无固定≤6月；同一单位同一劳动者仅约定一次？","law":[{"ref":"《劳动合同法》第19条","text":"第19条　劳动合同期限三个月以上不满一年的，试用期不得超过一个月；劳动合同期限一年以上不满三年的，试用期不得超过二个月；三年以上固定期限和无固定期限的劳动合同，试用期不得超过六个月。 同一用人单位与同一劳动者只能约定一次试用期。 以完成一定工作任务为期限的劳动合同或者劳动合同期限不满三个月的，不得约定试用期。 试用期包含在劳动合同期限内。劳动合同仅约定试用期的，试用期不成立，该期限为劳动合同期限。"}],"consequence":"违法约定且已履行的，按试用期满月工资就超期期间支付赔偿金（第83条）","remedy":["严格按合同期限约定试用期（3月以下/以任务为期限不得约定；3月–1年≤1月；1–3年≤2月；3年以上及无固定≤6月；同一单位同一劳动者仅一次）；试用期工资≥同岗最低档或约定80%且≥最低工资；解除须有录用条件不符证据，且不得对孕期女职工依第40/41条解除。"],"sev":"中"},{"id":"R-PROB-02","cat":"probation","catLabel":"试用期","risk":"试用期工资低于法定下限","level":"ask","owner":"hr","module":"staff","enabled":true,"q":"试用期工资是否≥本单位同岗位最低档工资或约定工资的80%，且≥当地最低工资标准？","law":[{"ref":"《劳动合同法》第20条","text":"第20条　劳动者在试用期的工资不得低于本单位相同岗位最低档工资或者劳动合同约定工资的百分之八十，并不得低于用人单位所在地的最低工资标准。"},{"ref":"《劳动合同法实施条例》第15条","text":"第15条　劳动者在试用期的工资不得低于本单位相同岗位最低档工资的80％或者不得低于劳动合同约定工资的80％，并不得低于用人单位所在地的最低工资标准。"},{"ref":"《最低工资规定》第3、5、12条","text":"第3条　本规定所称最低工资标准，是指劳动者在法定工作时间或依法签订的劳动合同约定的工作时间内提供了正常劳动的前提下，用人单位依法应支付的最低劳动报酬。 本规定所称正常劳动，是指劳动者按依法签订的劳动合同约定，在法定工作时间或劳动合同约定的工作时间内从事的劳动。劳动者依法享受带薪年休假、探亲假、婚丧假、生育（产）假、节育手术假等国家规定的假期间，以及法定工作时间内依法参加社会活动期间，视为提供了正常劳动。\n第5条　最低工资标准一般采取月最低工资标准和小时最低工资标准的形式。月最低工资标准适用于全日制就业劳动者，小时最低工资标准适用于非全日制就业劳动者。\n第12条　在劳动者提供正常劳动的情况下，用人单位应支付给劳动者的工资在剔除下列各项以后，不得低于当地最低工资标准： （一）延长工作时间工资； （二）中班、夜班、高温、低温、井下、有毒有害等特殊工作环境、条件下的津贴； （三）法律、法规和国家规定的劳动者福利待遇等。 实行计件工资或提成工资等工资形式的用人单位，在科学合理的劳动定额基础上，其支付劳动者的工资不得低于相应的最低工资标准。 劳动者由于本人原因造成在法定工作时间内或依法签订的劳动合同约定的工作时间内未提供正常劳动的，不适用于本条规定。"}],"consequence":"补足差额；逾期不支付按应付金额50%–100%加付赔偿金（第85条）","remedy":["严格按合同期限约定试用期（3月以下/以任务为期限不得约定；3月–1年≤1月；1–3年≤2月；3年以上及无固定≤6月；同一单位同一劳动者仅一次）；试用期工资≥同岗最低档或约定80%且≥最低工资；解除须有录用条件不符证据，且不得对孕期女职工依第40/41条解除。"],"sev":"中"},{"id":"R-PROB-03","cat":"probation","catLabel":"试用期","risk":"试用期违法解除（无证据证明不符合录用条件、或依第40/41条解除、或解除孕期女职工）","level":"ask","owner":"hr","module":"staff","enabled":true,"q":"试用期解除劳动合同是否有录用条件及不符证明，且未对孕期女职工依本条解除？","law":[{"ref":"《劳动合同法》第21、42条","text":"第21条　在试用期中，除劳动者有本法第三十九条和第四十条第一项、第二项规定的情形外，用人单位不得解除劳动合同。用人单位在试用期解除劳动合同的，应当向劳动者说明理由。\n第42条　劳动者有下列情形之一的，用人单位不得依照本法第四十条、第四十一条的规定解除劳动合同： （一）从事接触职业病危害作业的劳动者未进行离岗前职业健康检查，或者疑似职业病病人在诊断或者医学观察期间的； （二）在本单位患职业病或者因工负伤并被确认丧失或者部分丧失劳动能力的； （三）患病或者非因工负伤，在规定的医疗期内的； （四）女职工在孕期、产期、哺乳期的； （五）在本单位连续工作满十五年，且距法定退休年龄不足五年的； （六）法律、行政法规规定的其他情形。"}],"consequence":"构成违法解除，按经济补偿标准2倍支付赔偿金或继续履行（第87条）","remedy":["严格按合同期限约定试用期（3月以下/以任务为期限不得约定；3月–1年≤1月；1–3年≤2月；3年以上及无固定≤6月；同一单位同一劳动者仅一次）；试用期工资≥同岗最低档或约定80%且≥最低工资；解除须有录用条件不符证据，且不得对孕期女职工依第40/41条解除。"],"sev":"高"},{"id":"R-PROB-04","cat":"probation","catLabel":"试用期","risk":"违法约定试用期的赔偿金未支付","level":"ask","owner":"hr","module":"staff","enabled":true,"q":"如存在超期试用期且已履行，是否已按满月工资标准支付赔偿金？","law":[{"ref":"《劳动合同法》第83条","text":"第83条　用人单位违反本法规定与劳动者约定试用期的，由劳动行政部门责令改正；违法约定的试用期已经履行的，由用人单位以劳动者试用期满月工资为标准，按已经履行的超过法定试用期的期间向劳动者支付赔偿金。"}],"consequence":"劳动者可主张超期期间按试用期满月工资标准的赔偿金","remedy":["严格按合同期限约定试用期（3月以下/以任务为期限不得约定；3月–1年≤1月；1–3年≤2月；3年以上及无固定≤6月；同一单位同一劳动者仅一次）；试用期工资≥同岗最低档或约定80%且≥最低工资；解除须有录用条件不符证据，且不得对孕期女职工依第40/41条解除。"],"sev":"中"},{"id":"R-SIGN-01","cat":"entry_sign","catLabel":"合同签订","risk":"用工之日起超过一个月未订立书面劳动合同","level":"ask","owner":"hr","module":"contract","enabled":true,"q":"用工之日起是否在一个月内订立书面劳动合同？","law":[{"ref":"《劳动合同法》第10、82条","text":"第10条　建立劳动关系，应当订立书面劳动合同。 已建立劳动关系，未同时订立书面劳动合同的，应当自用工之日起一个月内订立书面劳动合同。 用人单位与劳动者在用工前订立劳动合同的，劳动关系自用工之日起建立。\n第82条　用人单位自用工之日起超过一个月不满一年未与劳动者订立书面劳动合同的，应当向劳动者每月支付二倍的工资。 用人单位违反本法规定不与劳动者订立无固定期限劳动合同的，自应当订立无固定期限劳动合同之日起向劳动者每月支付二倍的工资。"},{"ref":"《劳动合同法实施条例》第5、6、7条","text":"第5条　自用工之日起一个月内，经用人单位书面通知后，劳动者不与用人单位订立书面劳动合同的，用人单位应当书面通知劳动者终止劳动关系，无需向劳动者支付经济补偿，但是应当依法向劳动者支付其实际工作时间的劳动报酬。\n第6条　用人单位自用工之日起超过一个月不满一年未与劳动者订立书面劳动合同的，应当依照劳动合同法第八十二条的规定向劳动者每月支付两倍的工资，并与劳动者补订书面劳动合同；劳动者不与用人单位订立书面劳动合同的，用人单位应当书面通知劳动者终止劳动关系，并依照劳动合同法第四十七条的规定支付经济补偿。 前款规定的用人单位向劳动者每月支付两倍工资的起算时间为用工之日起满一个月的次日，截止时间为补订书面劳动合同的前一日。\n第7条　用人单位自用工之日起满一年未与劳动者订立书面劳动合同的，自用工之日起满一个月的次日至满一年的前一日应当依照劳动合同法第八十二条的规定向劳动者每月支付两倍的工资，并视为自用工之日起满一年的当日已经与劳动者订立无固定期限劳动合同，应当立即与劳动者补订书面劳动合同。"},{"ref":"《劳动保障监察条例》第24条","text":"第24条　用人单位与劳动者建立劳动关系不依法订立劳动合同的，由劳动保障行政部门责令改正。"}],"consequence":"超1月不满1年未订：自满1月次日至补订前一日付2倍工资；满1年视为已订无固定期限合同","remedy":["用工之日起1个月内订立书面劳动合同并双方各执一份；必备条款齐全（含职业危害防护、社保、劳动保护等）；不以欺诈胁迫或免除法定责任/排除劳动者权利条款订约；符合应订无固定期限情形的依法订立。"],"sev":"高"},{"id":"R-SIGN-02","cat":"entry_sign","catLabel":"合同签订","risk":"劳动合同文本未交付劳动者（双方未各执一份）","level":"ask","owner":"hr","module":"contract","enabled":true,"q":"签订的劳动合同是否双方签字盖章、劳动者已持有一份？","law":[{"ref":"《劳动合同法》第16、81条","text":"第16条　劳动合同由用人单位与劳动者协商一致，并经用人单位与劳动者在劳动合同文本上签字或者盖章生效。 劳动合同文本由用人单位和劳动者各执一份。\n第81条　用人单位提供的劳动合同文本未载明本法规定的劳动合同必备条款或者用人单位未将劳动合同文本交付劳动者的，由劳动行政部门责令改正；给劳动者造成损害的，应当承担赔偿责任。"}],"consequence":"责令改正；给劳动者造成损害的承担赔偿责任","remedy":["用工之日起1个月内订立书面劳动合同并双方各执一份；必备条款齐全（含职业危害防护、社保、劳动保护等）；不以欺诈胁迫或免除法定责任/排除劳动者权利条款订约；符合应订无固定期限情形的依法订立。"],"sev":"中"},{"id":"R-SIGN-03","cat":"entry_sign","catLabel":"合同签订","risk":"合同必备条款缺失（尤其职业危害防护、社会保险、劳动保护等）","level":"ask","owner":"hr","module":"contract","enabled":true,"q":"劳动合同是否具备法定必备条款（含职业危害防护、社保等）？","law":[{"ref":"《劳动合同法》第17条","text":"第17条　劳动合同应当具备以下条款： （一）用人单位的名称、住所和法定代表人或者主要负责人； （二）劳动者的姓名、住址和居民身份证或者其他有效身份证件号码； （三）劳动合同期限； （四）工作内容和工作地点； （五）工作时间和休息休假； （六）劳动报酬； （七）社会保险； （八）劳动保护、劳动条件和职业危害防护； （九）法律、法规规定应当纳入劳动合同的其他事项。 劳动合同除前款规定的必备条款外，用人单位与劳动者可以约定试用期、培训、保守秘密、补充保险和福利待遇等其他事项。"}],"consequence":"约定不明按集体合同或国家规定（第18条）；引发争议时不利用人单位","remedy":["用工之日起1个月内订立书面劳动合同并双方各执一份；必备条款齐全（含职业危害防护、社保、劳动保护等）；不以欺诈胁迫或免除法定责任/排除劳动者权利条款订约；符合应订无固定期限情形的依法订立。"],"sev":"中"},{"id":"R-SIGN-04","cat":"entry_sign","catLabel":"合同签订","risk":"以欺诈、胁迫手段或乘人之危订立合同，或约定免除法定责任、排除劳动者权利致合同无效","level":"ask","owner":"hr","module":"contract","enabled":true,"q":"劳动合同是否存在欺诈胁迫、或免除用人单位法定责任/排除劳动者权利的条款？","law":[{"ref":"《劳动合同法》第26、27、28、86条","text":"第26条　下列劳动合同无效或者部分无效： （一）以欺诈、胁迫的手段或者乘人之危，使对方在违背真实意思的情况下订立或者变更劳动合同的； （二）用人单位免除自己的法定责任、排除劳动者权利的； （三）违反法律、行政法规强制性规定的。 对劳动合同的无效或者部分无效有争议的，由劳动争议仲裁机构或者人民法院确认。\n第27条　劳动合同部分无效，不影响其他部分效力的，其他部分仍然有效。\n第28条　劳动合同被确认无效，劳动者已付出劳动的，用人单位应当向劳动者支付劳动报酬。劳动报酬的数额，参照本单位相同或者相近岗位劳动者的劳动报酬确定。\n第86条　劳动合同依照本法第二十六条规定被确认无效，给对方造成损害的，有过错的一方应当承担赔偿责任。"}],"consequence":"合同无效或部分无效；造成损害的过错方赔偿；已付出劳动的仍应支付报酬","remedy":["用工之日起1个月内订立书面劳动合同并双方各执一份；必备条款齐全（含职业危害防护、社保、劳动保护等）；不以欺诈胁迫或免除法定责任/排除劳动者权利条款订约；符合应订无固定期限情形的依法订立。"],"sev":"中"},{"id":"R-SIGN-05","cat":"entry_sign","catLabel":"合同签订","risk":"订立/变更合同时未如实告知职业病危害","level":"ask","owner":"hr","module":"contract","enabled":true,"q":"签订劳动合同时是否如实告知工作场所职业病危害及后果、防护措施？","law":[{"ref":"《职业病防治法》第33条","text":"第33条　用人单位与劳动者订立劳动合同（含聘用合同，下同）时，应当将工作过程中可能产生的职业病危害及其后果、职业病防护措施和待遇等如实告知劳动者，并在劳动合同中写明，不得隐瞒或者欺骗。 劳动者在已订立劳动合同期间因工作岗位或者工作内容变更，从事与所订立劳动合同中未告知的存在职业病危害的作业时，用人单位应当依照前款规定，向劳动者履行如实告知的义务，并协商变更原劳动合同相关条款。 用人单位违反前两款规定的，劳动者有权拒绝从事存在职业病危害的作业，用人单位不得因此解除与劳动者所订立的劳动合同。"}],"consequence":"劳动者可解除合同并要求经济补偿；造成健康损害的依法赔偿","remedy":["用工之日起1个月内订立书面劳动合同并双方各执一份；必备条款齐全（含职业危害防护、社保、劳动保护等）；不以欺诈胁迫或免除法定责任/排除劳动者权利条款订约；符合应订无固定期限情形的依法订立。"],"sev":"高"},{"id":"R-SIGN-06","cat":"entry_sign","catLabel":"合同签订","risk":"符合应订无固定期限合同情形却订固定期限（规避无固定）","level":"ask","owner":"hr","module":"contract","enabled":true,"q":"劳动者连续工作满10年等法定情形出现时，是否依法订立无固定期限合同（除劳动者提出订固定）？","law":[{"ref":"《劳动合同法》第14、82条","text":"第14条　无固定期限劳动合同，是指用人单位与劳动者约定无确定终止时间的劳动合同。 用人单位与劳动者协商一致，可以订立无固定期限劳动合同。有下列情形之一，劳动者提出或者同意续订、订立劳动合同的，除劳动者提出订立固定期限劳动合同外，应当订立无固定期限劳动合同： （一）劳动者在该用人单位连续工作满十年的； （二）用人单位初次实行劳动合同制度或者国有企业改制重新订立劳动合同时，劳动者在该用人单位连续工作满十年且距法定退休年龄不足十年的； （三）连续订立二次固定期限劳动合同，且劳动者没有本法第三十九条和第四十条第一项、第二项规定的情形，续订劳动合同的。 用人单位自用工之日起满一年不与劳动者订立书面劳动合同的，视为用人单位与劳动者已订立无固定期限劳动合同。\n第82条　用人单位自用工之日起超过一个月不满一年未与劳动者订立书面劳动合同的，应当向劳动者每月支付二倍的工资。 用人单位违反本法规定不与劳动者订立无固定期限劳动合同的，自应当订立无固定期限劳动合同之日起向劳动者每月支付二倍的工资。"},{"ref":"《劳动合同法实施条例》第11条","text":"第11条　除劳动者与用人单位协商一致的情形外，劳动者依照劳动合同法第十四条第二款的规定，提出订立无固定期限劳动合同的，用人单位应当与其订立无固定期限劳动合同。对劳动合同的内容，双方应当按照合法、公平、平等自愿、协商一致、诚实信用的原则协商确定；对协商不一致的内容，依照劳动合同法第十八条的规定执行。"}],"consequence":"应订无固定而未订的，自应订之日起每月支付2倍工资","remedy":["用工之日起1个月内订立书面劳动合同并双方各执一份；必备条款齐全（含职业危害防护、社保、劳动保护等）；不以欺诈胁迫或免除法定责任/排除劳动者权利条款订约；符合应订无固定期限情形的依法订立。"],"sev":"高"},{"id":"R-RENEW-01","cat":"entry_renew","catLabel":"合同续订","risk":"应订无固定期限合同而拒不续订","level":"ask","owner":"hr","module":"contract","enabled":true,"q":"合同到期且符合无固定期限条件时，是否依法续订无固定期限合同？","law":[{"ref":"《劳动合同法》第14条","text":"第14条　无固定期限劳动合同，是指用人单位与劳动者约定无确定终止时间的劳动合同。 用人单位与劳动者协商一致，可以订立无固定期限劳动合同。有下列情形之一，劳动者提出或者同意续订、订立劳动合同的，除劳动者提出订立固定期限劳动合同外，应当订立无固定期限劳动合同： （一）劳动者在该用人单位连续工作满十年的； （二）用人单位初次实行劳动合同制度或者国有企业改制重新订立劳动合同时，劳动者在该用人单位连续工作满十年且距法定退休年龄不足十年的； （三）连续订立二次固定期限劳动合同，且劳动者没有本法第三十九条和第四十条第一项、第二项规定的情形，续订劳动合同的。 用人单位自用工之日起满一年不与劳动者订立书面劳动合同的，视为用人单位与劳动者已订立无固定期限劳动合同。"},{"ref":"《劳动合同法实施条例》第11条","text":"第11条　除劳动者与用人单位协商一致的情形外，劳动者依照劳动合同法第十四条第二款的规定，提出订立无固定期限劳动合同的，用人单位应当与其订立无固定期限劳动合同。对劳动合同的内容，双方应当按照合法、公平、平等自愿、协商一致、诚实信用的原则协商确定；对协商不一致的内容，依照劳动合同法第十八条的规定执行。"}],"consequence":"违法不订无固定，面临2倍工资等责任","remedy":["合同到期前评估续订；符合无固定期限条件依法续订（除劳动者提出订固定）；遇医疗期、三期、工伤停工留薪等法定顺延情形自动续延至消失；固定期限期满终止（非因单位维持或提高条件而劳动者拒绝）依法支付经济补偿。"],"sev":"高"},{"id":"R-RENEW-02","cat":"entry_renew","catLabel":"合同续订","risk":"合同期满但劳动者有第42条情形（医疗期、孕期产期哺乳期、工伤1–6级等）未续延","level":"ask","owner":"hr","module":"contract","enabled":true,"q":"合同期满时如劳动者处于医疗期、三期、工伤停工留薪等情形，是否续延至情形消失？","law":[{"ref":"《劳动合同法》第45条","text":"第45条　劳动合同期满，有本法第四十二条规定情形之一的，劳动合同应当续延至相应的情形消失时终止。但是，本法第四十二条第二项规定丧失或者部分丧失劳动能力劳动者的劳动合同的终止，按照国家有关工���保险的规定执行。"}],"consequence":"违法终止，按经济补偿2倍赔偿或继续履行（第47、87条）","remedy":["合同到期前评估续订；符合无固定期限条件依法续订（除劳动者提出订固定）；遇医疗期、三期、工伤停工留薪等法定顺延情形自动续延至消失；固定期限期满终止（非因单位维持或提高条件而劳动者拒绝）依法支付经济补偿。"],"sev":"高"},{"id":"R-RENEW-03","cat":"entry_renew","catLabel":"合同续订","risk":"固定期限合同期满终止未依法支付经济补偿（单位维持/提高条件劳动者不同意除外）","level":"ask","owner":"hr","module":"contract","enabled":true,"q":"固定期限合同因期满终止（非因单位维持或提高条件而劳动者拒绝续订）时，是否支付经济补偿？","law":[{"ref":"《劳动合同法》第46、47条","text":"第46条　有下列情形之一的，用人单位应当向劳动者支付经济补偿： （一）劳动者依照本法第三十八条规定解除劳动合同的； （二）用人单位依照本法第三十六条规定向劳动者提出解除劳动合同并与劳动者协商一致解除劳动合同的； （三）用人单位依照本法第四十条规定解除劳动合同的； （四）用人单位依照本法第四十一条第一款规定解除劳动合同的； （五）除用人单位维持或者提高劳动合同约定条件续订劳动合同，劳动者不同意续订的情形外，依照本法第四十四条第一项规定终止固定期限劳动合同的； （六）依照本法第四十四条第四项、第五项规定终止劳动合同的； （七）法律、行政法规规定的其他情形。\n第47条　经济补偿按劳动者在本单位工作的年限，每满一年支付一个月工资的标准向劳动者支付。六个月以上不满一年的，按一年计算；不满六个月的，向劳动者支付半个月工资的经济补偿。 劳动者月工资高于用人单位所在直辖市、设区的市级人民政府公布的本地区上年度职工月平均工资三倍的，向其支付经济补偿的标准按职工月平均工资三倍的数额支付，向其支付经济补偿的年限最高不超过十二年。 本条所称月工资是指劳动者在劳动合同解除或者终止前十二个月的平均工资。"}],"consequence":"应支未支，劳动者可主张经济补偿（N）及加付赔偿","remedy":["合同到期前评估续订；符合无固定期限条件依法续订（除劳动者提出订固定）；遇医疗期、三期、工伤停工留薪等法定顺延情形自动续延至消失；固定期限期满终止（非因单位维持或提高条件而劳动者拒绝）依法支付经济补偿。"],"sev":"中"},{"id":"R-PERFORM-01","cat":"entry_perform","catLabel":"合同履行","risk":"未按劳动合同全面履行各自义务","level":"ask","owner":"hr","module":"contract","enabled":true,"q":"用人单位与劳动者是否均按合同约定全面履行？","law":[{"ref":"《劳动合同法》第3、29条","text":"第3条　订立劳动合同，应当遵循合法、公平、平等自愿、协商一致、诚实信用的原则。 依法订立的劳动合同具有约束力，用人单位与劳动者应当履行劳动合同约定的义务。\n第29条　用人单位与劳动者应当按照劳动合同的约定，全面履行各自的义务。"}],"consequence":"违约方承担相应责任；劳动者可依法解除并主张补偿","remedy":["全面履行劳动合同约定：按时足额支付劳动报酬，提供约定劳动条件与劳动保护，依法缴纳社会保险，不擅自变更核心义务；劳动者据此可即时解除并主张经济补偿的情形应避免。"],"sev":"中"},{"id":"R-PERFORM-02","cat":"entry_perform","catLabel":"合同履行","risk":"规章制度内容违法或程序不合法，损害劳动者权益","level":"ask","owner":"hr","module":"contract","enabled":true,"q":"规章制度是否内容合法、经民主程序制定并已公示告知？","law":[{"ref":"《劳动合同法》第4、80条","text":"第4条　用人单位应当依法建立和完善劳动规章制度，保障劳动者享有劳动权利、履行劳动义务。 用人单位在制定、修改或者决定有关劳动报酬、工作时间、休息休假、劳动安全卫生、保险福利、职工培训、劳动纪律以及劳动定额管理等直接涉及劳动者切身利益的规章制度或者重大事项时，应当经职工代表大会或者全体职工讨论，提出方案和意见，与工会或者职工代表平等协商确定。 在规章制度和重大事项决定实施过程中，工会或者职工认为不适当的，有权向用人单位提出，通过协商予以修改完善。 用人单位应当将直接涉及劳动者切身利益的规章制度和重大事项决定公示，或者告知劳动者。\n第80条　用人单位直接涉及劳动者切身利益的规章制度违反法律、法规规定的，由劳动行政部门责令改正，给予警告；给劳动者造成损害的，应当承担赔偿责任。"}],"consequence":"责令改正、给予警告；给劳动者造成损害的承担赔偿责任","remedy":["全面履行劳动合同约定：按时足额支付劳动报酬，提供约定劳动条件与劳动保护，依法缴纳社会保险，不擅自变更核心义务；劳动者据此可即时解除并主张经济补偿的情形应避免。"],"sev":"中"},{"id":"R-PERFORM-03","cat":"entry_perform","catLabel":"合同履行","risk":"劳动合同约定的劳动标准低于集体合同标准","level":"ask","owner":"hr","module":"contract","enabled":true,"q":"劳动合同约定的劳动报酬、工时、休息休假等标准是否不低于集体合同规定？","law":[{"ref":"《集体合同规定》第3、6、8条","text":"第3条　本规定所称集体合同，是指用人单位与本单位职工根据法律、法规、规章的规定，就劳动报酬、工作时间、休息休假、劳动安全卫生、职业培训、保险福利等事项，通过集体协商签订的书面协议；所称专项集体合同，是指用人单位与本单位职工根据法律、法规、规章的规定，就集体协商的某项内容签订的专项书面协议。\n第6条　符合本规定的集体合同或专项集体合同，对用人单位和本单位的全体职工具有法律约束力。 用人单位与职工个人签订的劳动合同约定的劳动条件和劳动报酬等标准，不得低于集体合同或专项集体合同的规定。\n第8条　集体协商双方可以就下列多项或某项内容进行集体协商，签订集体合同或专项集体合同： （一）劳动报酬； （二）工作时间； （三）休息休假； （四）劳动安全与卫生； （五）补充保险和福利； （六）女职工和未成年工特殊保护； （七）职业技能培训； （八）劳动合同管理； （九）奖惩； （十）裁员； （十一）集体合同期限； （十二）变更、解除集体合同的程序； （十三）履行集体合同发生争议时的协商处理办法； （十四）违反集体合同的责任； （十五）双方认为应当协商的其他内容。"}],"consequence":"低于集体合同标准的部分无效，按集体合同标准执行","remedy":["全面履行劳动合同约定：按时足额支付劳动报酬，提供约定劳动条件与劳动保护，依法缴纳社会保险，不擅自变更核心义务；劳动者据此可即时解除并主张经济补偿的情形应避免。"],"sev":"中"},{"id":"R-PERFORM-04","cat":"entry_perform","catLabel":"合同履行","risk":"违章指挥、强令冒险作业，未保障劳动者拒绝权","level":"ask","owner":"hr","module":"contract","enabled":true,"q":"是否存在违章指挥/强令冒险作业，且未保障劳动者拒绝权？","law":[{"ref":"《劳动合同法》第32条","text":"第32条　劳动者拒绝用人单位管理人员违章指挥、强令冒险作业的，不视为违反劳动合同。 劳动者对危害生命安全和身体健康的劳动条件，有权对用人单位提出批评、检举和控告。"},{"ref":"《安全生产法》第54条","text":"第54条　从业人员有权对本单位安全生产工作中存在的问题提出批评、检举、控告；有权拒绝违章指挥和强令冒险作业。 生产经营单位不得因从业人员对本单位安全生产工作提出批评、检举、控告或者拒绝违章指挥、强令冒险作业而降低其工资、福利等待遇或者解除与其订立的劳动合同。"}],"consequence":"劳动者拒绝不视为违约；造成损害的赔偿，严重的追究刑责（第88条）","remedy":["全面履行劳动合同约定：按时足额支付劳动报酬，提供约定劳动条件与劳动保护，依法缴纳社会保险，不擅自变更核心义务；劳动者据此可即时解除并主张经济补偿的情形应避免。"],"sev":"高"},{"id":"R-CHANGE-01","cat":"entry_change","catLabel":"合同变更","risk":"未经协商一致擅自变更劳动合同（岗位、地点、薪酬等）","level":"ask","owner":"hr","module":"contract","enabled":true,"q":"变更劳动合同内容（岗位/地点/薪酬等）是否经双方协商一致并采用书面形式？","law":[{"ref":"《劳动合同法》第35条","text":"第35条　用人单位与劳动者协商一致，可以变更劳动合同约定的内容。变更劳动合同，应当采用书面形式。 变更后的劳动合同文本由用人单位和劳动者各执一份。"}],"consequence":"单方变更无效，劳动者可主张恢复或解除并索补偿","remedy":["变更劳动合同（调岗调薪等）须与劳动者协商一致并采用书面形式；确需单方变更的须具合理性（经营必要、薪资相当、无侮辱惩罚）并留存证据，否则劳动者可拒绝并主张权利。"],"sev":"中"},{"id":"R-CHANGE-02","cat":"entry_change","catLabel":"合同变更","risk":"用人单位合并、分立后拒不履行原劳动合同","level":"ask","owner":"hr","module":"contract","enabled":true,"q":"单位合并分立后，是否由承继单位继续履行原劳动合同？","law":[{"ref":"《劳动合同法》第34条","text":"第34条　用人单位发生合并或者分立等情况，原劳动合同继续有效，劳动合同由承继其权利和义务的用人单位继续履行。"}],"consequence":"原合同继续有效，承继单位拒不履行的承担违约责任","remedy":["变更劳动合同（调岗调薪等）须与劳动者协商一致并采用书面形式；确需单方变更的须具合理性（经营必要、薪资相当、无侮辱惩罚）并留存证据，否则劳动者可拒绝并主张权利。"],"sev":"中"},{"id":"R-CHANGE-03","cat":"entry_change","catLabel":"合同变更","risk":"劳动者非因本人原因被安排到新单位，工作年限未合并计算","level":"ask","owner":"hr","module":"contract","enabled":true,"q":"劳动者非本人原因从原单位被安排到新单位，计算经济补偿时是否合并计算原单位工作年限？","law":[{"ref":"《劳动合同法实施条例》第10条","text":"第10条　劳动者非因本人原因从原用人单位被安排到新用人单位工作的，劳动者在原用人单位的工作年限合并计算为新用人单位的工作年限。原用人单位已经向劳动者支付经济补偿的，新用人单位在依法解除、终止劳动合同计算支付经济���偿的工作年限时，不再计算劳动者在原用人单位的工作年限。"}],"consequence":"年限不合并将少算经济补偿，面临补足责任","remedy":["变更劳动合同（调岗调薪等）须与劳动者协商一致并采用书面形式；确需单方变更的须具合理性（经营必要、薪资相当、无侮辱惩罚）并留存证据，否则劳动者可拒绝并主张权利。"],"sev":"中"},{"id":"R-WELFARE-01","cat":"entry_welfare","catLabel":"法定福利","risk":"自用工之日起30日内未办理社会保险登记","level":"ask","owner":"hr","module":"social","enabled":true,"q":"用工之日起30日内是否办理社保登记并为职工办理社保登记？","law":[{"ref":"《社会保险法》第57、58条","text":"第57条　用人单位应当自成立之日起三十日内凭营业执照、登记证书或者单位印章，向当地社会保险经办机构申请办理社会保险登记。社会保险经办机构应当自收到申请之日起十五日内予以审核，发给社会保险登记证件。 用人单位的社会保险登记事项发生变更或者用人单位依法终止的，应当自变更或者终止之日起三十日内，到社会保险经办机构办理变更或者注销社会保险登记。 市场监督管理部门、民政部门和机构编制管理机关应当及时向社会保险经办机构通报用人单位的成立、终止情况，公安机关应当及时向社会保险经办机构通报个人的出生、死亡以及户口登记、迁移、注销等情况。\n第58条　用人单位应当自用工之日起三十日内为其职工向社会保险经办机构申请办理社会保险登记。未办理社会保险登记的，由社会保险经办机构核定其应当缴纳的社会保险费。 自愿参加社会保险的无雇工的个体工商户、未在用人单位参加社会保险的非全日制从业人员以及其他灵活就业人员，应当向社会保险经办机构申请办理社会保险登记。 国家建立全国统一的个人社会保障号码。个人社会保障号码为公民身份号码。"},{"ref":"《社会保险费征缴暂行条例》第4条","text":"第4条　缴费单位、缴费个人应当按时足额缴纳社会保险费。 征缴的社会保险费纳入社会保险基金，专款专用，任何单位和个人不得挪用。"}],"consequence":"责令限期登记；逾期未改正可处罚款","remedy":["用工之日起30日内办理社保登记与增员，依法缴纳五险与住房公积金；发生工伤30日内申请认定；产假/生育依法申领待遇；禁止以现金补贴替代参保，不得签署\"不缴社保\"免责协议（无效）。"],"sev":"高"},{"id":"R-WELFARE-02","cat":"entry_welfare","catLabel":"法定福利","risk":"未按时足额缴纳社会保险费","level":"ask","owner":"hr","module":"social","enabled":true,"q":"是否自行申报、按时足额缴纳各项社会保险费（无缓减免法定事由）？","law":[{"ref":"《社会保险法》第60、63、86条","text":"第60条　用人单位应当自行申报、按时足额缴纳社会保险费，非因不可抗力等法定事由不得缓缴、减免。职工应当缴纳的社会保险费由用人单位代扣代缴，用人单位应当按月将缴纳社会保险费的明细情况告知本人。 无雇工的个体工商户、未在用人单位参加社会保险的非全日制从业人员以及其他灵活就业人员，可以直接向社会保险费征收机构缴纳社会保险费。\n第63条　用人单位未按时足额缴纳社会保险费的，由社会保险费征收机构责令其限期缴纳或者补足。 用人单位逾期仍未缴纳或者补足社会保险费的，社会保险费征收机构可以向银行和其他金融机构查询其存款账户；并可以申请县级以上有关行政部门作出划拨社会保险费的决定，书面通知其开户银行或者其他金融机构划拨社会保险费。用人单位账户余额少于应当缴纳的社会保险费的，社会保险费征收机构可以要求该用人单位提供担保，签订延期缴费协议。 用人单位未足额缴纳社会保险费且未提供担保的，社会保险费征收机构可以申请人民法院扣押、查封、拍卖其价值相当于应当缴纳社会保险费的财产，以拍卖所得抵缴社会保险费。\n第86条　用人单位未按时足额缴纳社会保险费的，由社会保险费征收机构责令限期缴纳或者补足，并自欠缴之日起，按日加收万分之五的滞纳金；逾期仍不缴纳的，由有关行政部门处欠缴数额一倍以上三倍以下的罚款。"},{"ref":"《社会保险费征缴暂行条例》第12、13条","text":"第12条　缴费单位和缴费个人应当以货币形式全额缴纳社会保险费。 缴费个人应当缴纳的社会保险费，由所在单位从其本人工资中代扣代缴。 社会保险费不得减免。\n第13条　缴费单位未按规定缴纳和代扣代缴社会保险费的，由劳动保障行政部门或者税务机关责令限期缴纳；逾期仍不缴纳的，除补缴欠缴数额外，从欠缴之日起，按日加收2‰的滞纳金。滞纳金并入社会保险基金。"}],"consequence":"责令限期补足，加收滞纳金；逾期处欠缴数额1–3倍罚款","remedy":["用工之日起30日内办理社保登记与增员，依法缴纳五险与住房公积金；发生工伤30日内申请认定；产假/生育依法申领待遇；禁止以现金补贴替代参保，不得签署\"不缴社保\"免责协议（无效）。"],"sev":"高"},{"id":"R-WELFARE-03","cat":"entry_welfare","catLabel":"法定福利","risk":"未依法为职工缴存住房公积金","level":"ask","owner":"hr","module":"social","enabled":true,"q":"是否为在职职工办理住房公积金缴存登记、设立账户并按≥5%比例按时足额缴存？","law":[{"ref":"《住房公积金管理条例》第2、13、14、15、16、17、18、19、20、34、37、38条","text":"第2条　本条例适用于中华人民共和国境内住房公积金的缴存、提取、使用、管理和监督。 本条例所称住房公积金，是指国家机关、国有企业、城镇集体企业、外商投资企业、城镇私营企业及其他城镇企业、事业单位、民办非企业单位、社会团体（以下统称单位）及其在职职工缴存的长期住房储金。\n第13条　住房公积金管理中心应当在受委托银行设立住房公积金专户。 单位应当向住房公积金管理中心办理住房公积金缴存登记，并为本单位职工办理住房公积金账户设立手续。每个职工只能有一个住房公积金账户。 住房公积金管理中心应当建立职工住房公积金明细账，记载职工个人住房公积金的缴存、提取等情况。\n第14条　新设立的单位应当自设立之日起30日内向住房公积金管理中心办理住房公积金缴存登记，并自登记之日起20日内，为本单位职工办理住房公积金账户设立手续。 单位合并、分立、撤销、解散或者破产的，应当自发生上述情况之日起30日内由原单位或者清算组织向住房公积金管理中心办理变更登记或者注销登记，并自办妥变更登记或者注销登记之日起20日内，为本单位职工办理住房公积金账户转移或者封存手续。\n第15条　单位录用职工的，应当自录用之日起30日内向住房公积金管理中心办理缴存登记，并办理职工住房公积金账户的设立或者转移手续。 单位与职工终止劳动关系的，单位应当自劳动关系终止之日起30日内向住房公积金管理中心办理变更登记，并办理职工住房公积金账户转移或者封存手续。\n第16条　职工住房公积金的月缴存额为职工本人上一年度月平均工资乘以职工住房公积金缴存比例。 单位为职工缴存的住房公积金的月缴存额为职工本人上一年度月平均工资乘以单位住房公积金缴存比例。\n第17条　新参加工作的职工从参加工作的第二个月开始缴存住房公积金，月缴存额为职工本人当月工资乘以职工住房公积金缴存比例。 单位新调入的职工从调入单位发放工资之日起缴存住房公积金，月缴存额为职工本人当月工资乘以职工住房公积金缴存比例。\n第18条　职工和单位住房公积金的缴存比例均不得低于职工上一年度月平均工资的5%；有条件的城市，可以适当提高缴存比例。具体缴存比例由住房公积金管理委员会拟订，经本级人民政府审核后，报省、自治区、直辖市人民政府批准。\n第19条　职工个人缴存的住房公积金，由所在单位每月从其工资中代扣代缴。 单位应当于每月发放职工工资之日起5日内将单位缴存的和为职工代缴的住房公积金汇缴到住房公积金专户内，由受委托银行计入职工住房公积金账户。\n第20条　单位应当按时、足额缴存住房公积金，不得逾期缴存或者少缴。 对缴存住房公积金确有困难的单位，经本单位职工代表大会或者工会讨论通过，并经住房公积金管理中心审核，报住房公积金管理委员会批准后，可以降低缴存比例或者缓缴；待单位经济效益好转后，再提高缴存比例或者补缴缓缴。\n第34条　住房公积金管理中心和职工有权督促单位按时履行下列义务： （一）住房公积金的缴存登记或者变更、注销登记； （二）住房公积金账户的设立、转移或者封存； （三）足额缴存住房公积金。\n第37条　违反本条例的规定，单位不办理住房公积金缴存登记或者不为本单位职工办理住房公积金账户设立手续的，由住房公积金管理中心责令限期办理；逾期不办理的，处1万元以上5万元以下的罚款。\n第38条　违反本条例的规定，单位逾期不缴或者少缴住房公积金的，由住房公积金管理中心责令限期缴存；逾期仍不缴存的，可以申请人民法院强制执行。"}],"consequence":"不办登记/账户设立罚1–5万元；逾期少缴责令限期缴存，可申请法院强制执行","remedy":["用工之日起30日内办理社保登记与增员，依法缴纳五险与住房公积金；发生工伤30日内申请认定；产假/生育依法申领待遇；禁止以现金补贴替代参保，不得签署\"不缴社保\"免责协议（无效）。"],"sev":"中"},{"id":"R-WELFARE-04","cat":"entry_welfare","catLabel":"法定福利","risk":"骗取社会保险待遇或基金支出","level":"ask","owner":"hr","module":"social","enabled":true,"q":"是否存在虚构材料骗取社保待遇/基金支出的行为？","law":[{"ref":"《社会保险法》第88条","text":"第88条　以欺诈、伪造证明材料或者其他手段骗取社会保险待遇的，由社会保险行政部门责令退回骗取的社会保险金，处骗取金额二倍以上五倍以下的罚款。"},{"ref":"《社会保险费征缴暂行条例》第26条","text":"第26条　缴费单位逾期拒不缴纳社会保险费、滞纳金的，由劳动保障行政部门或者税务机关申请人民法院依法强制征缴。"}],"consequence":"责令退回骗取的社会保险金，处骗取金额2–5倍罚款；构成犯罪的追究刑责","remedy":["用工之日起30日内办理社保登记与增员，依法缴纳五险与住房公积金；发生工伤30日内申请认定；产假/生育依法申领待遇；禁止以现金补贴替代参保，不得签署\"不缴社保\"免责协议（无效）。"],"sev":"高"},{"id":"R-WELFARE-05","cat":"entry_welfare","catLabel":"法定福利","risk":"未依法参保失业保险，影响职工失业待遇","level":"ask","owner":"hr","module":"social","enabled":true,"q":"是否依法为职工缴纳失业保险费（单位2%/职工1%，按阶段性政策）？","law":[{"ref":"《失业保险条例》第2、6条","text":"第2条　城镇企业事业单位、城镇企业事业单位职工依照本条例的规定，缴纳失业保险费。 城镇企业事业单位失业人员依照本条例的规定，享受失业保险待遇。 本条所称城镇企业，是指国有企业、城镇集体企业、外商投资企业、城镇私营企业以及其他城镇企业。\n第6条　城镇企业事业单位按照本单位工资总额的百分之二缴纳失业保险费。城镇企业事业单位职工按照本人工资的百分之一缴纳失业保险费。城镇企业事业单位招用的农民合同制工人本人不缴纳失业保险费。"}],"consequence":"职工失业后无法享受失业保险金，单位可能承担赔偿责任","remedy":["用工之日起30日内办理社保登记与增员，依法缴纳五险与住房公积金；发生工伤30日内申请认定；产假/生育依法申领待遇；禁止以现金补贴替代参保，不得签署\"不缴社保\"免责协议（无效）。"],"sev":"中"},{"id":"R-WELFARE-06","cat":"entry_welfare","catLabel":"法定福利","risk":"女职工未参保生育保险时，生育津贴/产假工资未依法支付","level":"ask","owner":"hr","module":"social","enabled":true,"q":"未参加生育保险的，是否按女职工产假前工资标准支付产假工资/生育津贴？","law":[{"ref":"《女职工劳动保护特别规定》第8条","text":"第8条　女职工产假期间的生育津贴，对已经参加生育保险的，按照用人单位上年度职工月平均工资的标准由生育保险基金支付；对未参加生育保险的，按照女职工产假前工资的标准由用人单位支付。 女职工生育或者流产的医疗费用，按照生育保险规定的项目和标准，对已经参加生育保险的，由生育保险基金支付；对未参加生育保险的，由用人单位支付。"}],"consequence":"未支付的，女职工可主张产假工资及赔偿","remedy":["用工之日起30日内办理社保登记与增员，依法缴纳五险与住房公积金；发生工伤30日内申请认定；产假/生育依法申领待遇；禁止以现金补贴替代参保，不得签署\"不缴社保\"免责协议（无效）。"],"sev":"中"},{"id":"R-HOURS-01-L104","cat":"entry_hours","catLabel":"工时","risk":"违法延长工作时间（日超3小时、月超36小时，或特殊情况未控总量）","level":"ask","owner":"hr","module":"attendance","enabled":true,"q":"安排加班是否控制：一般每日≤1小时、特殊≤3小时、每月≤36小时？","law":[{"ref":"《劳动法》第41、43条","text":"第41条　用人单位由于生产经���需要，经与工会和劳动者协商后可以延长工作时间，一般每日不得超过一小时；因特殊原因需要延长工作时间的，在保障劳动者身体健康的条件下延长工作时间每日不得超过三小时，但是每月不得超过三十六小时。\n第43条　用人单位不得违反本法规定延长劳动者的工作时间。"},{"ref":"《关于职工工作时间的规定》第6条","text":"第6条　任何单位和个人不得擅自延长职工工作时间。因特殊情况和紧急任务确需延长工作时间的，按照国家有关规定执行。"},{"ref":"《劳动保障监察条例》第25条","text":"第25条　用人单位违反劳动保障法律、法规或者规章延长劳动者工作时间的，由劳动保障行政部门给予警告，责令限期改正，并可以按照受侵害的劳动者每人100元以上500元以下的标准计算，处以罚款。"}],"consequence":"警告、限期改正，并按受侵害劳动者每人100–500元罚款","remedy":["执行标准工时（每日8小时、每周40小时）；加班须事前审批并每月不超36小时；特殊工时须行政审批；排班与考勤留痕，不得通过不定时/综合计算工时规避加班费。"],"sev":"中"},{"id":"R-HOURS-02","cat":"entry_hours","catLabel":"工时","risk":"未保证劳动者每周至少休息一日","level":"ask","owner":"hr","module":"attendance","enabled":true,"q":"是否保证劳动者每周至少休息一日？","law":[{"ref":"《劳动法》第38条","text":"第38条　用人单位应当保证劳动者每周至少休息一日。"}],"consequence":"违反工时制度，劳动保障监察责令改正并处罚款","remedy":["执行标准工时（每日8小时、每周40小时）；加班须事前审批并每月不超36小时；特殊工时须行政审批；排班与考勤留痕，不得通过不定时/综合计算工时规避加班费。"],"sev":"中"},{"id":"R-HOURS-03","cat":"entry_hours","catLabel":"工时","risk":"未执行标准工时（每日8小时、每周40小时）","level":"ask","owner":"hr","module":"attendance","enabled":true,"q":"标准工时岗位是否执行每日工作8小时、每周工作40小时？","law":[{"ref":"《关于职工工作时间的规定》第3条","text":"第3条　职工每日工作８小时、每周工作４０小时。"},{"ref":"《劳动法》第36条","text":"第36条　国家实行劳动者每日工作时间不超过八小时、平均每周工作时间不超过四十四小时的工时制度。"}],"consequence":"超时部分按加班处理并支付加班费","remedy":["执行标准工时（每日8小时、每周40小时）；加班须事前审批并每月不超36小时；特殊工时须行政审批；排班与考勤留痕，不得通过不定时/综合计算工时规避加班费。"],"sev":"中"},{"id":"R-HOURS-04","cat":"entry_hours","catLabel":"工时","risk":"实行综合计算工时/不定时工作制未经审批","level":"ask","owner":"hr","module":"attendance","enabled":true,"q":"不能实行标准工时的岗位，是否经劳动保障行政部门审批？","law":[{"ref":"《劳动法》第39条","text":"第39条　企业因生产特点不能实行本法第三十六条、第三十八条规定的，经劳动行政部门批准，可以实行其他工作和休息办法。"},{"ref":"《关于职工工作时间的规定》第5条","text":"第5条　因工作性质或者生产特点的限制，不能实行每日工作８小时、每周工作４０小时标准工时制度的，按照国家有关规定，可以实行其他工作和休息办法。"}],"consequence":"未经审批按标准工时计，超时部分需付加班费","remedy":["执行标准工时（每日8小时、每周40小时）；加班须事前审批并每月不超36小时；特殊工时须行政审批；排班与考勤留痕，不得通过不定时/综合计算工时规避加班费。"],"sev":"中"},{"id":"R-HOURS-05","cat":"entry_hours","catLabel":"工时","risk":"计件工资定额不合理，变相强迫加班","level":"ask","owner":"hr","module":"attendance","enabled":true,"q":"计件工作的定额与计件报酬是否合理，未变相强迫延长工时？","law":[{"ref":"《劳动法》第37条","text":"第37条　对实行计件工作的劳动者，用人单位应当根据本法第三十六条规定的工时制度合理确定其劳动定额和计件报酬标准。"}],"consequence":"定额不合理导致超时，需补付加班费","remedy":["执行标准工时（每日8小时、每周40小时）；加班须事前审批并每月不超36小时；特殊工时须行政审批；排班与考勤留痕，不得通过不定时/综合计算工时规避加班费。"],"sev":"低"},{"id":"R-WAGE-01-L104","cat":"entry_wage","catLabel":"工资","risk":"克扣或无故拖欠劳动者工资","level":"ask","owner":"hr","module":"payroll","enabled":true,"q":"是否以货币形式按月足额支付工资，无克扣或无故拖欠？","law":[{"ref":"《劳动法》第50条","text":"第50条　工资应当以货币形式按月支付给劳动者本人。不得克扣或者无故拖欠劳动者的工资。"},{"ref":"《劳动合同法》第30、85条","text":"第30条　用人单位应当按照劳动合同约定和国家规定，向劳动者及时足额支付劳动报酬。 用人单位拖欠或者未足额支付劳动报酬的，劳动者可以依法向当地人民法院申请支付令，人民法院应当依法发出支付令。\n第85条　用人单位有下列情形之一的，由劳动行政部门责令限期支付劳动报酬、加班费或者经济补偿；劳动报酬低于当地最低工资标准的，应当支付其差额部分；逾期不支付的，责令用人单位按应付金额百分之五十以上百分之一百以下的标准向劳动者加付赔偿金： （一）未按照劳动合同的约定或者国家规定及时足额支付劳动者劳动报酬的； （二）低于当地最低工资标准支付劳动者工资的； （三）安排加班不支付加班费的； （四）解除或者终止劳动合同，未依照本法规定向劳动者支付经济补偿的。"},{"ref":"《工资支付暂行规定》第7、15条","text":"第7条　工资必须在用人单位与劳动者约定的日期支付。如遇节假日或休息日，则应提前在最近的工作日支付。工资至少每月支付一次，实行周、日、小时工资制的可按周、日、小时支付工资。\n第15条　用人单位不得克扣劳动者工资。有下列情况之一的，用人单位可以代扣劳动者工资： （１）用人单位代扣代缴的个人所得税； （２）用人单位代扣代缴的应由劳动者个人负担的各项社会保险费用； （３）法院判决、裁定中要求代扣的抚养费、赡养费； （４）法律、法规规定可以从劳动者工资中扣除的其他费用。"},{"ref":"《劳动保障监察条例》第26条","text":"第26条　用人单位有下列行为之一的，由劳动保障行政部门分别责令限期支付劳动者的工资报酬、劳动者工资低于当地最低工资标准的差额或者解除劳动合同的经济补偿；逾期不支付的，责令用人单位按照应付金额50％以上1倍以下的标准计算，向劳动者加付赔偿金： （一）克扣或者无故拖欠劳动者工资报酬的； （二）支付劳动者的工资低于当地最低工资标准的； （三）解除劳动合同未依法给予劳动者经济补偿的。"},{"ref":"《保障农民工工资支付条例》第3、12条","text":"第3条　农民工有按时足额获得工资的权利。任何单位和个人不得拖欠农民工工资。 农民工应当遵守劳动纪律和职业道德，执行劳动安全卫生规程，完成劳动任务。\n第12条　用人单位应当按照与农民工书面约定或者依法制定的规章制度规定的工资支付周期和具体支付日期足额支付工资。"}],"consequence":"责令限期支付；逾期不支付按应付金额50%–100%加付赔偿金","remedy":["工资不得低于当地最低工资；按月足额支付并保存支付记录至少2年；加班费按150%/200%/300%支付；扣减后余额不低于最低工资；因单位原因停工停产依法支付工资或生活费。"],"sev":"中"},{"id":"R-WAGE-02-L104","cat":"entry_wage","catLabel":"工资","risk":"支付的工资低于当地最低工资标准","level":"ask","owner":"hr","module":"payroll","enabled":true,"q":"劳动者提供正常劳动后，工资（剔除加班费、特殊环境津贴、法定福利）是否≥当地最低工资？","law":[{"ref":"《劳动法》第48条","text":"第48条　国家实行最低工资保障制度。最低工资的具体标准由省、自治区、直辖市人民政府规定，报国务院备案。 用人单位支付劳动者的工资不得低于当地最低工资标准。"},{"ref":"《劳动合同法》第85条","text":"第85条　用人单位有下列情形之一的，由劳动行政部门责令限期支付劳动报酬、加班费或者经济补偿；劳动报酬低于当地最低工资标准的，应当支付其差额部分；逾期不支付的，责令用人单位按应付金额百分之五十以上百分之一百以下的标准向劳动者加付赔偿金： （一）未按照劳动合同的约定或者国家规定及时足额支付劳动者劳动报酬的； （二）低于当地最低工资标准支付劳动者工资的； （三）安排加班不支付加班费的； （四）解除或者终止劳动合同，未依照本法规定向劳动者支付经济补偿的。"},{"ref":"《最低工资规定》第3、5、12、13条","text":"第3条　本规定所称最低工资标准，是指劳动者在法定工作时间或依法签订的劳动合同约定的工作时间内提供了正常劳动的前提下，用人单位依法应支付的最低劳动报酬。 本规定所称正常劳动，是指劳动者按依法签订的劳动合同约定，在法定工作时间或劳动合同约定的工作时间内从事的劳动。劳动者依法享受带薪年休假、探亲假、婚丧假、生育（产）假、节育手术假等国家规定的假期间，以及法定工作时间内依法参加社会活动期间，视为提供了正常劳动。\n第5条　最低工资标准一般采取月最低工资标准和小时最低工资标准的形式。月最低工资标准适用于全日制就业劳动者，小时最低工资标准适用于非全日制就业劳动者。\n第12条　在劳动者提供正常劳动的情况下，用人单位应支付给劳动者的工资在剔除下列各项以后，不得低于当地最低工资标准： （一）延长工作时间工资； （二）中班、夜班、高温、低温、井下、有毒有害等特殊工作环境、条件下的津贴； （三）法律、法规和国家规定的劳动者福利待遇等。 实行计件工资或提成工资等工资形式的用人单位，在科学合理的劳动定额基础上，其支付劳动者的工资不得低于相应的最低工资标准。 劳动者由于本人原因造成在法定工作时间内或依法签订的劳动合同约定的工作时间内未提供正常劳动的，不适用于本条规定。\n第13条　用人单位违反本规定第十一条规定的，由劳动保障行政部门责令其限期改正；违反本规定第十二条规定的，由劳动保障行政部门责令其限期补发所欠劳动者工资，并可责令其按所欠工资的1至5倍支付劳动者赔偿金。"},{"ref":"《劳动保障监察条例》第26条","text":"第26条　用人单位有下列行为之一的，由劳动保障行政部门分别责令限期支付劳动者的工资报酬、劳动者工资低于当地最低工资标准的差额或者解除劳动合同的经济补偿；逾期不支付的，责令用人单位按照应付金额50％以上1倍以下的标准计算，向劳动者加付赔偿金： （一）克扣或者无故拖欠劳动者工资报酬的； （二）支付劳动者的工资低于当地最低工资标准的； （三）解除劳动合同未依法给予劳动者经济补偿的。"}],"consequence":"补发欠薪，并可处欠薪额1–5倍赔偿","remedy":["工资不得低于当地最低工资；按月足额支付并保存支付记录至少2年；加班费按150%/200%/300%支付；扣减后余额不低于最低工资；因单位原因停工停产依法支付工资或生活费。"],"sev":"中"},{"id":"R-WAGE-03","cat":"entry_wage","catLabel":"工资","risk":"安排加班未依法支付加班费或安排补休","level":"ask","owner":"hr","module":"payroll","enabled":true,"q":"平日加班是否≥150%、休息日≥200%（或补休）、法定休假日≥300%支付加班费？","law":[{"ref":"《劳动法》第44条","text":"第44条　有下列情形之一的，用人单位应当按照下列标准支付高于劳动者正常工作时间工资的工资报酬： （一）安排劳动者延长工作时间的，支付不低于工资的百分之一百五十的工资报酬； （二）休息日安排劳动者工作又不能安排补休的，支付不低于工资的百分之二百的工资报酬； （三）法定休假日安排劳动者工作的，支付不低于工资的百分之三百的工资报酬。"},{"ref":"《工资支付暂行规定》第13条","text":"第13条　用人单位在劳动者完成劳动定额或规定的工作任务后，根据实际需要安排劳动者在法定标准工作时间以外工作的，应按以下标准支付工资： （一）用人单位依法安排劳动者在日法定标准工作时间以外延长工作时间的，按照不低于劳动合同规定的劳动者本人小时工资标准的１５０％支付劳动者工资； （二）用人单位依法安排劳动者在休息日工作，而又不能安排补休的，按照不低于劳动合同规定的劳动者本人日或小时工资标准的２００％支付劳动者工资； （三）用人单位依法安排劳动者在法定休假节日工作的，按照不低于劳动合同规定的劳动者本人日或小时工资标准的３００％支付劳动者工资。 实行计件工资的劳动者，在完成计件定额任务后，由用人单位安排延长工作时间的，应根据上述规定的原则，分别按照不低于其本人法定工作时间计件单价的１５０％、２００％、３００％支付其工资。 经劳动行政部门批准实行综合计算工时工作制的，其综合计算工作时间超过法定标准工作时间的部分，应视为延长工作时间，并应按本规定支付劳动者延长工作时间的工资。 实行不定时工时制度的劳动者，不执行上述规定。"},{"ref":"《劳动合同法》第31、85条","text":"第31条　用人单位应当严格执行劳动定额标准，不得强迫或者变相强迫劳动者加班。用人单位安排加班的，应当按照国家有关规定向劳动者支付加班费。\n第85条　用人单位有下列情形之一的，由劳动行政部门责令限期支付劳动报酬、加班费或者经济补偿；劳动报酬低于当地最低工资标准的，应当支付其差额部分；逾期不支付的，责令用人单位按应付金额百分之五十以上百分之一百以下的标准向劳动者加付赔偿金： （一）未按照劳动合同的约定或者国家规定及时足额支付劳动者劳动报酬的； （二）低于当地最低工资标准支付劳动者工资的； （三）安排加班不支付加班费的； （四）解除或者终止劳动合同，未依照本法规定向劳动者支付经济补偿的。"}],"consequence":"补足加班费；逾期不支付加付50%–100%赔偿金","remedy":["工资不得低于当地最低工资；按月足额支付并保存支付记录至少2年；加班费按150%/200%/300%支付；扣减后余额不低于最低工资；因单位原因停工停产依法支付工资或生活费。"],"sev":"高"},{"id":"R-WAGE-04","cat":"entry_wage","catLabel":"工资","risk":"解除/终止劳动合同时未一次性付清劳动者工资","level":"ask","owner":"hr","module":"payroll","enabled":true,"q":"双方解除或终止劳动合同时，是否一次性付清工资？","law":[{"ref":"《工资支付暂行规定》第9条","text":"第9条　劳动关系双方依法解除或终止劳动合同时，用人单位应在解除或终止劳动合同时一次付清劳动者工资。"}],"consequence":"劳动者可主张欠付工资及赔偿","remedy":["工资不得低于当地最低工资；按月足额支付并保存支付记录至少2年；加班费按150%/200%/300%支付；扣减后余额不低于最低工资；因单位原因停工停产依法支付工资或生活费。"],"sev":"中"},{"id":"R-WAGE-05","cat":"entry_wage","catLabel":"工资","risk":"以实物或有价证券替代货币支付工资","level":"ask","owner":"hr","module":"payroll","enabled":true,"q":"工资是否以法定货币支付，未以实物/有价证券替代？","law":[{"ref":"《工资支付暂行规定》第5条","text":"第5条　工资应当以法定货币支付。不得以实物及有价证券替代货币支付。"}],"consequence":"责令改正；造成损害的赔偿","remedy":["工资不得低于当地最低工资；按月足额支付并保存支付记录至少2年；加班费按150%/200%/300%支付；扣减后余额不低于最低工资；因单位原因停工停产依法支付工资或生活费。"],"sev":"中"},{"id":"R-WAGE-06","cat":"entry_wage","catLabel":"工资","risk":"代扣工资不合法（超出法定范围，或扣后低于最低工资）","level":"ask","owner":"hr","module":"payroll","enabled":true,"q":"代扣工资是否限于个税、个人社保、法院裁定及法定项目，且每月扣除≤20%、扣后不低于最低工资？","law":[{"ref":"《工资支付暂行规定》第15、16条","text":"第15条　用人单位不得克扣劳动者工资。有下列情况之一的，用人单位可以代扣劳动者工资： （１）用人单位代扣代缴的个人所得税； （２）用人单位代扣代缴的应由劳动者个人负担的各项社会保险费用； （３）法院判决、裁定中要求代扣的抚养费、赡养费； （４）法律、法规规定可以从劳动者工资中扣除的其他费用。\n第16条　因劳动者本人原因给用人单位造成经济损失的，用人单位可按照劳动合同的约定要求其赔偿经济损失。经济损失的赔偿，可从劳动者本人的工资中扣除。但每月扣除的部分不得超过劳动者当月工资的２０％。若扣除后的剩余工资部分低于当地月最低工资标准，则按最低工资标准支付。"}],"consequence":"违法代扣，劳动者可主张返还及赔偿","remedy":["工资不得低于当地最低工资；按月足额支付并保存支付记录至少2年；加班费按150%/200%/300%支付；扣减后余额不低于最低工资；因单位原因停工停产依法支付工资或生活费。"],"sev":"中"},{"id":"R-WAGE-07","cat":"entry_wage","catLabel":"工资","risk":"（工程建设等领域）未落实农民工工资实名制、分账管理、专用账户、工资保证金","level":"ask","owner":"hr","module":"payroll","enabled":true,"q":"是否落实农民工工资支付台账、按月支付、分账管理、工资专用账户、工资保证金？","law":[{"ref":"《保障农民工工资支付条例》第3、10、11、12、13、14、15、16、24、25、26、27、28、29、30、31条","text":"第3条　农民工有按时足额获得工资的权利。任何单位和个人不得拖欠农民工工资。 农民工应当遵守劳动纪律和职业道德，执行劳动安全卫生规程，完成劳动任务。\n第10条　被拖欠工资的农民工有权依法投诉，或者申请劳动争议调解仲裁和提起诉讼。 任何单位和个人对拖欠农民工工资的行为，有权向人力资源社会保障行政部门或者其他有关部门举报。 人力资源社会保障行政部门和其他有关部门应当公开举报投诉电话、网站等渠道，依法接受对拖欠农民工工资行为的举报、投诉。对于举报、投诉的处理实行首问负责制，属于本部门受理的，应当依法及时处理；不属于本部门受理的，应当及时转送相关部门，相关部门应当依法及时处理，并将处理结果告知举报、投诉人。\n第11条　农民工工资应当以货币形式，通过银行转账或者现金支付给农民工本人，不得以实物或者有价证券等其他形式替代。\n第12条　用人单位应当按照与农民工书面约定或者依法制定的规章制度规定的工资支付周期和具体支付日期足额支付工资。\n第13条　实行月、周、日、小时工资制的，按照月、周、日、小时为周期支付工资；实行计件工资制的，工资支付周期由双方依法约定。\n第14条　用人单位与农民工书面约定或者依法制定的规章制度规定的具体支付日期，可以在农民工提供劳动的当期或者次期。具体支付日期遇法定节假日或者休息日的，应当在法定节假日或者休息日前支付。 用人单位因不可抗力未能在支付日期支付工资的，应当在不可抗力消除后及时支付。\n第15条　用人单位应当按照工资支付周期编制书面工资支付台账，并至少保存3年。 书面工资支付台账应当包括用人单位名称，支付周期，支付日期，支付对象姓名、身份证号码、联系方式，工作时间，应发工资项目及数额，代扣、代缴、扣除项目和数额，实发工资数额，银行代发工资凭证或者农民工签字等内容。 用人单位向农民工支付工资时，应当提供农民工本人的工资清单。\n第16条　用人单位拖欠农民工工资的，应当依法予以清偿。\n第24条　建设单位应当向施工单位提供工程款支付担保。 建设单位与施工总承包单位依法订立书面工程施工合同，应当约定工程款计量周期、工程款进度结算办法以及人工费用拨付周期，并按照保障农民工工资按时足额支付的要求约定人工费用。人工费用拨付周期不得超过1个月。 建设单位与施工总承包单位应当将工程施工合同保存备查。\n第25条　施工总承包单位与分包单位依法订立书面分包合同，应当约定工程款计量周期、工程款进度结算办法。\n第26条　施工总承包单位应当按照有关规定开设农民工工资专用账户，专项用于支付该工程建设项目农民工工资。 开设、使用农民工工资专用账户有关资料应当由施工总承包单位妥善保存备查。\n第27条　金融机构应当优化农民工工资专用账户开设服务流程，做好农民工工资专用账户的日常管理工作；发现资金未按约定拨付等情况的，及时通知施工总承包单位，由施工总承包单位报告人力资源社会保障行政部门和相关行业工程建设主管部门，并纳入欠薪预警系统。 工程完工且未拖欠农民工工资的，施工总承包单位公示30日后，可以申请注销农民工工资专用账户，账户内余额归施工总承包单位所有。\n第28条　施工总承包单位或者分包单位应当依法与所招用的农民工订立劳动合同并进行用工实名登记，具备条件的行业应当通过相应的管理服务信息平台进行用工实名登记、管理。未与施工总承包单位或者分包单位订立劳动合同并进行用工实名登记的人员，不得进入项目现场施工。 施工总承包单位应当在工程项目部配备劳资专管员，对分包单位劳动用工实施监督管理，掌握施工现场用工、考勤、工资支付等情况，审核分包单位编制的农民工工资支付表，分包单位应当予以配合。 施工总承包单位、分包单位应当建立用工管理台账，并保存至工程完工且工资全部结清后至少3年。\n第29条　建设单位应当按照合同约定及时拨付工程款，并将人工费用及时足额拨付至农民工工资专用账户，加强对施工总承包单位按时足额支付农民工工资的监督。 因建设单位未按照合同约定及时拨付工程款导致农民工工资拖欠的，建设单位应当以未结清的工程款为限先行垫付被拖欠的农民工工资。 建设单位应当以项目为单位建立保障农民工工资支付协调机制和工资拖欠预防机制，督促施工总承包单位加强劳动用工管理，妥善处理与农民工工资支付相关的矛盾纠纷。发生农民工集体讨薪事件的，建设单位应当会同施工总承包单位及时处理，并向项目所在地人力资源社会保障行政部门和相关行业工程建设主管部门报告有关情况。\n第30条　分包单位对所招用农民工的实名制管理和工资支付负直接责任。 施工总承包单位对分包单位劳动用工和工资发放等情况进行监督。 分包单位拖欠农民工工资的，由施工总承包单位先行清偿，再依法进行追偿。 工程建设项目转包，拖欠农民工工资的，由施工总承包单位先行清偿，再依法进行追偿。\n第31条　工程建设领域推行分包单位农民工工资委托施工总承包单位代发制度。 分包单位应当按月考核农民工工作量并编制工资支付表，经农民工本人签字确认后，与当月工程进度等情况一并交施工总承包单位。 施工总承包单位根据分包单位编制的工资支付表，通过农民工工资专用账户直接将工资支付到农民工本人的银行账户，并向分包单位提供代发工资凭证。 用于支付农民工工资的银行账户所绑定的农民工本人社会保障卡或者银行卡，用人单位或者其他人员不得以任何理由扣押或者变相扣押。"}],"consequence":"责令限期改正；逾期不改正处5–10万元罚款，乃至责令项目停工","remedy":["工资不得低于当地最低工资；按月足额支付并保存支付记录至少2年；加班费按150%/200%/300%支付；扣减后余额不低于最低工资；因单位原因停工停产依法支付工资或生活费。"],"sev":"高"},{"id":"R-WAGE-08","cat":"entry_wage","catLabel":"工资","risk":"法定休假日、年休假、婚丧假、依法参加社会活动期间未依法支付工资","level":"ask","owner":"hr","module":"payroll","enabled":true,"q":"职工在法定假、年休假、婚丧假及依法参加社会活动期间，是否按合同标准支付工资？","law":[{"ref":"《劳动法》第51条","text":"第51条　劳动者在法定休假日和婚丧假期间以及依法参加社会活动期间，用人单位应当依法支付工资。"},{"ref":"《工资支付暂行规定》第11条","text":"第11条　劳动者依法享受年休假、探亲假、婚假、丧假期间，用人单��应按劳动合同规定的标准支付劳动者工资。"}],"consequence":"未支付的补足并承担赔偿责任","remedy":["工资不得低于当地最低工资；按月足额支付并保存支付记录至少2年；加班费按150%/200%/300%支付；扣减后余额不低于最低工资；因单位原因停工停产依法支付工资或生活费。"],"sev":"中"},{"id":"R-REST-01","cat":"entry_rest","catLabel":"休息休假","risk":"未安排全体公民法定节假日休假（现行13天）","level":"ask","owner":"hr","module":"staff","enabled":true,"q":"是否安排全体公民法定节假日（元旦1、春节4、清明1、劳动2、端午1、中秋1、国庆3，共13天）休假？","law":[{"ref":"《劳动法》第40条","text":"第40条　用人单位在下列节日期间应当依法安排劳动者休假： （一）元旦； （二）春节； （三）国际劳动节； （四）国庆节； （五）法律、法规规定的其他休假节日。"},{"ref":"《全国年节及纪念日放假办法》第2、3、6、7条","text":"第2条　全体公民放假的节日： （一）元旦，放假1天（1月1日）； （二）春节，放假4天（农历除夕、正月初一至初三）； （三）清明节，放假1天（农历清明当日）； （四）劳动节，放假2天（5月1日、2日）； （五）端午节，放假1天（农历端午当日）； （六）中秋节，放假1天（农历中秋当日）； （七）国庆节，放假3天（10月1日至3日）。\n第3条　部分公民放假的节日及纪念日： （一）妇女节（3月8日），妇女放假半天； （二）青年节（5月4日），14周岁以上的青年放假半天； （三）儿童节（6月1日），不满14周岁的少年儿童放假1天； （四）中国人民解放军建军纪念日（8月1日），现役军人放假半天。\n第6条　全体公民放假的假日，如果适逢周六、周日，应当在工作日补假。部分公民放假的假日，如果适逢周六、周日，则不补假。\n第7条　全体公民放假的假日，可合理安排统一放假调休，结合落实带薪年休假等制度，实际形成较长假期。除个别特殊情形外，法定节假日假期前后连续工作一般不超过6天。"}],"consequence":"法定假日安排工作须付300%加班费（不可补休）","remedy":["保障每周至少休息一日与全体公民法定节假日（共13天）；统筹安排或补发未休年休假工资（日工资×200%×未休天数）；休息日加班不能补休的支付200%工资。"],"sev":"中"},{"id":"R-REST-02","cat":"entry_rest","catLabel":"休息休假","risk":"未依法安排职工带薪年休假","level":"ask","owner":"hr","module":"staff","enabled":true,"q":"连续工作1年以上的职工，是否安排年休假（满1年5天/满10年10天/满20年15天）？","law":[{"ref":"《劳动法》第45条","text":"第45条　国家实行带薪年休假制度。 劳动者连续工作一年以上的，享受带薪年休假。具体办法由国务院规定。"},{"ref":"《职工带薪年休假条例》第2、3、4、5、6、7条","text":"第2条　机关、团体、企业、事业单位、民办非企业单位、有雇工的个体工商户等单位的职工连续工作1年以上的，享受带薪年休假（以下简称年休假）。单位应当保证职工享受年休假。职工在年休假期间享受与正常工作期间相同的工资收入。\n第3条　职工累计工作已满1年不满10年的，年休假5天；已满10年不满20年的，年休假10天；已满20年的，年休假15天。 国家法定休假日、休息日不计入年休假的假期。\n第4条　职工有下列情形之一的，不享受当年的年休假： （一）职工依法享受寒暑假，其休假天数多于年休假天数的； （二）职工请事假累计20天以上且单位按照规定不扣工资的； （三）累计工作满1年不满10年的职工，请病假累计2个月以上的； （四）累计工作满10年不满20年的职工，请病假累计3个月以上的； （五）累计工作满20年以上的职工，请病假累计4个月以上的。\n第5条　单位根据生产、工作的具体情况，并考虑职工本人意愿，统筹安排职工年休假。 年休假在1个年度内可以集中安排，也可以分段安排，一般不跨年度安排。单位因生产、工作特点确有必要跨年度安排职工年休假的，可以跨1个年度安排。 单位确因工作需要不能安排职工休年休假的，经职工本人同意，可以不安排职工休年休假。对职工应休未休的年休假天数，单位应当按照该职工日工资收入的300%支付年休假工资报酬。\n第6条　县级以上地方人民政府人事部门、劳动保障部门应当依据职权对单位执行本条例的情况主动进行监督检查。 工会组织依法维护职工的年休假权利。\n第7条　单位不安排职工休年休假又不依照本条例规定给予年休假工资报酬的，由县级以上地方人民政府人事部门或者劳动保障部门依据职权责令限期改正；对逾期不改正的，除责令该单位支付年休假工资报酬外，单位还应当按照年休假工资报酬的数额向职工加付赔偿金；对拒不支付年休假工资报酬、赔偿金的，属于公务员和参照公务员法管理的人员所在单位的，对直接负责的主管人员以及其他直接责任人员依法给予处分；属于其他单位的，由劳动保障部门、人事部门或者职工申请人民法院强制执行。"},{"ref":"《企业职工带薪年休假实施办法》第3、4、9、10条","text":"第3条　职工连续工作满12个月以上的，享受带薪年休假（以下简称年休假）。\n第4条　年休假天数根据职工累计工作时间确定。职工在同一或者不同用人单位工作期间，以及依照法律、行政法规或者国务院规定视同工作期间，应当计为累计工作时间。\n第9条　用人单位根据生产、工作的具体情况，并考虑职工本人意愿，统筹安排年休假。用人单位确因工作需要不能安排职工年休假或者跨1个年度安排年休假的，应征得职工本人同意。\n第10条　用人单位经职工同意不安排年休假或者安排职工年休假天数少于应休年休假天数，应当在本年度内对职工应休未休年休假天数，按照其日工资收入的300%支付未休年休假工资报酬，其中包含用人单位支付职工正常工作期间的工资收入。 用人单位安排职工休年休假，但是职工因本人原因且书面提出不休年休假的，用人单位可以只支付其正常工作期间的工资收入。"}],"consequence":"未安排且职工未书面放弃的，按日工资300%支付未休年休假工资","remedy":["保障每周至少休息一日与全体公民法定节假日（共13天）；统筹安排或补发未休年休假工资（日工资×200%×未休天数）；休息日加班不能补休的支付200%工资。"],"sev":"中"},{"id":"R-REST-03","cat":"entry_rest","catLabel":"休息休假","risk":"解除/终止合同时当年度未休年休假未折算","level":"ask","owner":"hr","module":"staff","enabled":true,"q":"解除/终止合同时，当年度未休年休假是否按折算法支付报酬？","law":[{"ref":"《职工带薪年休假条例》第6、7条","text":"第6条　县级以上地方人民政府人事部门、劳动保障部门应当依据职权对单位执行本条例的情况主动进行监督检查。 工会组织依法维护职工的年休假权利。\n第7条　单位不安排职工休年休假又不依照本条例规定给予年休假工资报酬的，由县级以上地方人民政府人事部门或者劳动保障部门依据职权责令限期改正；对逾期不改正的，除责令该单位支付年休假工资报酬外，单位还应当按照年休假工资报酬的数额向职工加付赔偿金；对拒不支付年休假工资报酬、赔偿金的，属于公务员和参照公务员法管理的人员所在单位的，对直接负责的主管人员以及其他直接责任人员依法给予处分；属于其他单位的，由劳动保障部门、人事部门或者职工申请人民法院强制执行。"},{"ref":"《企业职工带薪年休假实施办法》第9、11、12条","text":"第9条　用人单位根据生产、工作的具体情况，并考虑职工本人意愿，统筹安排年休假。用人单位确因工作需要不能安排职工年休假或者跨1个年度安排年休假的，应征得职工本人同意。\n第11条　计算未休年休假工资报酬的日工资收入按照职工本人的月工资除以月计薪天数（21.75天）进行折算。 前款所称月工资是指职工在用人单位支付其未休年休假工资报酬前12个月剔除加班工资后的月平均工资。在本用人单位工作时间不满12个月的，按实际月份计算月平均工资。 职工在年休假期间享受与正常工作期间相同的工资收入。实行计件工资、提成工资或者其他绩效工资制的职工，日工资收入的计发办法按照本条第一款、��二款的规定执行。\n第12条　用人单位与职工解除或者终止劳动合同时，当年度未安排职工休满应休年休假的，应当按照职工当年已工作时间折算应休未休年休假天数并支付未休年休假工资报酬，但折算后不足1整天的部分不支付未休年休假工资报酬。 前款规定的折算方法为： （当年度在本单位已过日历天数÷365天）×职工本人全年应当享受的年休假天数-当年度已安排年休假天数。 用人单位当年已安排职工年休假的，多于折算应休年休假的天数不再扣回。"}],"consequence":"未折算的，职工可主张300%未休工资","remedy":["保障每周至少休息一日与全体公民法定节假日（共13天）；统筹安排或补发未休年休假工资（日工资×200%×未休天数）；休息日加班不能补休的支付200%工资。"],"sev":"中"},{"id":"R-REST-04","cat":"entry_rest","catLabel":"休息休假","risk":"女职工产假少于法定天数","level":"ask","owner":"hr","module":"staff","enabled":true,"q":"女职工生育是否享受不少于98天产假（难产、多胞胎相应增加）？","law":[{"ref":"《女职工劳动保护特别规定》第7条","text":"第7条　女职工生育享受98天产假，其中产前可以休假15天；难产的，增加产假15天；生育多胞胎的，每多生育1个婴儿，增加产假15天。 女职工怀孕未满4个月流产的，享受15天产假；怀孕满4个月流产的，享受42天产假。"},{"ref":"《劳动法》第62条","text":"第62条　女职工生育享受不少于九十天的产假。"}],"consequence":"劳动保障监察按每人1000–5000元罚款（监察条例第23条）","remedy":["保障每周至少休息一日与全体公民法定节假日（共13天）；统筹安排或补发未休年休假工资（日工资×200%×未休天数）；休息日加班不能补休的支付200%工资。"],"sev":"高"},{"id":"R-FEMALE-01","cat":"entry_female","catLabel":"女工","risk":"安排女职工从事禁忌劳动（矿山井下、第四级体力劳动；经期/孕期/哺乳期第三级体力及冷水低温高处等）","level":"ask","owner":"hr","module":"staff","enabled":true,"q":"是否避免安排女职工从事法定禁忌劳动，并对三期女职工调整禁忌岗位？","law":[{"ref":"《劳动法》第59、60、61、62、63条","text":"第59条　禁止安排女职工从事矿山井下、国家规定的第四级体力劳动强度的劳动和其他禁忌从事的劳动。\n第60条　不得安排女职工在经期从事高处、低温、冷水作业和国家规定的第三级体力劳动强度的劳动。\n第61条　不得安排女职工在怀孕期间从事国家规定的第三级体力劳动强度的劳动和孕期禁忌从事的活动。对怀孕七个月以上的女职工，不得安排其延长工作时间和夜班劳动。\n第62条　女职工生育享受不少于九十天的产假。\n第63条　不得安排女职工在哺乳未满一周岁的婴儿期间从事国家规定的第三级体力劳动强度的劳动和哺乳期禁忌从事的其他劳动，不得安排其延长工作时间和夜班劳动。"},{"ref":"《女职工劳动保护特别规定》第9、10、11条","text":"第9条　对哺乳未满1周岁婴儿的女职工，用人单位不得延长劳动时间或者安排夜班劳动。 用人单位应当在每天的劳动时间内为哺乳期女职工安排1小时哺乳时间；女职工生育多胞胎的，每多哺乳1个婴儿每天增加1小时哺乳时间。\n第10条　女职工比较多的用人单位应当根据女职工的需要，建立女职工卫生室、孕妇休息室、哺乳室等设施，妥善解决女职工在生理卫生、哺乳方面的困难。\n第11条　在劳动场所，用人单位应���预防和制止对女职工的性骚扰。"},{"ref":"《职业病防治法》第38条","text":"第38条　用人单位不得安排未成年工从事接触职业病危害的作业；不得安排孕期、哺乳期的女职工从事对本人和胎儿、婴儿有危害的作业。"}],"consequence":"劳动保障监察按每人1000–5000元罚款（监察条例第23条）","remedy":["不安排女职工从事矿山井下、四级体力劳动强度等禁忌劳动；对孕期、哺乳期女职工调整禁忌岗位；产假、哺乳时间依法保障；不因结婚、怀孕、产假、哺乳降级降薪或违法解除。"],"sev":"高"},{"id":"R-FEMALE-02","cat":"entry_female","catLabel":"女工","risk":"因女职工怀孕、生育、哺乳降低工资、辞退或限制晋级评优","level":"ask","owner":"hr","module":"staff","enabled":true,"q":"是否因女职工怀孕、生育、哺乳而降低工资、辞退或限制其晋级评优？","law":[{"ref":"《女职工劳动保护特别规定》第5条","text":"第5条　用人单位不得因女职工怀孕、生育、哺乳降低其工资、予以辞退、与其解除劳动或者聘用合同。"}],"consequence":"违法，女职工可主张恢复、补薪及赔偿","remedy":["不安排女职工从事矿山井下、四级体力劳动强度等禁忌劳动；对孕期、哺乳期女职工调整禁忌岗位；产假、哺乳时间依法保障；不因结婚、怀孕、产假、哺乳降级降薪或违法解除。"],"sev":"高"},{"id":"R-FEMALE-03","cat":"entry_female","catLabel":"女工","risk":"孕期女职工不能适应原劳动，未予以减轻或调整岗位","level":"ask","owner":"hr","module":"staff","enabled":true,"q":"孕期女职工不能适应原劳动的，是否减轻劳动量或安排其他适应岗位？","law":[{"ref":"《女职工劳动保护特别规定》第6条","text":"第6条　女职工在孕期不能适应原劳动的，用人单位应当根据医疗机构的证明，予以减轻劳动量或者安排其他能够适应的劳动。 对怀孕7个月以上的女职工，用人单位不得延长劳动时间或者安排夜班劳动，并应当在劳动时间内安排一定的休息时间。 怀孕女职工在劳动时间内进行产前检查，所需时间计入劳动时间。"}],"consequence":"未调整的，女职工可主张权益受损赔偿","remedy":["不安排女职工从事矿山井下、四级体力劳动强度等禁忌劳动；对孕期、哺乳期女职工调整禁忌岗位；产假、哺乳时间依法保障；不因结婚、怀孕、产假、哺乳降级降薪或违法解除。"],"sev":"中"},{"id":"R-FEMALE-04","cat":"entry_female","catLabel":"女工","risk":"哺乳期未提供每日1小时哺乳时间","level":"ask","owner":"hr","module":"staff","enabled":true,"q":"哺乳未满1周岁婴儿的女职工，是否每班提供1小时哺乳时间？","law":[{"ref":"《女职工劳动保护特别规定》第9条","text":"第9条　对哺乳未满1周岁婴儿的女职工，用人单位不得延长劳动时间或者安排夜班劳动。 用人单位应当在每天的劳动时间内为哺乳期女职工安排1小时哺乳时间；女职工生育多胞胎的，每多哺乳1个婴儿每天增加1小时哺乳时间。"}],"consequence":"未提供的，女职工可主张权益受损","remedy":["不安排女职工从事矿山井下、四级体力劳动强度等禁忌劳动；对孕期、哺乳期女职工调整禁忌岗位；产假、哺乳时间依法保障；不因结婚、怀孕、产假、哺乳降级降薪或违法解除。"],"sev":"中"},{"id":"R-FEMALE-05","cat":"entry_female","catLabel":"女工","risk":"招聘、面试中因性别差别对待或提高录用标准","level":"ask","owner":"hr","module":"staff","enabled":true,"q":"招聘面试中是否因性别拒绝录用或提高录用标准，或合同规定限制女职工结婚生育？","law":[{"ref":"《就业促进法》第27条","text":"第27条　国家保障妇女享有与男子平等的劳动权利。 用人单位招用人员，除国家规定的不适合妇女的工种或者岗位外，不得以性别为由拒绝录用妇女或者提高对妇女的录用标准。 用人单位录用女职工，不得在劳动合同中规定限制女职工结婚、生育的内容。"},{"ref":"《就业服务与就业管理规定》第16条","text":"第16条　用人单位在招用人员时，除国家规定的不适合妇女从事的工种或者岗位外，不得以性别为由拒绝录用妇女或者提高对妇女的录用标准。 用人单位录用女职工，不得在劳动合同中规定限制女职工结婚、生育的内容。"}],"consequence":"构成就业歧视，可起诉并赔偿","remedy":["不安排女职工从事矿山井下、四级体力劳动强度等禁忌劳动；对孕期、哺乳期女职工调整禁忌岗位；产假、哺乳时间依法保障；不因结婚、怀孕、产假、哺乳降级降薪或违法解除。"],"sev":"中"},{"id":"R-FEMALE-06","cat":"entry_female","catLabel":"女工","risk":"违法解除/终止孕期、产期、哺乳期女职工（违反第42条）","level":"ask","owner":"hr","module":"staff","enabled":true,"q":"是否对处于孕期、产期、哺乳期的女职工依第40/41条解除或违法终止？","law":[{"ref":"《劳动合同法》第42、45、87条","text":"第42条　劳动者有下列情形之一的，用人单位不得依照本法第四十条、第四十一条的规定解除劳动合同： （一）从事接触职业病危害作业的劳动者未进行离岗前职业健康检查，或者疑似职业病病人在诊断或者医学观察期间的； （二）在本单位患职业病或者因工负伤并被确认丧失或者部分丧失劳动能力的； （三）患病或者非因工负伤，在规定的医疗期内的； （四）女职工在孕期、产期、哺乳期的； （五）在本单位连续工作满十五年，且距法定退休年龄不足五年的； （六）法律、行政法规规定的其他情形。\n第45条　劳动合同期满，有本法第四十二条规定情形之一的，劳动合同应当续延至相应的情形消失时终止。但是，本法第四十二条第二项规定丧失或者部分丧失劳动能力劳动者的劳动合同的终止，按照国家有关工���保险的规定执行。\n第87条　用人单位违反本法规定解除或者终止劳动合同的，应当依照本法第四十七条规定的经济补偿标准的二倍向劳动者支付赔偿金。"}],"consequence":"违法解除/终止，按经济补偿2倍赔偿或继续履行","remedy":["不安排女职工从事矿山井下、四级体力劳动强度等禁忌劳动；对孕期、哺乳期女职工调整禁忌岗位；产假、哺乳时间依法保障；不因结婚、怀孕、产假、哺乳降级降薪或违法解除。"],"sev":"高"},{"id":"R-FEMALE-07","cat":"entry_female","catLabel":"女工","risk":"招用不满16周岁人员（童工），或违规使用未成年工","level":"ask","owner":"hr","module":"staff","enabled":true,"q":"是否招用不满16周岁人员，或对16–18岁未成年工安排禁忌劳动？","law":[{"ref":"《禁止使用童工规定》第2、4条","text":"第2条　国家机关、社会团体 、企业事业单位、民办非企业单位或者个体工商户（以下统称用人单位）均不得招用不满１６周岁的未成年人（招用不满１６周岁的未成年人，以下统称使用童工）。 禁止任何单位或者个人为不满１６周岁的未成年人介绍就业。 禁止不满１６周岁的未成年人开业从事个体经营活动。\n第4条　用人单位招用人员时，必须核查被招用人员的身份证；对不满１６周岁的未成年人，一律不得录用。用人单位录用人员的录用登记、核查材料应当妥善保管。"},{"ref":"《劳动法》第58条","text":"第58条　国家对女职工和未成年工实行特殊劳动保护。 未成年工是指年满十六周岁未满十八周岁的劳动者。"}],"consequence":"童工每童工每月5000元罚款并送回；未成年工违规安排按监察处罚","remedy":["不安排女职工从事矿山井下、四级体力劳动强度等禁忌劳动；对孕期、哺乳期女职工调整禁忌岗位；产假、哺乳时间依法保障；不因结婚、怀孕、产假、哺乳降级降薪或违法解除。"],"sev":"高"},{"id":"R-SAFETY-01","cat":"entry_safety","catLabel":"劳动安全卫生","risk":"未建立健全劳动安全卫生制度、安全卫生设施未「三同时」","level":"ask","owner":"legal","module":"staff","enabled":true,"q":"是否建立安全卫生制度，且新建/改建/扩建工程的安全卫生设施与主体工程同时设计、施工、投产？","law":[{"ref":"《劳动法》第52、53条","text":"第52条　用人单位必须建立、健全劳动安全卫生制度，严格执行国家劳动安全卫生规程和标准，对劳动者进行劳动安全卫生教育，防止劳动过程中的事故，减少职业危害。\n第53条　劳动安全卫生设施必须符合国家规定的标准。 新建、改建、扩建工程的劳动安全卫生设施必须与主体工程同时设计、同时施工、同时投入生产和使用。"},{"ref":"《安全生产法》第20、31条","text":"第20条　生产经营单位应当具备本法和有关法律、行政法规和国家标准或者行业标准规定的安全生产条件；不具备安全生产条件的，不得从事生产经营活动。\n第31条　生产经营单位新建、改建、扩建工程项目（以下统称建设项目）的安全设施，必须与主体工程同时设计、同时施工、同时投入生产和使用。安全设施投资应当纳入建设项目概算。"}],"consequence":"责令限期改正；导致事故的追究责任","remedy":["建立健全劳动安全卫生制度，安全卫生设施\"三同时\"；提供合格防护用品并培训；如实告知工作场所职业危害及后果、防护措施；组织岗前/岗中/离岗职业健康检查；事故伤害30日内申请工伤认定。"],"sev":"高"},{"id":"R-SAFETY-02","cat":"entry_safety","catLabel":"劳动安全卫生","risk":"未提供符合规定的劳动安全卫生条件和必要的防护用品","level":"ask","owner":"legal","module":"staff","enabled":true,"q":"是否提供符合国家标准/行业标准的劳动安全卫生条件和防护用品？","law":[{"ref":"《劳动法》第54条","text":"第54条　用人单位必须为劳动者提供符合国家规定的劳动安全卫生条件和必要的劳动防护用品，对从事有职业危害作业的劳动者应当定期进行健康检查。"},{"ref":"《安全生产法》第45条","text":"第45条　生产经营单位必须为从业人员提供符合国家标准或者行业标准的劳动防护用品，并监督、教育从业人员按照使用规则佩戴、使用。"},{"ref":"《职业病防治法》第22条","text":"第22条　用人单位必须采用有效的职业病防护设施，并为劳动者提供个人使用的职业病防护用品。 用人单位为劳动者个人提供的职业病防护用品必须符合防治职业病的要求；不符合要求的，不得使用。"}],"consequence":"责令限期改正；造成健康损害的赔偿","remedy":["建立健全劳动安全卫生制度，安全卫生设施\"三同时\"；提供合格防护用品并培训；如实告知工作场所职业危害及后果、防护措施；组织岗前/岗中/离岗职业健康检查；事故伤害30日内申请工伤认定。"],"sev":"高"},{"id":"R-SAFETY-03","cat":"entry_safety","catLabel":"劳动安全卫生","risk":"特种作业人员无证上岗","level":"ask","owner":"legal","module":"staff","enabled":true,"q":"从事特种作业的人员是否经专门培训并取得相应资格？","law":[{"ref":"《劳动法》第55条","text":"第55条　从事特种作业的劳动者必须经过专门培训并取得特种作业资格。"},{"ref":"《安全生产法》第30条","text":"第30条　生产经营单位的特种作业人员必须按照国家有关规定经专门的安全作业培训，取得相应资格，方可上岗作业。 特种作业人员的范围由国务院应急管理部门会同国务院有关部门确定。"}],"consequence":"责令限期改正，可处罚款；引发事故的追责","remedy":["建立健全劳动安全卫生制度，安全卫生设施\"三同时\"；提供合格防护用品并培训；如实告知工作场所职业危害及后果、防护措施；组织岗前/岗中/离岗职业健康检查；事故伤害30日内申请工伤认定。"],"sev":"高"},{"id":"R-SAFETY-04","cat":"entry_safety","catLabel":"劳动安全卫生","risk":"未对从业人员进行安全生产/职业卫生教育培训，或未如实告知危险因素","level":"ask","owner":"legal","module":"staff","enabled":true,"q":"是否对职工（含被派遣劳动者）进行安全卫生培训，并如实告知危险因素、防范措施、应急措施？","law":[{"ref":"《安全生产法》第28、44条","text":"第28条　生产经营单位应当对从业人员进行安全生产教育和培训，保证从业人员具备必要的安全生产知识，熟悉有关的安全生产规章制度和安全操作规程，掌握本岗位的安全操作技能，了解事故应急处理措施，知悉自身在安全生产方面的权利和义务。未经安全生产教育和培训合格的从业人员，不得上岗作业。 生产经营单位使用被派遣劳动者的，应当将被派遣劳动者纳入本单位从业人员统一管理，对被派遣劳动者进行岗位安全操作规程和安全操作技能的教育和培训。劳务派遣单位应当对被派遣劳动者进行必要的安全生产教育和培训。 生产经营单位接收中等职业学校、高等学校学生实习的，应当对实习学生进行相应的安全生产教育和培训，提供必要的劳动防护用品。学校应当协助生产经营单位对实习学生进行安全生产教育和培训。 生产经营单位应当建立安全生产教育和培训档案，如实记录安全生产教育和培训的时间、内容、参加人员以及考核结果等情况。\n第44条　生产经营单位应当教育和督促从业人员严格执行本单位的安全生产规章制度和安全操作规程；并向从业人员如实告知作业场所和工作岗位存在的危险因素、防范措施以及事故应急措施。 生产经营单位应当关注从业人员的身体、心理状况和行为习惯，加强对从业人员的心理疏导、精神慰藉，严格落实岗位安全生产责任，防范从业人员行为异常导致事故发生。"},{"ref":"《职业病防治法》第33、34条","text":"第33条　用人单位与劳动者订立劳动合同（含聘用合同，下同）时，应当将工作过程中可能产生的职业病危害及其后果、职业病防护措施和待遇等如实告知劳动者，并在劳动合同中写明，不得隐瞒或者欺骗。 劳动者在已订立劳动合同期间因工作岗位或者工作内容变更，从事与所订立劳动合同中未告知的存在职业病危害的作业时，用人单位应当依照前款规定，向劳动者履行如实告知的义务，并协商变更原劳动合同相关条款。 用人单位违反前两款规定的，劳动者有权拒绝从事存在职业病危害的作业，用人单位不得因此解除与劳动者所订立的劳动合同。\n第34条　用人单位的主要负责人和职业卫生管理人员应当接受职业卫生培训，遵守职业病防治法律、法规，依法组织本单位的职业病防治工作。 用人单位应当对劳动者进行上岗前的职业卫生培训和在岗期间的定期职业卫生培训，普及职业卫生知识，督促劳动者遵守职业病防治法律、法规、规章和操作规程，指导劳动者正确使用职业病防护设备和个人使用的职业病防护用品。 劳动者应当学习和掌握相关的职业卫生知识，增强职业病防范意识，遵守职业病防治法律、法规、规章和操作规程，正确使用、维护职业病防护设备和个人使用的职业病防护用品，发现职业病危害事故隐患应当及时报告。 劳动者不履行前款规定义务的，用人单位应当对其进行教育。"}],"consequence":"责令限期改正；导致事故的赔偿与追责","remedy":["建立健全劳动安全卫生制度，安全卫生设施\"三同时\"；提供合格防护用品并培训；如实告知工作场所职业危害及后果、防护措施；组织岗前/岗中/离岗职业健康检查；事故伤害30日内申请工伤认定。"],"sev":"高"},{"id":"R-SAFETY-05","cat":"entry_safety","catLabel":"劳动安全卫生","risk":"未组织上岗前、在岗期间、离岗时职业健康检查","level":"ask","owner":"legal","module":"staff","enabled":true,"q":"对接触职业病危害作业的劳动者，是否安排岗前/在岗/离岗职业健康检查并建立监护档案？","law":[{"ref":"《职业病防治法》第35、36条","text":"第35条　对从事接触职业病危害的作业的劳动者，用人单位应当按照国务院卫生行政部门的规定组织上岗前、在岗期间和离岗时的职业健康检查，并将检查结果书面告知劳动者。职业健康检查费用由用人单位承担。 用人单位不得安排未经上岗前职业健康检查的劳动者从事接触职业病危害的作业；不得安排有职业禁忌的劳动者从事其所禁忌的作业；对在职业健康检查中发现有与所从事的职业相关的健康损害的劳动者，应当调离原工作岗位，并妥善安置；对未进行离岗前职业健康检查的劳动者不得解除或者终止与其订立的劳动合同。 职业健康检查应当由取得《医疗机构执业许可证》的医疗卫生机构承担。卫生行政部门应当加强对职业健康检查工作的规范管理，具体管理办法由国务院卫生行政部门制定。\n第36条　用人单位应当为劳动者建立职业健康监护档案，并按照规定的期限妥善保存。 职业健康监护档案应当包括劳动者的职业史、职业病危害接触史、职业健康检查结果和职业病诊疗等有关个人健康资料。 劳动者离开用人单位时，有权索取本人职业健康监护档案复印件，用人单位应当如实、无偿提供，并在所提供的复印件上签章。"}],"consequence":"不得解除/终止未进行离岗体检的劳动者；造成职业病损害的赔偿","remedy":["建立健全劳动安全卫生制度，安全卫生设施\"三同时\"；提供合格防护用品并培训；如实告知工作场所职业危害及后果、防护措施；组织岗前/岗中/离岗职业健康检查；事故伤害30日内申请工伤认定。"],"sev":"高"},{"id":"R-SAFETY-06","cat":"entry_safety","catLabel":"劳动安全卫生","risk":"未依法参加工伤保险","level":"ask","owner":"legal","module":"staff","enabled":true,"q":"是否依法为全部职工参加工伤保险？","law":[{"ref":"《安全生产法》第51条","text":"第51条　生产经营单位必须依法参加工伤保险，为从业人员缴纳保险费。 国家鼓励生产经营单位投保安全生产责任保险；属于国家规定的高危行业、领域的生产经营单位，应当投保安全生产责任保险。具体范围和实施办法由国务院应急管理部门会同国务院财政部门、国务院保险监督管理机构和相关行业主管部门制定。"},{"ref":"《职业病防治法》第5、7条","text":"第5条　用人单位应当建立、健全职业病防治责任制，加强对职业病防治的管理，提高职业病防治水平，对本单位产生的职业病危害承担责任。\n第7条　用人单位必须依法参加工伤保险。 国务院和县级以上地方人民政府劳动保障行政部门应当加强对工伤保险的监督管理，确保劳动者依法享受工伤保险待遇。"},{"ref":"《工伤保险条例》第1、2条","text":"第1条　为了保障因工作遭受事故伤害或者患职业病的职工获得医疗救治和经济补偿，促进工伤预防和职业康复，分散用人单位的工伤风险，制定本条例。\n第2条　中华人民共和国境内的企业、事业单位、社会团体、民办非企业单位、基金会、律师事务所、会计师事务所等组织和有雇工的个体工商户（以下称用人单位）应当依照本条例规定参加工伤保险，为本单位全部职工或者雇工（以下称职工）缴纳工伤保险费。 中华人民共和国境内的企业、事业单位、社会团体、民办非企业单位、基金会、律师事务所、会计师事务所等组织的职工和个体工商户的雇工，均有依照本条例的规定享受工伤保险待遇的权利。"}],"consequence":"未参保期间发生工伤的，由用人单位按条例标准支付待遇","remedy":["建立健全劳动安全卫生制度，安全卫生设施\"三同时\"；提供合格防护用品并培训；如实告知工作场所职业危害及后果、防护措施；组织岗前/岗中/离岗职业健康检查；事故伤害30日内申请工伤认定。"],"sev":"高"},{"id":"R-SAFETY-07","cat":"entry_safety","catLabel":"劳动安全卫生","risk":"未如实告知职业病危害、未设置警示标识和中文说明","level":"ask","owner":"legal","module":"staff","enabled":true,"q":"是否如实告知职业病危害，并在醒目位置设置公告栏、警示标识和中文警示说明？","law":[{"ref":"《职业病防治法》第24、33条","text":"第24条　产生职业病危害的用人单位，应当在醒目位置设置公告栏，公布有关职业病防治的规章制度、操作规程、职业病危害事故应急救援措施和工作场所职业病危害因素检测结果。 对产生严重职业病危害的作业岗位，应当在其醒目位置，设置警示标识和中文警示说明。警示说明应当载明产生职业病危害的种类、后果、预防以及应急救治措施等内容。\n第33条　用人单位与劳动者订立劳动合同（含聘用合同，下同）时，应当将工作过程中可能产生的职业病危害及其后果、职业病防护措施和待遇等如实告知劳动者，并在劳动合同中写明，不得隐瞒或者欺骗。 劳动者在已订立劳动合同期间因工作岗位或者工作内容变更，从事与所订立劳动合同中未告知的存在职业病危害的作业时，用人单位应当依照前款规定，向劳动者履行如实告知的义务，并协商变更原劳动合同相关条款。 用人单位违反前两款规定的，劳动者有权拒绝从事存在职业病危害的作业，用人单位不得因此解除与劳动者所订立的劳动合同。"}],"consequence":"责令限期改正，给予警告，可并处罚款","remedy":["建立健全劳动安全卫生制度，安全卫生设施\"三同时\"；提供合格防护用品并培训；如实告知工作场所职业危害及后果、防护措施；组织岗前/岗中/离岗职业健康检查；事故伤害30日内申请工伤认定。"],"sev":"高"},{"id":"R-SAFETY-08","cat":"entry_safety","catLabel":"劳动安全卫生","risk":"违章指挥、强令冒险作业，或侮辱、体罚、殴打、非法搜查劳动者","level":"ask","owner":"legal","module":"staff","enabled":true,"q":"是否存在违章指挥/强令冒险作业，或以暴力威胁、侮辱体罚侵害劳动者？","law":[{"ref":"《劳动法》第56条","text":"第56条　劳动者在劳动过程中必须严格遵守安全操作规程。 劳动者对用人单位管理人员违章指挥、强令冒险作业，有权拒绝执行；对危害生命安全和身体健康的行为，有权提出批评、检举和控告。"},{"ref":"《劳动合同法》第32、88条","text":"第32条　劳动者拒绝用人单位管理人员违章指挥、强令冒险作业的，不视为违反劳动合同。 劳动者对危害生命安全和身体健康的劳动条件，有权对用人单位提出批评、检举和控告。\n第88条　用人单位有下列情形之一的，依法给予行政处罚；构成犯罪的，依法追究刑事责任；给劳动者造成损害的，应当承担赔偿责任： （一）以暴力、威胁或者非法限制人身自由的手段强迫劳动的； （二）违章指挥或者强令冒险作业危及劳动者人身安全的； （三）侮辱、体罚、殴打、非法搜查或者拘禁劳动者的； （四）劳动条件恶劣、环境污染严重，给劳动者身心健康造成严重损害的。"},{"ref":"《安全生产法》第54、55条","text":"第54条　从业人员有权对本单位安全生产工作中存在的问题提出批评、检举、控告；有权拒绝违章指挥和强令冒险作业。 生产经营单位不得因从业人员对本单位安全生产工作提出批评、检举、控告或者拒绝违章指挥、强令冒险作业而降低其工资、福利等待遇或者解除与其订立的劳动合同。\n第55条　从业人员发现直接危及人身安全的紧急情况时，有权停止作业或者在采取可能的应急措施后撤离作业场所。 生产经营单位不得因从业人员在前款紧急情况下停止作业或者采取紧急撤离措施而降低其工资、福利等待遇或者解除与其订立的劳动合同。"}],"consequence":"劳动者可立即解除并索补偿；造成损害的赔偿，严重的追究刑责","remedy":["建立健全劳动安全卫生制度，安全卫生设施\"三同时\"；提供合格防护用品并培训；如实告知工作场所职业危害及后果、防护措施；组织岗前/岗中/离岗职业健康检查；事故伤害30日内申请工伤认定。"],"sev":"高"},{"id":"R-SAFETY-09","cat":"entry_safety","catLabel":"劳动安全卫生","risk":"发生工伤事故未在规定时限内申请认定","level":"ask","owner":"legal","module":"staff","enabled":true,"q":"职工发生事故伤害，是否在30日内提出工伤认定申请（职工/近亲属/工会1年内）？","law":[{"ref":"《工伤保险条例》第17条","text":"第17条　职工发生事故伤害或者按照职业病防治法规定被诊断、鉴定为职业病，所在单位应当自事故伤害发生之日或者被诊断、鉴定为职业病之日起30日内，向统筹地区社会保险行政部门提出工伤认定申请。遇有特殊情况，经报社会保险行政部门同意，申请时限可以适当延长。 用人单位未按前款规定提出工伤认定申请的，工伤职工或者其近亲属、工会组织在事故伤害发生之日或者被诊断、鉴定为职业病之日起1年内，可以直接向用人单位所在地统筹地区社会保险行政部门提出工伤认定申请。 按照本条第一款规定应��由省级社会保险行政部门进行工伤认定的事项，根据属地原则由用人单位所在地的设区的市级社会保险行政部门办理。 用人单位未在本条第一款规定的时限内提交工伤认定申请，在此期间发生符合本条例规定的工伤待遇等有关费用由该用人单位负担。"},{"ref":"《工伤认定办法》第3、4、5、6、7、8条","text":"第3条　工伤认定应当客观公正、简捷方便，认定程序应当向社会公开。\n第4条　职工发生事故伤害或者按照职业病防治法规定被诊断、鉴定为职业病，所在单位应当自事故伤害发生之日或者被诊断、鉴定为职业病之日起30日内，向统筹地区社会保险行政部门提出工伤认定申请。遇有特殊情况，经报社会保险行政部门同意，申请时限可以适当延长。 按照前款规定应当向省级社会保险行政部门提出工伤认定申请的，根据属地原则应当向用人单位所在地设区的市级社会保险行政部门提出。\n第5条　用人单位未在规定的时限内提出工伤认定申请的，受伤害职工或者其近亲属、工会组织在事故伤害发生之日或者被诊断、鉴定为职业病之日起1年内，可以直接按照本办法第四条规定提出工伤认定申请。\n第6条　提出工伤认定申请应当填写《工伤认定申请表》，并提交下列材料： （一）劳动、聘用合同文本复印件或者与用人单位存在劳动关系（包括事实劳动关系）、人事关系的其他证明材料； （二）医疗机构出具的受伤后诊断证明书或者职业病诊断证明书（或者职业病诊断鉴定书）。\n第7条　工伤认定申请人提交的申请材料符合要求，属于社会保险行政部门管辖范围且在受理时限内的，社会保险行政部门应当受理。\n第8条　社会保险行政部门收到工伤认定申请后，应当在15日内对申请人提交的材料进行审核，材料完整的，作出受理或者不予受理的决定；材料不完整的，应当以书面形式一次性告知申请人需要补正的全部材料。社会保险行政部门收到申请人提交的全部补正材料后，应当在15日内作出受理或者不予受理的决定。 社会保险行政部门决定受理的，应当出具《工伤认定申请受理决定书》；决定不予受理的，应当出具《工伤认定申请不予受理决定书》。"}],"consequence":"单位逾期申请期间的工伤待遇费用由单位负担","remedy":["建立健全劳动安全卫生制度，安全卫生设施\"三同时\"；提供合格防护用品并培训；如实告知工作场所职业危害及后果、防护措施；组织岗前/岗中/离岗职业健康检查；事故伤害30日内申请工伤认定。"],"sev":"高"},{"id":"R-SAFETY-10","cat":"entry_safety","catLabel":"劳动安全卫生","risk":"劳动场所与员工宿舍安全距离不足、出口不畅","level":"ask","owner":"legal","module":"staff","enabled":true,"q":"生产经营场所与员工宿舍是否保持安全距离，出口和疏散通道是否畅通？","law":[{"ref":"《安全生产法》第42条","text":"第42条　生产、经营、储存、使用危险物品的车间、商店、仓库不得与员工宿舍在同一座建筑物内，并应当与员工宿舍保持安全距离。 生产经营场所和员工宿舍应当设有符合紧急疏散要求、标志明显、保持畅通的出口。禁止占用、锁闭、封堵生产经营场所或者员工宿舍的出口、疏散通道。"}],"consequence":"责令限期改正，可处罚款；事故的追责","remedy":["建立健全劳动安全卫生制度，安全卫生设施\"三同时\"；提供合格防护用品并培训；如实告知工作场所职业危害及后果、防护措施；组织岗前/岗中/离岗职业健康检查；事故伤害30日内申请工伤认定。"],"sev":"中"},{"id":"R-TERM-01","cat":"leave_terminate","catLabel":"合同解除","risk":"违法解除劳动合同（无合法事由、未履行通知工会程序、违反第42条）","level":"ask","owner":"hr","module":"staff","enabled":true,"q":"单方解除是否有法定事由（第39/40/41条），且事先通知工会、未触及第42条禁止情形？","law":[{"ref":"《劳动合同法》第39、40、41、42、43、87条","text":"第39条　劳动者有下列情形之一的，用人单位可以解除劳动合同： （一）在试用期间被证明不符合录用条件的； （二）严重违反用人单位的规章制度的； （三）严重失职，营私舞弊，给用人单位造成重大损害的； （四）劳动者同时与其他用人单位建立劳动关系，对完成本单位的工作任务造成严重影响，或者经用人单位提出，拒不改正的； （五）因本法第二十六条第一款第一项规定的情形致使劳动合同无效的； （六）被依法追究��事责任的。\n第40条　有下列情形之一的，用人单位提前三十日以书面形式通知劳动者本人或者额外支付劳动者一个月工资后，可以解除劳动合同： （一）劳动者患病或者非因工负伤，在规定的医疗期满后不能从事原工作，也不能从事由用人单位另行安排的工作的； （二）劳动者不能胜任工作，经过培训或者调整工作岗位，仍不能胜任工作的； （三）劳动合同订立时所依据的客观情况发生重大变化，致使劳动合同无法履行，经用人单位与劳动者协商，未能就变更劳动合同内容达成协议的。\n第41条　有下列情形之一，需要裁减人员二十人以上或者裁减不足二十人但占企业职工总数百分之十以上的，用人单位提前三十日向工会或者全体职工说明情况，听取工会或者职工的意见后，裁减人员方案经向劳动行政部门报告，可以裁减人员： （一）依照企业破产法规定进行重整的； （二）生产经营发生严重困难的； （三）企业转产、重大技术革新或者经营方式调整，经变更劳动合同后，仍需裁减人员的； （四）其他因劳动合同订立时所依据的客观经济情况发生重大变化，致使劳动合同无法履行的。 裁减人员时，应当优先留用下列人员： （一）与本单位订立较长期限的固定期限劳动合同的； （二）与本单位订立无固定期限劳动合同的； （三）家庭无其他就业人员，有需要扶养的老人或者未成年人的。 用人单位依照本条第一款规定裁减人员，在六个月内重新招用人员的，应当通知被裁减的人员，并在同等条件下优先招用被裁减的人员。\n第42条　劳动者有下列情形之一的，用人单位不得依照本法第四十条、第四十一条的规定解除劳动合同： （一）从事接触职业病危害作业的劳动者未进行离岗前职业健康检查，或者疑似职业病病人在诊断或者医学观察期间的； （二）在本单位患职业病或者因工负伤并被确认丧失或者部分丧失劳动能力的； （三）患病或者非因工负伤，在规定的医疗期内的； （四）女职工在孕期、产期、哺乳期的； （五）在本单位连续工作满十五年，且距法定退休年龄不足五年的； （六）法律、行政法规规定的其他情形。\n第43条　用人单位单方解除劳动合同，应当事先将理由通知工会。用人单位违反法律、行政法规规定或者劳动合同约定的，工会有权要求用人单位纠正。用人单位应当研究工会的意见，并将处理结果书面通知工会。\n第87条　用人单位违反本法规定解除或者终止劳动合同的，应当依照本法第四十七条规定的经济补偿标准的二倍向劳动者支付赔偿金。"},{"ref":"《劳动合同法实施条例》第18、19条","text":"第18条　有下列情形之一的，依照劳动合同法规定的条件、程序，劳动者可以与用人单位解除固定期限劳动合同、无固定期限劳动合同或者以完成一定工作任务为期限的劳动合同： （一）劳动者与用人单位协商一致的； （二）劳动者提前30日以书面形式通知用人单位的； （三）劳动者在试用期内提前3日通知用人单位的； （四）用人单位未按照劳动合同约定提供劳动保护或者劳动条件的； （五）用人单位未及时足额支付劳动报酬的； （六）用人单位未依法为劳动者缴纳社会保险费的； （七）用人单位的规章制度违反法律、法规的规定，损害劳动者权益的； （八）用人单位以欺诈、胁迫的手段或者乘人之危，使劳动者在违背真实意思的情况下订立或者变更劳动合同的； （九）用人单位在劳动合同中免除自己的法定责任、排除劳动者权利的； （十）用人单位违反法律、行政法规强制性规定的； （十一）用人单位以暴力、威胁或者非法限制人身自由的手段强迫劳动者劳动的； （十二）用人单位违章指挥、强令冒险作业危及劳动者人身安全的； （十三）法律、行政法规规定劳动者可以解除劳动合同的其他情形。\n第19条　有下列情形之一的，依照劳动合同法规定的条件、程序，用人单位可以与劳动者解除固定期限劳动合同、无固定期限劳动合同或者以完成一定工作任务为期限的劳动合同： （一）用人单位与劳动者协商一致的； （二）劳动者在试用期间被证明不符合录用条件的； （三）劳动者严重违反用人单位的规章制度的； （四）劳动者严重失职，营私舞弊，给用人单位造成重大损害的； （五）劳动者同时与其他用人单位建立劳动关系，对完成本单位的工作任务造成严重影响，或者经用人单位提出，拒不改正的； （六）劳动者以欺诈、胁迫的手段或者乘人之危，使用人单位在违背真实意思的情况下订立或者变更劳动合同的； （七）劳动者被依法追究刑事责任的； （八）劳动者患病或者非因工负伤，在规定的医疗期满后不能从事原工作，也不能从事由用人单位另行安排的工作的； （九）劳动者不能胜任工作，经过培训或者调整工作岗位，仍不能胜任工作的； （十）劳动合同订立时所依据的客观情况发生重大变化，致使劳动合同无法履行，经用人单位与劳动者协商，未能就变更劳动合同内容达成协议的； （十一）用人单位依照企业破产法规定进行重整的； （十二）用人单位生产经营发生严重困难的； （十三）企业转产、重大技术革新或者经营方式调整，经变更劳动合同后，仍需裁减人员的； （十四）其他因劳动合同订立时所依据的客观经济情况发生重大变化，致使劳动合同无法履行的。"}],"consequence":"违法解除，按经济补偿2倍支付赔偿金或继续履行；赔偿金与经济补偿不兼得（实施条例第25条）","remedy":["解除须有法定事由与充分证据；违法解除按经济补偿2倍（2N）赔偿或继续履行；医疗期、三期、工伤等情形不得依第40/41条解除；解除时出具证明并办理档案/社保转移。"],"sev":"高"},{"id":"R-TERM-02","cat":"leave_terminate","catLabel":"合同解除","risk":"依法解除但未支付经济补偿","level":"ask","owner":"hr","module":"staff","enabled":true,"q":"属于法定应支付经济补偿的解除情形（如第38条、第40条、第41条、协商解除由用人单位提出等），是否支付经济补偿（N）？","law":[{"ref":"《劳动合同法》第46、47条","text":"第46条　有下列情形之一的，用人单位应当向劳动者支付经济补偿： （一）劳动者依照本法第三十八条规定解除劳动合同的； （二）用人单位依照本法第三十六条规定向劳动者提出解除劳动合同并与劳动者协商一致解除劳动合同的； （三）用人单位依照本法第四十条规定解除劳动合同的； （四）用人单位依照本法第四十一条第一款规定解除劳动合同的； （五）除用人单位维持或者提高劳动合同约定条件续订劳动合同，劳动者不同意续订的情形外，依照本法第四十四条第一项规定终止固定期限劳动合同的； （六）依照本法第四十四条第四项、第五项规定终止劳动合同的； （七）法律、行政法规规定的其他情形。\n第47条　经济补偿按劳动者在本单位工作的年限，每满一年支付一个月工资的标准向劳动者支付。六个月以上不满一年的，按一年计算；不满六个月的，向劳动者支付半个月工资的经济补偿。 劳动者月工资高于用人单位所在直辖市、设区的市级人民政府公布的本地区上年度职工月平均工资三倍的，向其支付经济补偿的标准按职工月平均工资三倍的数额支付，向其支付经济补偿的年限最高不超过十二年。 本条所称月工资是指劳动者在劳动合同解除或者终止前十二个月的平均工资。"},{"ref":"《劳动合同法实施条例》第27条","text":"第27条　劳动合同法第四十七条规定的经济补偿的月工资按照劳动者应得工资计算，包括计时工资或者计件工资以及奖金、津贴和补贴等货币性收入。劳动者在劳动合同解除或者终止前12个月的平均工资低于当地最低工资标准的，按照当地最低工资标准计算。劳动者工作不满12个月的，按照实际工作的月数计算平均工资。"}],"consequence":"应支未支，劳动者可主张经济补偿及加付赔偿","remedy":["解除须有法定事由与充分证据；违法解除按经济补偿2倍（2N）赔偿或继续履行；医疗期、三期、工伤等情形不得依第40/41条解除；解除时出具证明并办理档案/社保转移。"],"sev":"中"},{"id":"R-TERM-03","cat":"leave_terminate","catLabel":"合同解除","risk":"用人单位存在过错（未足额付酬、未缴社保、未提供劳动保护等）致劳动者即时解除","level":"ask","owner":"hr","module":"staff","enabled":true,"q":"是否存在未足额支付报酬、未依法缴社保、未提供劳动保护等致员工可即时解除的情形？","law":[{"ref":"《劳动合同法》第38、46条","text":"第38条　用人单位有下列情形之一的，劳动者可以解除劳动合同： （一）未按照劳动合同约定提供劳动保护或者劳动条件的； （二）未及时足额支付劳动报酬的； （三）未依法为劳动者缴纳社会保险费的； （四）用人单位的规章制度违反法律、法规的规定，损害劳动者权益的； （五）因本法第二十六条第一款规定的情形致使劳动合同无效的； （六）法律、行政法规规定劳动者可以解除劳动合同的其他情形。 用人单位以暴力、威胁或者非法限制人身自由的手段强迫劳动者劳动的，或者用人单位违章指挥、强令冒险作业危及劳动者人身安全的，劳动者可以立即解除劳动合同，不需事先告知用人单位。\n第46条　有下列情形之一的，用人单位应当向劳动者支付经济补偿： （一）劳动者依照本法第三十八条规定解除劳动合同的； （二）用人单位依照本法第三十六条规定向劳动者提出解除劳动合同并与劳动者协商一致解除劳动合同的； （三）用人单位依照本法第四十条规定解除劳动合同的； （四）用人单位依照本法第四十一条第一款规定解除劳动合同的； （五）除用人单位维持或者提高劳动合同约定条件续订劳动合同，劳动者不同意续订的情形外，依照本法第四十四条第一项规定终止固定期限劳动合同的； （六）依照本法第四十四条第四项、第五项规定终止劳动合同的； （七）法律、行政法规规定的其他情形。"}],"consequence":"劳动者据此解除的，单位仍需支付经济补偿（N）","remedy":["解除须有法定事由与充分证据；违法解除按经济补偿2倍（2N）赔偿或继续履行；医疗期、三期、工伤等情形不得依第40/41条解除；解除时出具证明并办理档案/社保转移。"],"sev":"中"},{"id":"R-TERM-04","cat":"leave_terminate","catLabel":"合同解除","risk":"解除后未出具证明、未办理档案和社保关系转移","level":"ask","owner":"hr","module":"staff","enabled":true,"q":"解除/终止劳动合同是否出具证明，并在15日内办理档案和社保关系转移？","law":[{"ref":"《劳动合同法》第50、89条","text":"第50条　用人单位应当在解除或者终止劳动合同时出具解除或者终止劳动合同的证明，并在十五日内为劳动者办理档案和社会保险关系转移手续。 劳动者应当按照双方约定，办理工作交接。用人单位依照本法有关规定应当向劳动者支付经济补偿的，在办结工作交接时支付。 用人单位对已经解除或者终止的劳动合同的文本，至少保存二年备查。\n第89条　用人单位违反本法规定未向劳动者出具解除或者终止劳动合同的书面证明，由劳动行政部门责令改正；给劳动者造成损害的，应当承担赔偿责任。"}],"consequence":"未出具证明造成损害的承担赔偿责任","remedy":["解除须有法定事由与充分证据；违法解除按经济补偿2倍（2N）赔偿或继续履行；医疗期、三期、工伤等情形不得依第40/41条解除；解除时出具证明并办理档案/社保转移。"],"sev":"中"},{"id":"R-TERM-05","cat":"leave_terminate","catLabel":"合同解除","risk":"经济性裁员程序违法（未提前30日向工会/全体职工说明、未报告）","level":"ask","owner":"hr","module":"staff","enabled":true,"q":"裁员20人以上或占10%以上时，是否提前30日向工会/职工说明、听取意见并向劳动行政部门报告？","law":[{"ref":"《劳动合同法》第41条","text":"第41条　有下列情形之一，需要裁减人员二十人以上或者裁减不足二十人但占企业职工总数百分之十以上的，用人单位提前三十日向工会或者全体职工说明情况，听取工会或者职工的意见后，裁减人员方案经向劳动行政部门报告，可以裁减人员： （一）依照企业破产法规定进行重整的； （二）生产经营发生严重困难的； （三）企业转产、重大技术革新或者经营方式调整，经变更劳动合同后，仍需裁减人员的； （四）其他因劳动合同订立时所依据的客观经济情况发生重大变化，致使劳动合同无法履行的。 裁减人员时，应当优先留用下列人员： （一）与本单位订立较长期限的固定期限劳动合同的； （二）与本单位订立无固定期限劳动合同的； （三）家庭无其他就业人员，有需要扶养的老人或者未成年人的。 用人单位依照本条第一款规定裁减人员，在六个月内重新招用人员的，应当通知被裁减的人员，并在同等条件下优先招用被裁减的人员。"}],"consequence":"程序违法的裁员无效，按违法解除赔偿","remedy":["解除须有法定事由与充分证据；违法解除按经济补偿2倍（2N）赔偿或继续履行；医疗期、三期、工伤等情形不得依第40/41条解除；解除时出具证明并办理档案/社保转移。"],"sev":"高"},{"id":"R-TERM-06","cat":"leave_terminate","catLabel":"合同解除","risk":"试用期解除不符合法定条件（同 R-PROB-03，贯穿解除环节）","level":"ask","owner":"hr","module":"staff","enabled":true,"q":"试用期解除是否证明不符合录用条件，且未对孕期女职工解除？","law":[{"ref":"《劳动合同法》第21、42条","text":"第21条　在试用期中，除劳动者有本法第三十九条和第四十条第一项、第二项规定的情形外，用人单位不得解除劳动合同。用人单位在试用期解除劳动合同的，应当向劳动者说明理由。\n第42条　劳动者有下列情形之一的，用人单位不得依照本法第四十条、第四十一条的规定解除劳动合同： （一）从事接触职业病危害作业的劳动者未进行离岗前职业健康检查，或者疑似职业病病人在诊断或者医学观察期间的； （二）在本单位患职业病或者因工负伤并被确认丧失或者部分丧失劳动能力的； （三）患病或者非因工负伤，在规定的医疗期内的； （四）女职工在孕期、产期、哺乳期的； （五）在本单位连续工作满十五年，且距法定退休年龄不足五年的； （六）法律、行政法规规定的其他情形。"}],"consequence":"违法解除，2倍赔偿或继续履行","remedy":["解除须有法定事由与充分证据；违法解除按经济补偿2倍（2N）赔偿或继续履行；医疗期、三期、工伤等情形不得依第40/41条解除；解除时出具证明并办理档案/社保转移。"],"sev":"高"},{"id":"R-END-01","cat":"leave_end","catLabel":"合同终止","risk":"约定法定情形以外的终止条件，或违法终止","level":"ask","owner":"hr","module":"staff","enabled":true,"q":"劳动合同是否仅约定法定终止情形（期满、退休、死亡、破产、吊销等），无额外违法终止条款？","law":[{"ref":"《劳动合同法》第44条","text":"第44条　有下列情形之一的，劳动合同终止： （一）劳动合同期满的； （二）劳动者开始依法享受基本养老保险待遇的； （三）劳动者死亡，或者被人民法院宣告死亡或者宣告失踪的； （四）用人单位被依法宣告破产的； （五）用人单位被吊销营业执照、责令关闭、撤销或者用人单位决定提前解散的； （六）法律、行政法规规定的其他情形。"},{"ref":"《劳动合同法实施条例》第13条","text":"第13条　用人单位与劳动者不得在劳动合同法第四十四条规定的劳动合同终止情形之外约定其他的劳动合同终止条件。"}],"consequence":"违法终止，按经济补偿2倍赔偿或继续履行","remedy":["终止须合法；遇法定顺延情形续延至消失；固定期限期满终止依法支付经济补偿（N）；出具终止证明并办理档案与社保关系转移手续。"],"sev":"中"},{"id":"R-END-02","cat":"leave_end","catLabel":"合同终止","risk":"合同期满但劳动者有第42条情形未续延即终止","level":"ask","owner":"hr","module":"staff","enabled":true,"q":"合同期满时劳动者处于医疗期、三期、工伤1–6级等，是否续延至情形消失再终止？","law":[{"ref":"《劳动合同法》第45条","text":"第45条　劳动合同期满，有本法第四十二条规定情形之一的，劳动合同应当续延至相应的情形消失时终止。但是，本法第四十二条第二项规定丧失或者部分丧失劳动能力劳动者的劳动合同的终止，按照国家有关工���保险的规定执行。"}],"consequence":"违法终止，2倍赔偿或继续履行","remedy":["终止须合法；遇法定顺延情形续延至消失；固定期限期满终止依法支付经济补偿（N）；出具终止证明并办理档案与社保关系转移手续。"],"sev":"高"},{"id":"R-END-03","cat":"leave_end","catLabel":"合同终止","risk":"终止未依法支付经济补偿（破产、吊销、期满等情形）","level":"ask","owner":"hr","module":"staff","enabled":true,"q":"因破产、被吊销、责令关闭或期满等终止的，是否依法支付经济补偿（N）？","law":[{"ref":"《劳动合同法》第46、47条","text":"第46条　有下列情形之一的，用人单位应当向劳动者支付经济补偿： （一）劳动者依照本法第三十八条规定解除劳动合同的； （二）用人单位依照本法第三十六条规定向劳动者提出解除劳动合同并与劳动者协商一致解除劳动合同的； （三）用人单位依照本法第四十条规定解除劳动合同的； （四）用人单位依照本法第四十一条第一款规定解除劳动合同的； （五）除用人单位维持或者提高劳动合同约定条件续订劳动合同，劳动者不同意续订的情形外，依照本法第四十四条第一项规定终止固定期限劳动合同的； （六）依照本法第四十四条第四项、第五项规定终止劳动合同的； （七）法律、行政法规规定的其他情形。\n第47条　经济补偿按劳动者在本单位工作的年限，每满一年支付一个月工资的标准向劳动者支付。六个月以上不满一年的，按一年计算；不满六个月的，向劳动者支付半个月工资的经济补偿。 劳动者月工资高于用人单位所在直辖市、设区的市级人民政府公布的本地区上年度职工月平均工资三倍的，向其支付经济补偿的标准按职工月平均工资三倍的数额支付，向其支付经济补偿的年限最高不超过十二年。 本条所称月工资是指劳动者在劳动合同解除或者终止前十二个月的平均工资。"}],"consequence":"应支未支，劳动者可主张经济补偿及加付赔偿","remedy":["终止须合法；遇法定顺延情形续延至消失；固定期限期满终止依法支付经济补偿（N）；出具终止证明并办理档案与社保关系转移手续。"],"sev":"中"},{"id":"R-END-04","cat":"leave_end","catLabel":"合同终止","risk":"对未进行离岗职业健康检查、或疑似职业病在诊断观察期的劳动者终止合同","level":"ask","owner":"hr","module":"staff","enabled":true,"q":"接触职业病危害作业的劳动者离职时，是否先做离岗职业健康检查后再终止？","law":[{"ref":"《职业病防治法》第35条","text":"第35条　对从事接触职业病危害的作业的劳动者，用人单位应当按照国务院卫生行政部门的规定组织上岗前、在岗期间和离岗时的职业健康检查，并将检查结果书面告知劳动者。职业健康检查费用由用人单位承担。 用人单位不得安排未经上岗前职业健康检查的劳动者从事接触职业病危害的作业；不得安排有职业禁忌的劳动者从事其所禁忌的作业；对在职业健康检查中发现有与所从事的职业相关的健康损害的劳动者，应当调离原工作岗位，并妥善安置；对未进行离岗前职业健康检查的劳动者不得解除或者终止与其订立的劳动合同。 职业健康检查应当由取得《医疗机构执业许可证》的医疗卫生机构承担。卫生行政部门应当加强对职业健康检查工作的规范管理，具体管理办法由国务院卫生行政部门制定。"},{"ref":"《劳动合同法》第45条","text":"第45条　劳动合同期满，有本法第四十二条规定情形之一的，劳动合同应当续延至相应的情形消失时终止。但是，本法第四十二条第二项规定丧失或者部分丧失劳动能力劳动者的劳动合同的终止，按照国家有关工���保险的规定执行。"}],"consequence":"不得终止，违法终止按2倍赔偿","remedy":["终止须合法；遇法定顺延情形续延至消失；固定期限期满终止依法支付经济补偿（N）；出具终止证明并办理档案与社保关系转移手续。"],"sev":"高"},{"id":"R-END-05","cat":"leave_end","catLabel":"合同终止","risk":"终止后未出具终止证明、未办理转移手续","level":"ask","owner":"hr","module":"staff","enabled":true,"q":"终止劳动合同是否出具证明并在15日内办理档案和社保转移？","law":[{"ref":"《劳动合同法》第50条","text":"第50条　用人单位应当在解除或者终止劳动合同时出具解除或者终止劳动合同的证明，并在十五日内为劳动者办理档案和社会保险关系转移手续。 劳动者应当按照双方约定，办理工作交接。用人单位依照本法有关规定应当向劳动者支付经济补偿的，在办结工作交接时支付。 用人单位对已经解除或者终止的劳动合同的文本，至少保存二年备查。"}],"consequence":"未出具证明造成损害的赔偿","remedy":["终止须合法；遇法定顺延情形续延至消失；固定期限期满终止依法支付经济补偿（N）；出具终止证明并办理档案与社保关系转移手续。"],"sev":"中"},{"id":"R-SERVICE-01","cat":"leave_service","catLabel":"服务期","risk":"违法约定服务期，或违约金超过实际培训费用","level":"ask","owner":"hr","module":"staff","enabled":true,"q":"服务期是否仅针对专项培训费用培训，且违约金不超过尚未履行部分所分摊的培训费用？","law":[{"ref":"《劳动合同法》第22、25条","text":"第22条　用人单位为劳动者提供专项培训费用，对其进行专业技术培训的，可以与该劳动者订立协议，约定服务期。 劳动者违反服务期约定的，应当按照约定向用人单位支付违约金。违约金的数额不得超过用人单位提供的培训费用。用人单位要求劳动者支付的违约金不得超过服务期尚未履行部分所应分摊的培训费用。 用人单位与劳动者约定服务期的，不影响按照正常的工资调整机制提高劳动者在服务期期间的劳动报酬。\n第25条　除本法第二十二条和第二十三条规定的情形外，用人单位不得与劳动者约定由劳动者承担违约金。"},{"ref":"《劳动合同法实施条例》第16、17条","text":"第16条　劳动合同法第二十二条第二款规定的培训费用，包括用人单位为了对劳动者进行专业技术培训而支付的有凭证的培训费用、培训期间的差旅费用以及因培训产生的用于该劳动者的其他直接费用。\n第17条　劳动合同期满，但是用人单位与劳动者依照劳动合同法第二十二条的规定约定的服务期尚未到期的，劳动合同应当续延至服务期满；双方另有约定的，从其约定。"}],"consequence":"超范围约定无效；违约金超限部分无效","remedy":["仅对提供专项培训费用的专业技术培训约定服务期；违约金不超过尚未履行部分所分摊的培训费用；劳动合同期满而服务期未满的延续至服务期满（另有约定除外）。"],"sev":"中"},{"id":"R-SERVICE-02","cat":"leave_service","catLabel":"服务期","risk":"劳动合同期满但服务期未届满，未延续至服务期满","level":"ask","owner":"hr","module":"staff","enabled":true,"q":"合同期满而服务期未满的，是否延续至服务期满（除非双方另有约定）？","law":[{"ref":"《劳动合同法实施条例》第17条","text":"第17条　劳动合同期满，但是用人单位与劳动者依照劳动合同法第二十二条的规定约定的服务期尚未到期的，劳动合同应当续延至服务期满；双方另有约定的，从其约定。"}],"consequence":"未延续致劳动者提前离职的争议","remedy":["仅对提供专项培训费用的专业技术培训约定服务期；违约金不超过尚未履行部分所分摊的培训费用；劳动合同期满而服务期未满的延续至服务期满（另有约定除外）。"],"sev":"中"},{"id":"R-SERVICE-03","cat":"leave_service","catLabel":"服务期","risk":"服务期违约金支付情形界定不清（谁违约、是否退费）","level":"ask","owner":"hr","module":"staff","enabled":true,"q":"服务期违约金的支付与返还是否按「培训费用分摊+过错」规则明确？","law":[{"ref":"《劳动合同法实施条例》第26条","text":"第26条　用人单位与劳动者约定了服务期，劳动者依照劳动合同法第三十八条的规定解除劳动合同的，不属于违反服务期的约定，用人单位不得要求劳动者支付违约金。 有下列情形之一，用人单位与劳动者解除约定服务期的劳动合同的，劳动者应当按照劳动合同的约定向用人单位支付违约金： （一）劳动者严重违反用人单位的规章制度的； （二）劳动者严重失职，营私舞弊，给用人单位造成重大损害的； （三）劳动者同时与其他用人单位建立劳动关系，对完成本单位的工作任务造成严重影响，或者经用人单位提出，拒不改正的； （四）劳动者以欺诈、胁迫的手段或者乘人之危，使用人单位在违背真实意思的情况下订立或者变更劳动合同的； （五）劳动者被依法追究刑事责任的。"}],"consequence":"约定不清易引发争议，按法定规则处理","remedy":["仅对提供专项培训费用的专业技术培训约定服务期；违约金不超过尚未履行部分所分摊的培训费用；劳动合同期满而服务期未满的延续至服务期满（另有约定除外）。"],"sev":"低"},{"id":"R-NONCOMP-01","cat":"leave_noncompete","catLabel":"竞业限制","risk":"竞业限制人员范围过宽、期限超过2年或地域/范围不合理","level":"ask","owner":"hr","module":"staff","enabled":true,"q":"竞业限制是否仅限高管、高技和其他负有保密义务人员，期限≤2年，范围地域合理？","law":[{"ref":"《劳动合同法》第23、24、25条","text":"第23条　用人单位与劳动者可以在劳动合同中约定保守用人单位的商业秘密和与知识产权相关的保密事项。 对负有保密义务的劳动者，用人单位可以在劳动合同或者保密协议中与劳动者约定竞业限制条款，并约定在解除或者终止劳动合同后，在竞业限制期限内按月给予劳动者经济补偿。劳动者违反竞业限制约定的，应当按照约定向用人单位支付违约金。\n第24条　竞业限制的人员限于用人单位的高级管理人员、高级技术人员和其他负有保密义务的人员。竞业限制的范围、地域、期限由用人单位与劳动者约定，竞业限制的约定不得违反法律、法规的规定。 在解除或者终止劳动合同后，前款规定的人员到与本单位生产或者经营同类产品、从事同类业务的有竞争关系的其他用人单位，或者自己开业生产或者经营同类产品、从事同类业务的竞业限制期限，不得超过二年。\n第25条　除本法第二十二条和第二十三条规定的情形外，用人单位不得与劳动者约定由劳动者承担违约金。"}],"consequence":"超范围/超期限约定可能被认定无效","remedy":["竞业限制限于高管、高级技术人员和其他负有保密义务人员，期限不超2年；解除或终止后按月支付补偿（不低于离职前12个月平均工资30%且不低于最低工资）；超期或主体不适格部分无效，超3个月未付补偿劳动者可解除。"],"sev":"中"},{"id":"R-NONCOMP-02","cat":"leave_noncompete","catLabel":"竞业限制","risk":"约定竞业限制但未在离职后按月支付经济补偿","level":"ask","owner":"hr","module":"staff","enabled":true,"q":"离职后是否按月向履行竞业限制的劳动者支付经济补偿？","law":[{"ref":"《劳动合同法》第23条","text":"第23条　用人单位与劳动者可以在劳动合同中约定保守用人单位的商业秘密和与知识产权相关的保密事项。 对负有保密义务的劳动者，用人单位可以在劳动合同或者保密协议中与劳动者约定竞业限制条款，并约定在解除或者终止劳动合同后，在竞业限制期限内按月给予劳动者经济补偿。劳动者违反竞业限制约定的，应当按照约定向用人单位支付违约金。"}],"consequence":"未支付补偿达一定期限，劳动者可解除竞业限制约定","remedy":["竞业限制限于高管、高级技术人员和其他负有保密义务人员，期限不超2年；解除或终止后按月支付补偿（不低于离职前12个月平均工资30%且不低于最低工资）；超期或主体不适格部分无效，超3个月未付补偿劳动者可解除。"],"sev":"中"},{"id":"R-NONCOMP-03","cat":"leave_noncompete","catLabel":"竞业限制","risk":"违法约定劳动者违约金（超出服务期、竞业限制两类）","level":"ask","owner":"hr","module":"staff","enabled":true,"q":"除服务期、竞业限制外，是否与劳动者约定由劳动者承担的违约金？","law":[{"ref":"《劳动合同法》第25条","text":"第25条　除本法第二十二条和第二十三条规定的情形外，用人单位不得与劳动者约定由劳动者承担违约金。"}],"consequence":"该类违约金约定无效","remedy":["竞业限制限于高管、高级技术人员和其他负有保密义务人员，期限不超2年；解除或终止后按月支付补偿（不低于离职前12个月平均工资30%且不低于最低工资）；超期或主体不适格部分无效，超3个月未付补偿劳动者可解除。"],"sev":"中"},{"id":"R-IP-01","cat":"leave_ip","catLabel":"知识产权","risk":"职务发明创造权属与奖励报酬未落实","level":"ask","owner":"legal","module":"staff","enabled":true,"q":"执行本单位任务或主要利用本单位物质技术条件完成的发明，是否归单位所有并给予奖励和合理报酬？","law":[{"ref":"《专利法》第6、15条","text":"第6条　执行本单位的任务或者主要是利用本单位的物质技术条件所完成的发明创造为职务发明创造。职务发明创造申请专利的权利属于该单位，申请被批准后，该单位为专利权人。该单位可以依法处置其职务发明创造申请专利的权利和专利权，促进相关发明创造的实施和运用。 非职务发明创造，申请专利的权利属于发明人或者设计人；申请被批准后，该发明人或者设计人为专利权人。 利用本单位的物质技术条件所完成的发明创造，单位与发明人或者设计人订有合同，对申请专利的权利和专利权的归属作出约定的，从其约定。\n第15条　被授予专利权的单位应当对职务发明创造的发明人或者设计人给予奖励；发明创造专利实施后，根据其推广应用的范围和取得的经济效益，对发明人或者设计人给予合理的报酬。 国家鼓励被授予专利权的单位实行产权激励，采取股权、期权、分红等方式，使发明人或者设计人合理分享创新收益。"},{"ref":"《专利法实施细则》第12条","text":"第12条　除专利法第二十八条和第四十二条规定的情形外，专利法所称申请日，有优先权的，指优先权日。 本细则所称申请日，除另有规定的外，是指专利法第二十八条规定的申请日。"}],"consequence":"权属争议；未给奖励报酬的，发明人可主张","remedy":["明确职务发明创造归属单位；约定保密义务与涉密载体管理；离职办理技术资料与涉密载体交接；不侵犯原单位知识产权与商业秘密。"],"sev":"中"},{"id":"R-IP-02","cat":"leave_ip","catLabel":"知识产权","risk":"未约定保密义务，或劳动者违反保密约定造成损失","level":"ask","owner":"legal","module":"staff","enabled":true,"q":"劳动合同中是否约定保守商业秘密条款，并对违约泄密追责？","law":[{"ref":"《劳动法》第22、102条","text":"第22条　劳动合同当事人可以在劳动合同中约定保守用人单位商业秘密的有关事项。\n第102条　劳动者违反本法规定的条件解除劳动合同或者违反劳动合同中约定的保密事项，对用人单位造成经济损失的，应当依法承担赔偿责任。"},{"ref":"《劳动合同法》第23条","text":"第23条　用人单位与劳动者可以在劳动合同中约定保守用人单位的商业秘密和与知识产权相关的保密事项。 对负有保密义务的劳动者，用人单位可以在劳动合同或者保密协议中与劳动者约定竞业限制条款，并约定在解除或者终止劳动合同后，在竞业限制期限内按月给予劳动者经济补偿。劳动者违反竞业限制约定的，应当按照约定向用人单位支付违约金。"}],"consequence":"违反保密约定造成损失，承担赔偿责任","remedy":["明确职务发明创造归属单位；约定保密义务与涉密载体管理；离职办理技术资料与涉密载体交接；不侵犯原单位知识产权与商业秘密。"],"sev":"中"},{"id":"R-IP-03","cat":"leave_ip","catLabel":"知识产权","risk":"离职后1年内作出的与原任务相关的发明权属不清","level":"ask","owner":"legal","module":"staff","enabled":true,"q":"离职员工1年内作出的与原单位任务相关的发明，是否按职务发明处理？","law":[{"ref":"《专利法实施细则》第12条","text":"第12条　除专利法第二十八条和第四十二条规定的情形外，专利法所称申请日，有优先权的，指优先权日。 本细则所称申请日，除另有规定的外，是指专利法第二十八条规定的申请日。"}],"consequence":"权属争议风险","remedy":["明确职务发明创造归属单位；约定保密义务与涉密载体管理；离职办理技术资料与涉密载体交接；不侵犯原单位知识产权与商业秘密。"],"sev":"低"},{"id":"R-DISP-01","cat":"special_dispatch","catLabel":"劳务派遣","risk":"劳务派遣单位无行政许可或注册资本不足200万元即经营派遣","level":"ask","owner":"legal","module":"staff","enabled":true,"q":"合作的劳务派遣单位是否取得行政许可且注册资本≥200万元？","law":[{"ref":"《劳动合同法》第57条","text":"第57条　经营劳务派遣业务应当具备下列条件： （一）注册资本不得少于人民币二百万元； （二）有与开展业务相适应的固定的经营场所和设施； （三）有符合法律、行政法规规定的劳务派遣管理制度； （四）法律、行政法规规定的其他条件。 经营劳务派遣业务，应当向劳动行政部门依法申请行政许可；经许可的，依法办理相应的公司登记。未经许可，任何单位和个人不得经营劳务派遣业务。"}],"consequence":"未经许可经营派遣，依法处罚并没收违法所得","remedy":["查验劳务派遣单位《劳务派遣经营许可证》；仅\"三性\"岗位使用且用工比例不超10%；落实同工同酬；派遣工工伤由派遣单位担责，用工单位未尽义务承担连带责任。"],"sev":"高"},{"id":"R-DISP-02","cat":"special_dispatch","catLabel":"劳务派遣","risk":"劳务派遣用工超出「三性」岗位或超过用工总量10%比例","level":"ask","owner":"legal","module":"staff","enabled":true,"q":"派遣岗位是否确属临时性(≤6月)/辅助性/替代性，且派遣用工≤用工总量10%？","law":[{"ref":"《劳动合同法》第66条","text":"第66条　劳动合同用工是我国的企业基本用工形式。劳务派遣用工是补充形式，只能在临时性、辅助性或者替代性的工作岗位上实施。 前款规定的临时性工作岗位是指存续时间不超过六个月的岗位；辅助性工作岗位是指为主营业务岗位提供服务的非主营业务岗位；替代性工作岗位是指用工单位的劳动者因脱产学习、休假等原因无法工作的一定期间内，可以由其他劳动者替代工作的岗位。 用工单位应当严格控制劳务派遣用工数量，不得超过其用工总量的一定比例，具体比例由国务院劳动行政部门规定。"},{"ref":"《劳务派遣暂行规定》第3、4条","text":"第3条　用工单位只能在临时性、辅助性或者替代性的工作岗位上使用被派遣劳动者。 前款规定的临时性工作岗位是指存续时间不超过6个月的岗位；辅助性工作岗位是指为主营业务岗位提供服务的非主营业务岗位；替代性工作岗位是指用工单位的劳动者因脱产学习、休假等原因无法工作的一定期间内，可以由其他劳动者替代工作的岗位。 用工单位决定使用被派遣劳动者的辅助性岗位，应当经职工代表大会或者全体职工讨论，提出方案和意见，与工会或者职工代表平等协商确定，并在用工单位内公示。\n第4条　用工单位应当严格控制劳务派遣用工数量，使用的被派遣劳动者数量不得超过其用工总量的10%。 前款所称用工总量是指用工单位订立劳动合同人数与使用的被派遣劳动者人数之和。 计算劳务派遣用工比例的用工单位是指依照劳动合同法和劳动合同法实施条例可以与劳动者订立劳动合同的用人单位。"}],"consequence":"违反的，按劳动合同法第92条处罚","remedy":["查验劳务派遣单位《劳务派遣经营许可证》；仅\"三性\"岗位使用且用工比例不超10%；落实同工同酬；派遣工工伤由派遣单位担责，用工单位未尽义务承担连带责任。"],"sev":"高"},{"id":"R-DISP-03","cat":"special_dispatch","catLabel":"劳务派遣","risk":"派遣单位未订2年以上固定期限合同、克扣工资或向劳动者收费","level":"ask","owner":"legal","module":"staff","enabled":true,"q":"派遣单位是否订2年以上固定期限合同、按月付酬、不克扣用工单位付酬、不向劳动者收费？","law":[{"ref":"《劳动合同法》第58、60条","text":"第58条　劳务派遣单位是本法所称用人单位，应当履行用人单位对劳动者的义务。劳务派遣单位与被派遣劳动者订立的劳动合同，除应当载明本法第十七条规定的事项外，还应当载明被派遣劳动者的用工单位以及派遣期限、工作岗位等情况。 劳务派遣单位应当与被派遣劳动者订立二年以上的固定期限劳动合同，按月支付劳动报酬；被派遣劳动者在无工作期间，劳务派遣单位应当按照所在地人民政府规定的最低工资标准，向其按月支付报酬。\n第60条　劳务派遣单位应当将劳务派遣协议的内容告知被派遣劳动者。 劳务派遣单位不得克扣用工单位按照劳务派遣协议支付给被派遣劳动者的劳动报酬。 劳务派遣单位和用工单位不得向被派遣劳动者收取费用。"},{"ref":"《劳务派遣暂行规定》第5、6、8条","text":"第5条　劳务派遣单位应当依法与被派遣劳动者订立2年以上的固定期限书面劳动合同。\n第6条　劳务派遣单位可以依法与被派遣劳动者约定试用期。劳务派遣单位与同一被派遣劳动者只能约定一次试用期。\n第8条　劳务派遣单位应当对被派遣劳动者履行下列义务： （一）如实告知被派遣劳动者劳动合同法第八条规定的事项、应遵守的规章制度以及劳务派遣协议的内容； （二）建立培训制度，对被派遣劳动者进行上岗知识、安全教育培训； （三）按照国家规定和劳务派遣协议约定，依法支付被派遣劳动者的劳动报酬和相关待遇； （四）按照国家规定和劳务派遣协议约定，依法为被派遣劳动者缴纳社会保险费，并办理社会保险相关手续； （五）督促用工单位依法为被派遣劳动者提供劳动保护和劳动安全卫生条件； （六）依法出具解除或者终止劳动合同的证明； （七）协助处理被派遣劳动者与用工单位的纠纷； （八）法律、法规和规章规定的其他事项。"}],"consequence":"违反按第92条处罚；克扣工资等承担赔偿责任","remedy":["查验劳务派遣单位《劳务派遣经营许可证》；仅\"三性\"岗位使用且用工比例不超10%；落实同工同酬；派遣工工伤由派遣单位担责，用工单位未尽义务承担连带责任。"],"sev":"高"},{"id":"R-DISP-04","cat":"special_dispatch","catLabel":"劳务派遣","risk":"被派遣劳动者与用工单位劳动者未同工同酬","level":"ask","owner":"legal","module":"staff","enabled":true,"q":"被派遣劳动者是否享有与用工单位同类岗位劳动者同工同酬的权利？","law":[{"ref":"《劳动合同法》第63条","text":"第63条　被派遣劳动者享有与用工单位的劳动者同工同酬的权利。用工单位应当按照同工同酬原则，对被派遣劳动者与��单位同类岗位的劳动者实行相同的劳动报酬分配办法。用工单位无同类岗位劳动者的，参照用工单位所在地相同或者相近岗位劳动者的劳动报酬确定。 劳务派遣单位与被派遣劳动者订立的劳动合同和与用工单位订立的劳务派遣协议，载明或者约定的向被派遣劳动者支付的劳动报酬应当符合前款规定。"},{"ref":"《劳务派遣暂行规定》第9条","text":"第9条　用工单位应当按照劳动合同法第六十二条规定，向被派遣劳动者提供与工作岗位相关的福利待遇，不得歧视被派遣劳动者。"}],"consequence":"工资歧视引发争议，补足差额","remedy":["查验劳务派遣单位《劳务派遣经营许可证》；仅\"三性\"岗位使用且用工比例不超10%；落实同工同酬；派遣工工伤由派遣单位担责，用工单位未尽义务承担连带责任。"],"sev":"高"},{"id":"R-DISP-05","cat":"special_dispatch","catLabel":"劳务派遣","risk":"用人单位自设劳务派遣单位向本单位或所属单位派遣（自我派遣）","level":"ask","owner":"legal","module":"staff","enabled":true,"q":"是否设立劳务派遣单位向本单位或所属单位派遣劳动者？","law":[{"ref":"《劳动合同法》第67条","text":"第67条　用人单位不得设立劳务派遣单位向本单位或者所属单位派遣劳动者。"}],"consequence":"按第92条处罚","remedy":["查验劳务派遣单位《劳务派遣经营许可证》；仅\"三性\"岗位使用且用工比例不超10%；落实同工同酬；派遣工工伤由派遣单位担责，用工单位未尽义务承担连带责任。"],"sev":"高"},{"id":"R-DISP-06","cat":"special_dispatch","catLabel":"劳务派遣","risk":"劳务派遣中工伤责任主体不清（谁申请、谁承担）","level":"ask","owner":"legal","module":"staff","enabled":true,"q":"被派遣劳动者发生工伤，是否由派遣单位申请认定并承担工伤保险责任、用工单位协助？","law":[{"ref":"《劳务派遣暂行规定》第10条","text":"第10条　被派遣劳动者在用工单位因工作遭受事故伤害的，劳务派遣单位应当依法申请工伤认定，用工单位应当协助工伤认定的调查核实工作。劳务派遣单位承担工伤保险责任，但可以与用工单位约定补偿办法。 被派遣劳动者在申请进行职业病诊断、鉴定时，用工单位应当负责处理职业病诊断、鉴定事宜，并如实提供职业病诊断、鉴定所需的劳动者职业史和职业危害接触史、工作场所职业病危害因素检测结果等资料，劳务派遣单位应当提供被派遣劳动者职业病诊断、鉴定所需的其他材料。"}],"consequence":"责任不清致工伤待遇落空的，相关单位连带赔偿","remedy":["查验劳务派遣单位《劳务派遣经营许可证》；仅\"三性\"岗位使用且用工比例不超10%；落实同工同酬；派遣工工伤由派遣单位担责，用工单位未尽义务承担连带责任。"],"sev":"高"},{"id":"R-DISP-07","cat":"special_dispatch","catLabel":"劳务派遣","risk":"违法退回被派遣劳动者（触及第42条情形等）","level":"ask","owner":"legal","module":"staff","enabled":true,"q":"退回被派遣劳动者是否避开第42条禁止情形，并依法定退回情形处理？","law":[{"ref":"《劳务派遣暂行规定》第12、13条","text":"第12条　有下列情形之一的，用工单位可以将被派遣劳动者退回劳务派遣单位： （一）用工单位有劳动合同法第四十条第三项、第四十一条规定情形的； （二）用工单位被依法宣告破产、吊销营业执照、责令关闭、撤销、决定提前解散或者经营期限届满不再继续经营的； （三）劳务派遣协议期满终止的。 被派遣劳动者退回后在无工作期间，劳务派遣单位应当按照不低于所在地人民政府规定的最低工资标准，向其按月支付报酬。\n第13条　被派遣劳动者有劳动合同法第四十二条规定情形的，在派遣期限届满前，用工单位不得依据本规定第十二条第一款第一项规定将被派遣劳动者退回劳务派遣单位；派遣期限届满的，应当延续至相应情形消失时方可退回。"}],"consequence":"违法退回的，派遣/用工单位承担相应责任","remedy":["查验劳务派遣单位《劳务派遣经营许可证》；仅\"三性\"岗位使用且用工比例不超10%；落实同工同酬；派遣工工伤由派遣单位担责，用工单位未尽义务承担连带责任。"],"sev":"高"},{"id":"R-DISP-08","cat":"special_dispatch","catLabel":"劳务派遣","risk":"以承揽、外包之名行劳务派遣之实（假外包真派遣）","level":"ask","owner":"legal","module":"staff","enabled":true,"q":"是否存在以承揽、外包名义实际按劳务派遣形式用工的情形？","law":[{"ref":"《劳务派遣暂行规定》第27条","text":"第27条　用人单位以承揽、外包等名义，按劳务派遣用工形式使用劳动者的，按照本规定处理。"}],"consequence":"按本规定（劳务派遣）处理并处罚","remedy":["查验劳务派遣单位《劳务派遣经营许可证》；仅\"三性\"岗位使用且用工比例不超10%；落实同工同酬；派遣工工伤由派遣单位担责，用工单位未尽义务承担连带责任。"],"sev":"中"},{"id":"R-DISP-09","cat":"special_dispatch","catLabel":"劳务派遣","risk":"跨地区派遣未在用工单位所在地参保","level":"ask","owner":"legal","module":"staff","enabled":true,"q":"跨地区派遣劳动者是否在用工单位所在地参保，执行当地标准？","law":[{"ref":"《劳务派遣暂行规定》第18、19条","text":"第18条　劳务派遣单位跨地区派遣劳动者的，应当在用工单位所在地为被派遣劳动者参加社会保险，按照用工单位所在地的规定缴纳社会保险费，被派遣劳动者按照国家规定享受社会保险待遇。\n第19条　劳务派遣单位在用工单位所在地设立分支机构的，由分支机构为被派遣劳动者办理参保手续，缴纳社会保险费。 劳务派遣单位未在用工单位所在地设立分支机构的，由用工单位代劳务派遣单位为被派遣劳动者办理参保手续，缴纳社会保险费。"},{"ref":"《安全生产法》第61条","text":"第61条　生产经营单位使用被派遣劳动者的，被派遣劳动者享有本法规定的从业人员的权利，并应当履行本法规定的从业人员的义务。"}],"consequence":"未属地参保的，工伤等待遇风险由派遣/用工单位承担","remedy":["查验劳务派遣单位《劳务派遣经营许可证》；仅\"三性\"岗位使用且用工比例不超10%；落实同工同酬；派遣工工伤由派遣单位担责，用工单位未尽义务承担连带责任。"],"sev":"中"},{"id":"R-PART-01","cat":"special_parttime","catLabel":"非全日制","risk":"非全日制用工工时超标（日均>4小时或周累计>24小时）","level":"ask","owner":"hr","module":"staff","enabled":true,"q":"非全日制用工是否平均每日≤4小时、每周累计≤24小时（以劳动合同法第68条为准，优于2003年意见5/30）？","law":[{"ref":"《劳动合同法》第68条","text":"第68条　非全日制用工，是指以小时计酬为主，劳动者在同一用人单位一般平均每日工作时间不超过四小时，每周工作时间累计不超过二十四小时的用工形式。"},{"ref":"《关于非全日制用工若干问题的意见》第1项","text":"第1项　非全日制用工是指以小时计酬、劳动者在同一用人单位平均每日工作时间不超过5小时累计每周工作时间不超过30小时的用工形式。 从事非全日制工作的劳动者，可以与一个或一个以上用人单位建立劳动关系。用人单位与非全日制劳动者建立劳动关系，应当订立劳动合同。劳动合同一般以书面形式订立。劳动合同期限在一个月以下的，经双方协商同意，可以订立口头劳动合同。但劳动者提出订立书面劳动合同的，应当以书面形式订立。"}],"consequence":"超标可能被认定为全日制，需补全日制权利义务（合同、社保、解雇保护等）","remedy":["非全日制用工平均每日不超4小时、每周不超24小时；报酬不低于最低小时工资、结算周期不超15日；不得约定试用期；避免被认定事实劳动关系（全义务风险）。"],"sev":"高"},{"id":"R-PART-02","cat":"special_parttime","catLabel":"非全日制","risk":"与非全日制劳动者约定试用期","level":"ask","owner":"hr","module":"staff","enabled":true,"q":"是否与非全日制劳动者约定了试用期？","law":[{"ref":"《劳动合同法》第69、70条","text":"第69条　非全日制用工双方当事人可以订立口头协议。 从事非全日制用工的劳动者可以与一个或者一个以上用人单位订立劳动合同；但是，后订立的劳动合同不得影响先订立的劳动合同的履行。\n第70条　非全日制用工双方当事人不得约定试用期。"},{"ref":"《关于非全日制用工若干问题的意见》第3项","text":"第3项　非全日制劳动合同的内容由双方协商确定，应当包括工作时间和期限、工作内容、劳动报酬、劳动保护和劳动条件五项必备条款，但不得约定试用期。"}],"consequence":"约定试用期违法，应改正","remedy":["非全日制用工平均每日不超4小时、每周不超24小时；报酬不低于最低小时工资、结算周期不超15日；不得约定试用期；避免被认定事实劳动关系（全义务风险）。"],"sev":"中"},{"id":"R-PART-03","cat":"special_parttime","catLabel":"非全日制","risk":"非全日制小时工资低于最低标准或结算周期超15日","level":"ask","owner":"hr","module":"staff","enabled":true,"q":"非全日制小时计酬是否≥用人单位所在地最低小时工资，且结算周期最长≤15日？","law":[{"ref":"《劳动合同法》第72条","text":"第72条　非全日制用工小时计酬标准不得低于用人单位所在地人民政府规定的最低小时工资标准。 非全日制用工劳动报酬结算支付周期最长不得超过十五日。"},{"ref":"《关于非全日制用工若干问题的意见》第7、8项","text":"第7项　用人单位应当按时足额支付非全日制劳动者的工资。用人单位支付非全日制劳动者的小时工资不得低于当地政府颁布的小时最低工资标准。\n第8项　非全日制用工的小时最低工资标准由省、自治区、直辖市规定，并报劳动保障部备案。确定和调整小时最低工资标准应当综合参考以下因素：当地政府颁布的月最低工资标准；单位应缴纳的基本养老保险费和基本医疗保险费(当地政府颁布的月最低工资标准未包含个人缴纳社会保险费因素的，还应考虑个人应缴纳的社会保险费)；非全日制劳动者在工作稳定性、劳动条件和劳动强度、福利等方面与全日制就业人员之间的差异。小时最低工资标准的测算方法为： 小时最低工资标准＝〔（月最低工资标准÷20.92÷8）×（1＋单���应当缴纳的基本养老保险费和基本医疗保险费比例之和）〕×（1＋浮动系数）"}],"consequence":"低于标准需补足；结算超期违法","remedy":["非全日制用工平均每日不超4小时、每周不超24小时；报酬不低于最低小时工资、结算周期不超15日；不得约定试用期；避免被认定事实劳动关系（全义务风险）。"],"sev":"中"},{"id":"R-PART-04","cat":"special_parttime","catLabel":"非全日制","risk":"非全日制劳动者社会保险（尤其工伤）未依法缴纳","level":"ask","owner":"hr","module":"staff","enabled":true,"q":"是否依法为非全日制劳动者缴纳工伤保险（养老/医疗由个人身份参加）？","law":[{"ref":"《关于非全日制用工若干问题的意见》第10、11、12项","text":"第10项　从事非全日制工作的劳动者应当参加基本养老保险，原则上参照个体工商户的参保办法执行。对于已参加过基本养老保险和建立个人账户的人员，前后缴费年限合并计算，跨统筹地区转移的，应办理基本养老保险关系和个人账户的转移、接续手续。符合退休条件时，按国家规定计发基本养老金。\n第11项　从事非全日制工作的劳动者可以以个人身份参加基本医疗保险，并按照待遇水平与缴费水平相挂钩的原则，享受相应的基本医疗保险待遇。参加基本医疗保险的具体办法由各地劳动保障部门研究制定。\n第12项　用人单位应当按照国家有关规定为建立劳动关系的非全日制劳动者缴纳工伤保险费。从事非全日制工作的劳动者发生工伤，依法享受工伤保险待遇；被鉴定为伤残5－10级的，经劳动者与用人单位协商一致，可以一次性结算伤残待遇及有关费用。 四、关于非全日制用工的劳动争议处理"}],"consequence":"未缴工伤险期间发生工伤的，由用人单位支付待遇","remedy":["非全日制用工平均每日不超4小时、每周不超24小时；报酬不低于最低小时工资、结算周期不超15日；不得约定试用期；避免被认定事实劳动关系（全义务风险）。"],"sev":"中"},{"id":"R-PART-05","cat":"special_parttime","catLabel":"非全日制","risk":"终止非全日制用工未依法结清报酬","level":"ask","owner":"hr","module":"staff","enabled":true,"q":"终止非全日制用工是否即时结清劳动报酬（虽不支付经济补偿）？","law":[{"ref":"《劳动合同法》第70、71条","text":"第70条　非全日制用工双方当事人不得约定试用期。\n第71条　非全日制用工双方当事人任何一方都可以随时通知对方终止用工。终止用工，用人单位不向劳动者支付经济补偿。"}],"consequence":"未结清报酬的，劳动者可主张","remedy":["非全日制用工平均每日不超4小时、每周不超24小时；报酬不低于最低小时工资、结算周期不超15日；不得约定试用期；避免被认定事实劳动关系（全义务风险）。"],"sev":"低"}];
