window.QUIZ_DATA = [{"key":"recruit","label":"招聘","flow":"招聘","desc":"招聘阶段（禁童工/禁扣押证件/禁歧视/如实告知/劳动关系核实）","questions":[{"id":"R-RECRUIT-01","q":"招用人员时是否核查身份证并确认其已满16周岁？","sev":"高","law":"禁止使用童工规定第2、4条","risk":"招用人员未核查年龄，误招不满16周岁童工","consequence":"每使用一名童工每月处5000元罚款，并责令限期送回；文艺体育单位招专业工作者须监护人同意（第13条例外）","remedy":"规范招聘流程：核验身份证件（禁招不满16周岁童工）；不扣押证件、不收押金/保证金；招用简章必备法定内容；如实告知职业危害、安全生产状况与劳动报酬；录用前核实候选人已与原单位解除/终止劳动关系。"},{"id":"R-RECRUIT-02","q":"贵司是否扣押员工证件或收取任何形式的押金、保证金、担保？","sev":"高","law":"劳动合同法第9、84条；就业服务与就业管理规定第14条","risk":"扣押劳动者居民身份证或其他证件，或要求提供担保、以其他名义收取财物（押金/保证金）","consequence":"责令退还，按每人500–2000元罚款；造成损害的承担赔偿责任","remedy":"规范招聘流程：核验身份证件（禁招不满16周岁童工）；不扣押证件、不收押金/保证金；招用简章必备法定内容；如实告知职业危害、安全生产状况与劳动报酬；录用前核实候选人已与原单位解除/终止劳动关系。"}]},{"key":"interview","label":"面试","flow":"面试","desc":"面试阶段（禁止就业歧视/禁乙肝检测/知情权边界）","questions":[{"id":"R-INTERVIEW-01","q":"面试评判是否因性别、婚育状况、乙肝、户籍等与岗位无关因素而拒绝或抬高标准？","sev":"中","law":"就业促进法第26、27、28–31条；就业服务与就业管理规定第16、20条","risk":"面试中因性别、民族、残疾、传染病病原携带、农村身份等实施歧视或差别对待","consequence":"劳动者可起诉；造成损害的承担赔偿责任","remedy":"面试仅考察与岗位直接相关因素，杜绝性别、婚育、乙肝、户籍等歧视；不将乙肝病毒血清学指标作为体检或录用标准；不越界打探与合同无关隐私，同时单位应如实告知相关情况。"},{"id":"R-INTERVIEW-02","q":"是否将乙肝病毒血清学指标作为体检标准或录用前提？","sev":"中","law":"就业服务与就业管理规定第19条","risk":"将乙肝病毒血清学指标作为体检受录用标准","consequence":"责令改正，并可处1000元以下的罚款（情节严重者更高）","remedy":"面试仅考察与岗位直接相关因素，杜绝性别、婚育、乙肝、户籍等歧视；不将乙肝病毒血清学指标作为体检或录用标准；不越界打探与合同无关隐私，同时单位应如实告知相关情况。"},{"id":"R-INTERVIEW-03","q":"面试了解的信息是否限于与合同直接相关的基本情况，且单位已如实告知？","sev":"低","law":"劳动合同法第8条","risk":"超出与劳动合同直接相关范围打探隐私，或单位未如实告知相关情况","consequence":"知情权与告知义务失衡，易引发纠纷与经济补偿责任","remedy":"面试仅考察与岗位直接相关因素，杜绝性别、婚育、乙肝、户籍等歧视；不将乙肝病毒血清学指标作为体检或录用标准；不越界打探与合同无关隐私，同时单位应如实告知相关情况。"}]},{"key":"probation","label":"试用期","flow":"试用期","desc":"试用期阶段（期限/工资/解除/赔偿金）","questions":[{"id":"R-PROB-01","q":"试用期是否符合：合同<3月或以完成任务为期限不得约定；3月–1年≤1月；1–3年≤2月；3年以上及无固定≤6月；同一单位同一劳动者仅约定一次？","sev":"高","law":"劳动合同法第19条","risk":"违法约定试用期（期限超法定上限、对同一劳动者重复约定、对不应约定情形约定）","consequence":"违法约定且已履行的，按试用期满月工资就超期期间支付赔偿金（第83条）","remedy":"严格按合同期限约定试用期（3月以下/以任务为期限不得约定；3月–1年≤1月；1–3年≤2月；3年以上及无固定≤6月；同一单位同一劳动者仅一次）；试用期工资≥同岗最低档或约定80%且≥最低工资；解除须有录用条件不符证据，且不得对孕期女职工依第40/41条解除。"},{"id":"R-PROB-03","q":"试用期解除劳动合同是否有录用条件及不符证明，且未对孕期女职工依本条解除？","sev":"高","law":"劳动合同法第21条、第42条","risk":"试用期违法解除（无证据证明不符合录用条件、或依第40/41条解除、或解除孕期女职工）","consequence":"构成违法解除，按经济补偿标准2倍支付赔偿金或继续履行（第87条）","remedy":"严格按合同期限约定试用期（3月以下/以任务为期限不得约定；3月–1年≤1月；1–3年≤2月；3年以上及无固定≤6月；同一单位同一劳动者仅一次）；试用期工资≥同岗最低档或约定80%且≥最低工资；解除须有录用条件不符证据，且不得对孕期女职工依第40/41条解除。"}]},{"key":"entry_sign","label":"合同签订","flow":"入职","desc":"合同签订（书面合同/必备条款/无效情形/无固定期限）","questions":[{"id":"R-SIGN-01","q":"用工之日起是否在一个月内订立书面劳动合同？","sev":"高","law":"劳动合同法第10、82条；劳动合同法实施条例第5–7条；劳动保障监察条例第24条","risk":"用工之日起超过一个月未订立书面劳动合同","consequence":"超1月不满1年未订：自满1月次日至补订前一日付2倍工资；满1年视为已订无固定期限合同","remedy":"用工之日起1个月内订立书面劳动合同并双方各执一份；必备条款齐全（含职业危害防护、社保、劳动保护等）；不以欺诈胁迫或免除法定责任/排除劳动者权利条款订约；符合应订无固定期限情形的依法订立。"},{"id":"R-SIGN-05","q":"签订劳动合同时是否如实告知工作场所职业病危害及后果、防护措施？","sev":"高","law":"职业病防治法第33条","risk":"订立/变更合同时未如实告知职业病危害","consequence":"劳动者可解除合同并要求经济补偿；造成健康损害的依法赔偿","remedy":"用工之日起1个月内订立书面劳动合同并双方各执一份；必备条款齐全（含职业危害防护、社保、劳动保护等）；不以欺诈胁迫或免除法定责任/排除劳动者权利条款订约；符合应订无固定期限情形的依法订立。"},{"id":"R-SIGN-06","q":"劳动者连续工作满10年等法定情形出现时，是否依法订立无固定期限合同（除劳动者提出订固定）？","sev":"高","law":"劳动合同法第14条、第82条第2款；劳动合同法实施条例第11条","risk":"符合应订无固定期限合同情形却订固定期限（规避无固定）","consequence":"应订无固定而未订的，自应订之日起每月支付2倍工资","remedy":"用工之日起1个月内订立书面劳动合同并双方各执一份；必备条款齐全（含职业危害防护、社保、劳动保护等）；不以欺诈胁迫或免除法定责任/排除劳动者权利条款订约；符合应订无固定期限情形的依法订立。"}]},{"key":"entry_renew","label":"合同续订","flow":"入职","desc":"合同续订（无固定续订/法定顺延/期满终止补偿）","questions":[{"id":"R-RENEW-01","q":"合同到期且符合无固定期限条件时，是否依法续订无固定期限合同？","sev":"高","law":"劳动合同法第14条；劳动合同法实施条例第11条","risk":"应订无固定期限合同而拒不续订","consequence":"违法不订无固定，面临2倍工资等责任","remedy":"合同到期前评估续订；符合无固定期限条件依法续订（除劳动者提出订固定）；遇医疗期、三期、工伤停工留薪等法定顺延情形自动续延至消失；固定期限期满终止（非因单位维持或提高条件而劳动者拒绝）依法支付经济补偿。"},{"id":"R-RENEW-02","q":"合同期满时如劳动者处于医疗期、三期、工伤停工留薪等情形，是否续延至情形消失？","sev":"高","law":"劳动合同法第45条","risk":"合同期满但劳动者有第42条情形（医疗期、孕期产期哺乳期、工伤1–6级等）未续延","consequence":"违法终止，按经济补偿2倍赔偿或继续履行（第47、87条）","remedy":"合同到期前评估续订；符合无固定期限条件依法续订（除劳动者提出订固定）；遇医疗期、三期、工伤停工留薪等法定顺延情形自动续延至消失；固定期限期满终止（非因单位维持或提高条件而劳动者拒绝）依法支付经济补偿。"}]},{"key":"entry_perform","label":"合同履行","flow":"入职","desc":"合同履行（全面履行/报酬/条件/社保）","questions":[{"id":"R-PERFORM-04","q":"是否存在违章指挥/强令冒险作业，且未保障劳动者拒绝权？","sev":"高","law":"劳动合同法第32条；安全生产法第54条","risk":"违章指挥、强令冒险作业，未保障劳动者拒绝权","consequence":"劳动者拒绝不视为违约；造成损害的赔偿，严重的追究刑责（第88条）","remedy":"全面履行劳动合同约定：按时足额支付劳动报酬，提供约定劳动条件与劳动保护，依法缴纳社会保险，不擅自变更核心义务；劳动者据此可即时解除并主张经济补偿的情形应避免。"}]},{"key":"entry_change","label":"合同变更","flow":"入职","desc":"合同变更（协商变更/单方合理性）","questions":[{"id":"R-CHANGE-01","q":"变更劳动合同内容（岗位/地点/薪酬等）是否经双方协商一致并采用书面形式？","sev":"中","law":"劳动合同法第35条","risk":"未经协商一致擅自变更劳动合同（岗位、地点、薪酬等）","consequence":"单方变更无效，劳动者可主张恢复或解除并索补偿","remedy":"变更劳动合同（调岗调薪等）须与劳动者协商一致并采用书面形式；确需单方变更的须具合理性（经营必要、薪资相当、无侮辱惩罚）并留存证据，否则劳动者可拒绝并主张权利。"},{"id":"R-CHANGE-02","q":"单位合并分立后，是否由承继单位继续履行原劳动合同？","sev":"中","law":"劳动合同法第34条","risk":"用人单位合并、分立后拒不履行原劳动合同","consequence":"原合同继续有效，承继单位拒不履行的承担违约责任","remedy":"变更劳动合同（调岗调薪等）须与劳动者协商一致并采用书面形式；确需单方变更的须具合理性（经营必要、薪资相当、无侮辱惩罚）并留存证据，否则劳动者可拒绝并主张权利。"},{"id":"R-CHANGE-03","q":"劳动者非本人原因从原单位被安排到新单位，计算经济补偿时是否合并计算原单位工作年限？","sev":"中","law":"劳动合同法实施条例第10条","risk":"劳动者非因本人原因被安排到新单位，工作年限未合并计算","consequence":"年限不合并将少算经济补偿，面临补足责任","remedy":"变更劳动合同（调岗调薪等）须与劳动者协商一致并采用书面形式；确需单方变更的须具合理性（经营必要、薪资相当、无侮辱惩罚）并留存证据，否则劳动者可拒绝并主张权利。"}]},{"key":"entry_welfare","label":"法定福利","flow":"入职","desc":"法定福利（社保/公积金/工伤/生育）","questions":[{"id":"R-WELFARE-01","q":"用工之日起30日内是否办理社保登记并为职工办理社保登记？","sev":"高","law":"社会保险法第57、58条；社会保险费征缴暂行条例第4条","risk":"自用工之日起30日内未办理社会保险登记","consequence":"责令限期登记；逾期未改正可处罚款","remedy":"用工之日起30日内办理社保登记与增员，依法缴纳五险与住房公积金；发生工伤30日内申请认定；产假/生育依法申领待遇；禁止以现金补贴替代参保，不得签署\"不缴社保\"免责协议（无效）。"},{"id":"R-WELFARE-02","q":"是否自行申报、按时足额缴纳各项社会保险费（无缓减免法定事由）？","sev":"高","law":"社会保险法第60、63、86条；社会保险费征缴暂行条例第12、13条","risk":"未按时足额缴纳社会保险费","consequence":"责令限期补足，加收滞纳金；逾期处欠缴数额1–3倍罚款","remedy":"用工之日起30日内办理社保登记与增员，依法缴纳五险与住房公积金；发生工伤30日内申请认定；产假/生育依法申领待遇；禁止以现金补贴替代参保，不得签署\"不缴社保\"免责协议（无效）。"},{"id":"R-WELFARE-04","q":"是否存在虚构材料骗取社保待遇/基金支出的行为？","sev":"高","law":"社会保险法第88条；社会保险费征缴暂行条例第26条","risk":"骗取社会保险待遇或基金支出","consequence":"责令退回骗取的社会保险金，处骗取金额2–5倍罚款；构成犯罪的追究刑责","remedy":"用工之日起30日内办理社保登记与增员，依法缴纳五险与住房公积金；发生工伤30日内申请认定；产假/生育依法申领待遇；禁止以现金补贴替代参保，不得签署\"不缴社保\"免责协议（无效）。"}]},{"key":"entry_hours","label":"工时","flow":"入职","desc":"工时（标准工时/加班上限/特殊工时审批）","questions":[{"id":"R-HOURS-01","q":"安排加班是否控制：一般每日≤1小时、特殊≤3小时、每月≤36小时？","sev":"高","law":"劳动法第41、43条；关于职工工作时间的规定(1995修订)第6条；劳动保障监察条例第25条","risk":"违法延长工作时间（日超3小时、月超36小时，或特殊情况未控总量）","consequence":"警告、限期改正，并按受侵害劳动者每人100–500元罚款","remedy":"执行标准工时（每日8小时、每周40小时）；加班须事前审批并每月不超36小时；特殊工时须行政审批；排班与考勤留痕，不得通过不定时/综合计算工时规避加班费。"}]},{"key":"entry_wage","label":"工资","flow":"入职","desc":"工资（最低工资/足额支付/加班费/扣减）","questions":[{"id":"R-WAGE-01","q":"是否以货币形式按月足额支付工资，无克扣或无故拖欠？","sev":"高","law":"劳动法第50条；劳动合同法第30、85条；工资支付暂行规定第7、15条；劳动保障监察条例第26条；保障农民工工资支付条例第3、12条","risk":"克扣或无故拖欠劳动者工资","consequence":"责令限期支付；逾期不支付按应付金额50%–100%加付赔偿金","remedy":"工资不得低于当地最低工资；按月足额支付并保存支付记录至少2年；加班费按150%/200%/300%支付；扣减后余额不低于最低工资；因单位原因停工停产依法支付工资或生活费。"},{"id":"R-WAGE-02","q":"劳动者提供正常劳动后，工资（剔除加班费、特殊环境津贴、法定福利）是否≥当地最低工资？","sev":"高","law":"劳动法第48条；劳动合同法第85条；最低工资规定第3、5、12、13条；劳动保障监察条例第26条","risk":"支付的工资低于当地最低工资标准","consequence":"补发欠薪，并可处欠薪额1–5倍赔偿","remedy":"工资不得低于当地最低工资；按月足额支付并保存支付记录至少2年；加班费按150%/200%/300%支付；扣减后余额不低于最低工资；因单位原因停工停产依法支付工资或生活费。"},{"id":"R-WAGE-03","q":"平日加班是否≥150%、休息日≥200%（或补休）、法定休假日≥300%支付加班费？","sev":"高","law":"劳动法第44条；工资支付暂行规定第13条；劳动合同法第31、85条","risk":"安排加班未依法支付加班费或安排补休","consequence":"补足加班费；逾期不支付加付50%–100%赔偿金","remedy":"工资不得低于当地最低工资；按月足额支付并保存支付记录至少2年；加班费按150%/200%/300%支付；扣减后余额不低于最低工资；因单位原因停工停产依法支付工资或生活费。"}]},{"key":"entry_rest","label":"休息休假","flow":"入职","desc":"休息休假（周休/法定节假日/年休假）","questions":[{"id":"R-REST-04","q":"女职工生育是否享受不少于98天产假（难产、多胞胎相应增加）？","sev":"高","law":"女职工劳动保护特别规定第7条；劳动法第62条","risk":"女职工产假少于法定天数","consequence":"劳动保障监察按每人1000–5000元罚款（监察条例第23条）","remedy":"保障每周至少休息一日与全体公民法定节假日（共13天）；统筹安排或补发未休年休假工资（日工资×200%×未休天数）；休息日加班不能补休的支付200%工资。"}]},{"key":"entry_female","label":"女工","flow":"入职","desc":"女工（禁忌劳动/三期保护/产假哺乳）","questions":[{"id":"R-FEMALE-01","q":"是否避免安排女职工从事法定禁忌劳动，并对三期女职工调整禁忌岗位？","sev":"高","law":"劳动法第59–63条；女职工劳动保护特别规定第9–11条；职业病防治法第38条","risk":"安排女职工从事禁忌劳动（矿山井下、第四级体力劳动；经期/孕期/哺乳期第三级体力及冷水低温高处等）","consequence":"劳动保障监察按每人1000–5000元罚款（监察条例第23条）","remedy":"不安排女职工从事矿山井下、四级体力劳动强度等禁忌劳动；对孕期、哺乳期女职工调整禁忌岗位；产假、哺乳时间依法保障；不因结婚、怀孕、产假、哺乳降级降薪或违法解除。"},{"id":"R-FEMALE-02","q":"是否因女职工怀孕、生育、哺乳而降低工资、辞退或限制其晋级评优？","sev":"高","law":"女职工劳动保护特别规定第5条","risk":"因女职工怀孕、生育、哺乳降低工资、辞退或限制晋级评优","consequence":"违法，女职工可主张恢复、补薪及赔偿","remedy":"不安排女职工从事矿山井下、四级体力劳动强度等禁忌劳动；对孕期、哺乳期女职工调整禁忌岗位；产假、哺乳时间依法保障；不因结婚、怀孕、产假、哺乳降级降薪或违法解除。"},{"id":"R-FEMALE-06","q":"是否对处于孕期、产期、哺乳期的女职工依第40/41条解除或违法终止？","sev":"高","law":"劳动合同法第42条、第45条、第87条","risk":"违法解除/终止孕期、产期、哺乳期女职工（违反第42条）","consequence":"违法解除/终止，按经济补偿2倍赔偿或继续履行","remedy":"不安排女职工从事矿山井下、四级体力劳动强度等禁忌劳动；对孕期、哺乳期女职工调整禁忌岗位；产假、哺乳时间依法保障；不因结婚、怀孕、产假、哺乳降级降薪或违法解除。"}]},{"key":"entry_safety","label":"劳动安全卫生","flow":"入职","desc":"劳动安全卫生（制度/设施/防护/职业健康检查/工伤申报）","questions":[{"id":"R-SAFETY-01","q":"是否建立安全卫生制度，且新建/改建/扩建工程的安全卫生设施与主体工程同时设计、施工、投产？","sev":"高","law":"劳动法第52、53条；安全生产法第20、31条","risk":"未建立健全劳动安全卫生制度、安全卫生设施未「三同时」","consequence":"责令限期改正；导致事故的追究责任","remedy":"建立健全劳动安全卫生制度，安全卫生设施\"三同时\"；提供合格防护用品并培训；如实告知工作场所职业危害及后果、防护措施；组织岗前/岗中/离岗职业健康检查；事故伤害30日内申请工伤认定。"},{"id":"R-SAFETY-02","q":"是否提供符合国家标准/行业标准的劳动安全卫生条件和防护用品？","sev":"高","law":"劳动法第54条；安全生产法第45条；职业病防治法第22条","risk":"未提供符合规定的劳动安全卫生条件和必要的防护用品","consequence":"责令限期改正；造成健康损害的赔偿","remedy":"建立健全劳动安全卫生制度，安全卫生设施\"三同时\"；提供合格防护用品并培训；如实告知工作场所职业危害及后果、防护措施；组织岗前/岗中/离岗职业健康检查；事故伤害30日内申请工伤认定。"},{"id":"R-SAFETY-03","q":"从事特种作业的人员是否经专门培训并取得相应资格？","sev":"高","law":"劳动法第55条；安全生产法第30条","risk":"特种作业人员无证上岗","consequence":"责令限期改正，可处罚款；引发事故的追责","remedy":"建立健全劳动安全卫生制度，安全卫生设施\"三同时\"；提供合格防护用品并培训；如实告知工作场所职业危害及后果、防护措施；组织岗前/岗中/离岗职业健康检查；事故伤害30日内申请工伤认定。"}]},{"key":"leave_terminate","label":"合同解除","flow":"离职","desc":"合同解除（法定事由/违法解除2N/特殊保护/证明）","questions":[{"id":"R-TERM-01","q":"单方解除是否有法定事由（第39/40/41条），且事先通知工会、未触及第42条禁止情形？","sev":"高","law":"劳动合同法第39、40、41、42、43、87条；劳动合同法实施条例第18、19条","risk":"违法解除劳动合同（无合法事由、未履行通知工会程序、违反第42条）","consequence":"违法解除，按经济补偿2倍支付赔偿金或继续履行；赔偿金与经济补偿不兼得（实施条例第25条）","remedy":"解除须有法定事由与充分证据；违法解除按经济补偿2倍（2N）赔偿或继续履行；医疗期、三期、工伤等情形不得依第40/41条解除；解除时出具证明并办理档案/社保转移。"},{"id":"R-TERM-05","q":"裁员20人以上或占10%以上时，是否提前30日向工会/职工说明、听取意见并向劳动行政部门报告？","sev":"高","law":"劳动合同法第41条","risk":"经济性裁员程序违法（未提前30日向工会/全体职工说明、未报告）","consequence":"程序违法的裁员无效，按违法解除赔偿","remedy":"解除须有法定事由与充分证据；违法解除按经济补偿2倍（2N）赔偿或继续履行；医疗期、三期、工伤等情形不得依第40/41条解除；解除时出具证明并办理档案/社保转移。"},{"id":"R-TERM-06","q":"试用期解除是否证明不符合录用条件，且未对孕期女职工解除？","sev":"高","law":"劳动合同法第21、42条","risk":"试用期解除不符合法定条件（同 R-PROB-03，贯穿解除环节）","consequence":"违法解除，2倍赔偿或继续履行","remedy":"解除须有法定事由与充分证据；违法解除按经济补偿2倍（2N）赔偿或继续履行；医疗期、三期、工伤等情形不得依第40/41条解除；解除时出具证明并办理档案/社保转移。"}]},{"key":"leave_end","label":"合同终止","flow":"离职","desc":"合同终止（合法终止/顺延/经济补偿/证明转移）","questions":[{"id":"R-END-02","q":"合同期满时劳动者处于医疗期、三期、工伤1–6级等，是否续延至情形消失再终止？","sev":"高","law":"劳动合同法第45条","risk":"合同期满但劳动者有第42条情形未续延即终止","consequence":"违法终止，2倍赔偿或继续履行","remedy":"终止须合法；遇法定顺延情形续延至消失；固定期限期满终止依法支付经济补偿（N）；出具终止证明并办理档案与社保关系转移手续。"},{"id":"R-END-04","q":"接触职业病危害作业的劳动者离职时，是否先做离岗职业健康检查后再终止？","sev":"高","law":"职业病防治法第35条；劳动合同法第45条","risk":"对未进行离岗职业健康检查、或疑似职业病在诊断观察期的劳动者终止合同","consequence":"不得终止，违法终止按2倍赔偿","remedy":"终止须合法；遇法定顺延情形续延至消失；固定期限期满终止依法支付经济补偿（N）；出具终止证明并办理档案与社保关系转移手续。"}]},{"key":"leave_service","label":"服务期","flow":"离职","desc":"服务期（专项培训/违约金上限/期满延续）","questions":[{"id":"R-SERVICE-01","q":"服务期是否仅针对专项培训费用培训，且违约金不超过尚未履行部分所分摊的培训费用？","sev":"中","law":"劳动合同法第22、25条；劳动合同法实施条例第16、17条","risk":"违法约定服务期，或违约金超过实际培训费用","consequence":"超范围约定无效；违约金超限部分无效","remedy":"仅对提供专项培训费用的专业技术培训约定服务期；违约金不超过尚未履行部分所分摊的培训费用；劳动合同期满而服务期未满的延续至服务期满（另有约定除外）。"},{"id":"R-SERVICE-02","q":"合同期满而服务期未满的，是否延续至服务期满（除非双方另有约定）？","sev":"中","law":"劳动合同法实施条例第17条","risk":"劳动合同期满但服务期未届满，未延续至服务期满","consequence":"未延续致劳动者提前离职的争议","remedy":"仅对提供专项培训费用的专业技术培训约定服务期；违约金不超过尚未履行部分所分摊的培训费用；劳动合同期满而服务期未满的延续至服务期满（另有约定除外）。"},{"id":"R-SERVICE-03","q":"服务期违约金的支付与返还是否按「培训费用分摊+过错」规则明确？","sev":"低","law":"劳动合同法实施条例第26条","risk":"服务期违约金支付情形界定不清（谁违约、是否退费）","consequence":"约定不清易引发争议，按法定规则处理","remedy":"仅对提供专项培训费用的专业技术培训约定服务期；违约金不超过尚未履行部分所分摊的培训费用；劳动合同期满而服务期未满的延续至服务期满（另有约定除外）。"}]},{"key":"leave_noncompete","label":"竞业限制","flow":"离职","desc":"竞业限制（适用人员/期限/补偿/无效情形）","questions":[{"id":"R-NONCOMP-01","q":"竞业限制是否仅限高管、高技和其他负有保密义务人员，期限≤2年，范围地域合理？","sev":"中","law":"劳动合同法第23、24、25条","risk":"竞业限制人员范围过宽、期限超过2年或地域/范围不合理","consequence":"超范围/超期限约定可能被认定无效","remedy":"竞业限制限于高管、高级技术人员和其他负有保密义务人员，期限不超2年；解除或终止后按月支付补偿（不低于离职前12个月平均工资30%且不低于最低工资）；超期或主体不适格部分无效，超3个月未付补偿劳动者可解除。"},{"id":"R-NONCOMP-02","q":"离职后是否按月向履行竞业限制的劳动者支付经济补偿？","sev":"中","law":"劳动合同法第23条","risk":"约定竞业限制但未在离职后按月支付经济补偿","consequence":"未支付补偿达一定期限，劳动者可解除竞业限制约定","remedy":"竞业限制限于高管、高级技术人员和其他负有保密义务人员，期限不超2年；解除或终止后按月支付补偿（不低于离职前12个月平均工资30%且不低于最低工资）；超期或主体不适格部分无效，超3个月未付补偿劳动者可解除。"},{"id":"R-NONCOMP-03","q":"除服务期、竞业限制外，是否与劳动者约定由劳动者承担的违约金？","sev":"中","law":"劳动合同法第25条","risk":"违法约定劳动者违约金（超出服务期、竞业限制两类）","consequence":"该类违约金约定无效","remedy":"竞业限制限于高管、高级技术人员和其他负有保密义务人员，期限不超2年；解除或终止后按月支付补偿（不低于离职前12个月平均工资30%且不低于最低工资）；超期或主体不适格部分无效，超3个月未付补偿劳动者可解除。"}]},{"key":"leave_ip","label":"知识产权","flow":"离职","desc":"知识产权（职务发明/保密/交接/侵权）","questions":[{"id":"R-IP-01","q":"执行本单位任务或主要利用本单位物质技术条件完成的发明，是否归单位所有并给予奖励和合理报酬？","sev":"中","law":"专利法(2020修正)第6、15条；专利法实施细则(2023修订)第12条","risk":"职务发明创造权属与奖励报酬未落实","consequence":"权属争议；未给奖励报酬的，发明人可主张","remedy":"明确职务发明创造归属单位；约定保密义务与涉密载体管理；离职办理技术资料与涉密载体交接；不侵犯原单位知识产权与商业秘密。"},{"id":"R-IP-02","q":"劳动合同中是否约定保守商业秘密条款，并对违约泄密追责？","sev":"中","law":"劳动法第22、102条；劳动合同法第23条","risk":"未约定保密义务，或劳动者违反保密约定造成损失","consequence":"违反保密约定造成损失，承担赔偿责任","remedy":"明确职务发明创造归属单位；约定保密义务与涉密载体管理；离职办理技术资料与涉密载体交接；不侵犯原单位知识产权与商业秘密。"},{"id":"R-IP-03","q":"离职员工1年内作出的与原单位任务相关的发明，是否按职务发明处理？","sev":"低","law":"专利法实施细则(2023修订)第12条","risk":"离职后1年内作出的与原任务相关的发明权属不清","consequence":"权属争议风险","remedy":"明确职务发明创造归属单位；约定保密义务与涉密载体管理；离职办理技术资料与涉密载体交接；不侵犯原单位知识产权与商业秘密。"}]},{"key":"special_dispatch","label":"劳务派遣","flow":"特殊用工","desc":"劳务派遣（资质/三性/10%比例/同工同酬/工伤责任）","questions":[{"id":"R-DISP-01","q":"合作的劳务派遣单位是否取得行政许可且注册资本≥200万元？","sev":"高","law":"劳动合同法第57条","risk":"劳务派遣单位无行政许可或注册资本不足200万元即经营派遣","consequence":"未经许可经营派遣，依法处罚并没收违法所得","remedy":"查验劳务派遣单位《劳务派遣经营许可证》；仅\"三性\"岗位使用且用工比例不超10%；落实同工同酬；派遣工工伤由派遣单位担责，用工单位未尽义务承担连带责任。"},{"id":"R-DISP-02","q":"派遣岗位是否确属临时性(≤6月)/辅助性/替代性，且派遣用工≤用工总量10%？","sev":"高","law":"劳动合同法第66条；劳务派遣暂行规定第3、4条","risk":"劳务派遣用工超出「三性」岗位或超过用工总量10%比例","consequence":"违反的，按劳动合同法第92条处罚","remedy":"查验劳务派遣单位《劳务派遣经营许可证》；仅\"三性\"岗位使用且用工比例不超10%；落实同工同酬；派遣工工伤由派遣单位担责，用工单位未尽义务承担连带责任。"},{"id":"R-DISP-03","q":"派遣单位是否订2年以上固定期限合同、按月付酬、不克扣用工单位付酬、不向劳动者收费？","sev":"高","law":"劳动合同法第58、60条；劳务派遣暂行规定第5、6、8条","risk":"派遣单位未订2年以上固定期限合同、克扣工资或向劳动者收费","consequence":"违反按第92条处罚；克扣工资等承担赔偿责任","remedy":"查验劳务派遣单位《劳务派遣经营许可证》；仅\"三性\"岗位使用且用工比例不超10%；落实同工同酬；派遣工工伤由派遣单位担责，用工单位未尽义务承担连带责任。"}]},{"key":"special_parttime","label":"非全日制","flow":"特殊用工","desc":"非全日制（工时/报酬/结算/无试用期/事实劳动风险）","questions":[{"id":"R-PART-01","q":"非全日制用工是否平均每日≤4小时、每周累计≤24小时（以劳动合同法第68条为准，优于2003年意见5/30）？","sev":"高","law":"劳动合同法第68条；关于非全日制用工若干问题的意见第1条","risk":"非全日制用工工时超标（日均>4小时或周累计>24小时）","consequence":"超标可能被认定为全日制，需补全日制权利义务（合同、社保、解雇保护等）","remedy":"非全日制用工平均每日不超4小时、每周不超24小时；报酬不低于最低小时工资、结算周期不超15日；不得约定试用期；避免被认定事实劳动关系（全义务风险）。"}]}];
